#                        "상승 구간은 최저점 이후 최대한 근처에서 비중을 늘려 매수, 최고점에선
#                        더 일찍 회피, 하락 중 저점 접근 시 매수, buy-and-hold보다 높은 수익"과
#                        FRED API 키 설정을 요청.
#
#                        [v1.10.0 실사용 검증 — fast-trigger 대성공] 2020년 전략 -10.0%→+7.8%
#                        (+17.8pp), 전략 MDD -24.3%→-9.31%, 전체 CAGR 9.1%→11.4%, 샤프 0.906→
#                        1.391. 2022 방어(+16.4pp)·MDD(-5.44%) 불변(§E 수용기준 충족). 06c
#                        민감도: 0.95/0.97 동률 최적(12개 추가 발동이 상태 무변화), 0.90/0.99
#                        열위 — 기본값 0.97 유지 근거 실측 확인. 단 여전히 buy-and-hold에 뒤짐
#                        (11.4% vs 14.6%) — 오탐률 실측이 잔여 격차의 정체를 폭로: 트리거
#                        발동일 이후 21일 시장수익 중앙값 +4.6%(양수비율 73%). 즉 트리거는
#                        최악 구간을 피하게 하지만 패닉 종료 후 반등을 못 타면 이득을 도로
#                        반납한다. 재진입을 막던 3중 자물쇠(01시트): 점수 저공비행(0.08~0.24)
#                        + 추세오버라이드(가격<200MA) + H 고공(0.7+)의 매수보류게이트.
#
#                        [SignalLayer §A ⚠ 신호(위험) 파라미터] 규칙 ⑤ 회복 승격 신설 — 이번
#                        라운드 유일한 신호 메커니즘 변경(§9). 신규 Config 3필드: USE_RECOVERY_
#                        FLOOR=True, RECOVERY_LOW_WINDOW=120, RECOVERY_CONFIRM_PCT=0.05.
#                        종가가 최근 120거래일 저점 대비 +5% 이상 회복 & 그 날 급락트리거·
#                        haz_enter 침묵이면 RISK_OFF를 최소 중립(0.5)으로 승격. 규칙 ③과 달리
#                        가격>200MA 불요(2020-03~05형 200MA 아래 V반등에서 동작), 추세오버라이드
#                        보다 후순위 적용으로 이를 해제 가능. 승격은 매수보류게이트(규칙 ④)
#                        적용 제외 — report10 실측상 승격 대상일 225일 중 166일(74%)이 H>0.70
#                        이라 제외 없이는 규칙이 무력화되며(2020-04·2023 전부), +5% 가격 확인
#                        + 트리거/ENTER 침묵이 게이트의 목적(위험 상승 중 매수 차단)을 대신
#                        수행한다. "하락 중 저점 접근 시 매수"는 저점을 미리 아는 것(룩어헤드)
#                        이라 불가능 — 저점 대비 +5% 반등 확인 직후 매수가 인과적으로 가능한
#                        최선이며 실측 첫 승격일이 이를 증명: 2020-03-30(3-23 저점 후 4거래일),
#                        2025-04-14(4-08 저점 후 4거래일), 2019-01-02, 2026-04-08. 1차 근사
#                        기여(report10 일 단위): 2020 +6.7pp/2023 +4.5pp/2019 +1.6pp/2026
#                        +1.1pp, 2022 -0.2pp(방어 무손상 — §E 충족 예상), 합계 +10.1pp.
#                        ⚠ 정직 고지: 기본값(120, 0.05)은 사전 근거(6개월 참조창·노이즈 초과
#                        확인폭) 우선으로 정했고 1차 근사가 확인 — 같은 표본 관찰이라 선택편향
#                        잔존 가능성 명시, 06c 민감도(0.03/0.05/0.07/0.10)로 강건성 사후 검증.
#                        "최고점에서 더 일찍 회피"의 잔여분은 A-3(비대칭 히스테리시스)로 다음
#                        라운드 이월(§9 — 한 커밋 한 메커니즘).
#
#                        [Config] FRED_API_KEY 기본값에 사용자 제공 키 설정 — 설정 시 JSON
#                        API를 CSV보다 먼저 시도(v1.1.1 경로, 수집 안정성 향상). 키는 로그에
#                        출력되지 않음(확인 완료).
#
#                        [ReportLayer §A] 06c에 RECOVERY_CONFIRM_PCT 단독 민감도 4케이스
#                        (0.03/0.05/0.07/0.10, 기준선=규칙 ⑤만 끔, event=recovery_floor_
#                        sensitivity). 01시트에 회복확인(저점대비)·회복승격(R) 컬럼, 00시트에
#                        규칙 ⑤ 설명 행. threshold_sensitivity() 기존 격자 전부에 recov_conf
#                        전달(살아있는 설정 기준 일관화).
#
#                        [검증] 신규 test_recovery_floor_v111.py(6개 테스트): 기본값·§9 불변,
#                        2020-04형 재진입(점수 저공·200MA 아래·H 고공에서 승격), 게이트 제외
#                        상호작용, 트리거/ENTER 발동일 승격 금지, 하위호환 3경로, 회복 확인
#                        불리언 산출식. 기존 회귀 17종 재실행 회귀 없음. e2e 스모크 01/06c
#                        신규 컬럼 배선 확인. py_compile 매 편집 후.
#
#                        [이월] A-3(비대칭 히스테리시스 — 고점 조기 회피 잔여분)·A-2(ΔH 속도)·
#                        뉴스 기반 후보지표·실행시간 벡터화. buy-and-hold 역전 여부는 규칙 ⑤의
#                        실측 효과(다음 실행) 확인 후 판단 — 1차 근사 +10pp가 실현되면 CAGR
#                        약 12.5~13%대로 격차(14.6%) 상당 부분 축소 예상이나 확정은 실측으로만.
#
#  v1.10.0 | 2026-09-02 | 사용자가 v1.9.0 실행 결과(market_regime_report_9.xlsx, SIGNAL_START=
#                        2018 첫 실행)를 제출하며 "05b 시트를 보니 큰 하락 회피·큰 상승 참여가
#                        잘 안 된다. 원인 분석해서 개선하라. 등락률 큰 것은 반드시 맞춰야 하고
#                        특히 하락은 반드시 회피 — 정확히 하락 전날이 아니라 좀 더 일찍 회피해도
#                        된다"고 요청. 계획서 §D 순서 1번(v1.8 §A-1, v1.9 §D-1)인 fast-trigger를
#                        구현한다(⚠ 이번 라운드 유일한 신호 메커니즘 변경 — §9 준수).
#
#                        [진단 핵심 — 2018 확장이 드러낸 최대 결함] 07시트: 2020년 전략 -10.0%
#                        vs 시장 +18.3%(-28.4pp), 전략 MDD -24.3%가 2020-02~03 코로나 급락에서
#                        발생. 01시트 실측 실패 사슬: (i) 수익트랙 복합점수 백분위가 급락 내내
#                        0.82~0.99 — 패닉성 금리인하가 금리계열 지표에 호재로 찍혀 매크로 점수가
#                        '지연'이 아니라 '역방향'으로 상승, (ii) H백분위 0.29(02-19)→0.854
#                        (03-13, 고점 후 17거래일·시장 -20% 후에야 ENTER 도달), (iii) 그 사이
#                        H가 0.70 부근 진동으로 차단 해제 → 03-09(-7.6% 당일) 풀포지션 ADD,
#                        (iv) 하락 확정 후엔 매크로 점수 붕괴+추세오버라이드로 V반등(+17%/+15%/
#                        +7% 구간) 전량 미참여. 같은 '빠른 이벤트 무방비'가 2018-02(-10.1%,
#                        0.5 통과), 2019-07(-6.0%, 1.0), 2020-06(-7.0%, 1.0), 2024-08 엔캐리
#                        (-6.1%, 0.5)에서 반복 — 05b 집계: -5% 이상 하락 35건 중 '감축 없음
#                        (보유 통과)' 10건, 지연 감축 9건(지연 4~17일).
#
#                        [SignalLayer §A ⚠ 신호(위험) 파라미터] 규칙 ⓪ 급락 fast-trigger 신설.
#                        신규 Config 3필드: USE_FAST_TRIGGER=True, FAST_TRIGGER_INDICATOR=
#                        "VIX_TERM", FAST_TRIGGER_PCT=0.97. run()이 지정 지표의 위험방향
#                        (사전방향 부호 반전) expanding rank 백분위(fast_pct)를 산출해
#                        generate_signals()에 전달, fast_pct>0.97인 날 raw_state를 즉시
#                        RISK_OFF로 강제(규칙 ① haz_enter의 OR 조건 — 합성 H 희석과 무관).
#                        발동일은 규칙 ③(안전판) 적용 제외 — 급락 초입(가격>200MA·H<0.70,
#                        2020-02-24~28 실측)에서 안전판이 트리거를 되돌리는 것을 방지.
#                        지표·임계값 근거(격자 최적화 아님): VIX_TERM은 옵션 헤지수요의 현물
#                        선행이라는 사전 메커니즘 + 위험트랙 AUC엣지 상위(0.142)로 이미 검증된
#                        기존 지표 재사용(§E 신규지표 금지 저촉 없음). 0.97은 expanding 분포
#                        상위 3%(연 ~7일)의 극단 꼬리로 통상 -2~3% 조정에는 침묵하도록 사전
#                        설계(0.90은 연 ~25일 과다, 0.99는 중형 쇼크 누락 위험). 이력현상·
#                        최소보유일은 변경하지 않음(비대칭 히스테리시스는 A-3, 별도 라운드).
#                        USE_FAST_TRIGGER=False 또는 fast_pct=None이면 v1.9.0과 비트 단위
#                        동일(하위호환). 지표 부재/데이터 전무 시 경고 후 비활성 진행(§5).
#
#                        [ReportLayer §A] 06c에 FAST_TRIGGER_PCT 단독 민감도 4케이스(0.90/
#                        0.95/0.97/0.99, 기준선=트리거만 끈 상태, event=fast_trigger_
#                        sensitivity) + 오탐률 컬럼(발동 후 21거래일 시장수익 중앙값·양수비율
#                        — 사후 진단용 forward 통계, 신호 미재사용). 01시트에 급락트리거백분위·
#                        급락트리거(FT) 컬럼, 00시트에 규칙 ⓪ 설명 행 신규. threshold_
#                        sensitivity()의 기존 격자 전부에 fast_pct 전달(살아있는 설정 기준으로
#                        ENTER/BLOCK/FLOOR/게이트 효과를 측정하도록 일관화).
#
#                        [검증] 신규 test_fast_trigger_v110.py(6개 테스트): 기본값·백분위 방향
#                        (prior_sign=+1 지표는 낮은 값=위험), 2020-02형 상황 재현(트리거 발동
#                        → 하락 강제), 안전판 제외 상호작용(H<0.70·가격>200MA에서도 RISK_OFF
#                        유지), 매수보류게이트 무간섭(하향 전환은 미보류), 하위호환 3경로
#                        (USE_FAST_TRIGGER=False/fast_pct=None/지표 부재), 임계값 경계(0.97
#                        같음=미발동, 초과=발동). 기존 회귀 17종 재실행 회귀 없음. e2e 스모크
#                        01/06c 신규 컬럼 배선 확인. py_compile 매 편집 후.
#
#                        [이월] 큰 상승 참여(2019 -9.3pp/2021 -13.0pp/회복장 0.5 고착)는 B-2/
#                        C-1 축으로 다음 라운드 단독 처리(§9). A-3(비대칭 히스테리시스)·A-2
#                        (ΔH 속도)는 fast-trigger 실사용 효과 확인 후. 실행시간 1,648초(§B
#                        벡터화)·SOFR/IORB 이월 지속.
#
#  v1.9.0 | 2026-09-02 | 사용자가 v1.8.0 실행 결과(market_regime_report_8.xlsx)를 제출하며
#                        (1) "일별 예측을 2018년부터 하는걸로 변경" (2) "-2% 이상 하락 구간 /
#                        재하락 없는 상승 구간을 표로 정리해 하락 전 매도·상승 전(저점 부근)
#                        매수를 했는지 판정, 지금도 그런지 확인" (3) 예측 실패 원인 분석과
#                        개선 방법 보고를 요청. (1)(2)는 코드로 구현, (3)은 IMPROVEMENT_PLAN_
#                        v1.9.md에 분석·개선안으로 정리(신호 로직 변경 없음 — 이번 라운드는
#                        신호 파라미터 0개 변경).
#
#                        [v1.8.0 실사용 검증 — 매수보류게이트] report8 실측으로 B-1의 목표 달성
#                        확인: 01시트 게이트 발동 7일(2026-07-14 H=0.817, 2026-08-05~12
#                        H=0.71~0.79) — v1.7.0에서 손실이던 #13(H=0.877 매수, -0.6%)·#14
#                        (H=0.77 매수) 두 휩쏘 거래가 정확히 제거/지연됨(거래 14→13건).
#                        우려했던 #8(2023-11-21, +14.5% 최대 승리거래) 지연은 발생하지 않음
#                        (신호확정일 H가 0.70 이하였음 — 게이트는 확정일 H를 보므로 집행일
#                        H=0.71과 무관). CAGR 12.57→12.59%, 샤프 1.760→1.766, MDD -6.73% 불변.
#                        06c 신규 민감도: 0.70→12.59%/0.75→12.65%/0.80→12.71%/0.85→12.57%
#                        (0.85는 발동 0일 = 게이트 소멸로 휩쏘 복귀) — 0.75~0.80이 근소 우위나
#                        §9(격자 최적 셀 채택 금지)에 따라 의미론 근거가 있는 0.70 유지.
#                        단, 2026-08 재진입 건은 게이트 지연(08-05→08-14)이 진입가를 약 1.1%
#                        올려 이번 건에 한해 불리했음을 정직하게 기록(순효과는 위 수치대로 양).
#
#                        [Config §A ⚠ 평가구간 파라미터] SIGNAL_START 2022-01-03 → 2018-01-02.
#                        사용자 명시 요청. 신호 생성 규칙·임계값·검증게이트는 일절 변경 없음 —
#                        백테스트/일별기록/백분위 마스크 시작일만 앞당김. 2018-02 변동성 쇼크,
#                        2018-Q4, 2020-03 코로나, 2020~21 회복장이 평가구간에 포함됨. ⚠ 비용:
#                        월간 재추정 횟수 약 57→105회로 06_워크포워드재추정이 기존 ~1,240초의
#                        약 1.7~2배(35~40분대)로 늘 것으로 예상 — §B 벡터화 이월 항목의 우선
#                        순위 상승을 CHANGELOG에 명시.
#
#                        [ReportLayer §B] drawdown_episodes() 신설 + 05b_하락상승구간 시트.
#                        종가 기준 대칭 ±2%(Config.DRAWDOWN_EPISODE_THRESHOLD) 지그재그로 전체
#                        구간을 하락(고점→저점)/상승(저점→고점) 구간으로 분할하고, 구간별
#                        시작시/10일전/최소/평균 비중, 첫 대응일과 지연 거래일수, 구간 전략/
#                        시장 수익률, 판정(선행 감축/기간내 감축(지연N)/무포지션 통과/감축
#                        없음(보유 통과) · 저점 풀보유/매수(저점 후 N일, 상승분 x% 지점)/증액
