#                        확인(2024 엔캐리: 고점·저점비중 1.0/1.0(v1.4.0)→0.5/0.5, 방어폭 대폭
#                        개선). 이 확인 과정에서 §A와는 독립된 새로운 구조적 게이트 문제를
#                        03시트에서 추가로 발견해 이번 라운드에 §A와 동일한 최소변경 원칙으로
#                        구현했다(§B 실행시간 벡터화·§C fast-trigger는 여전히 코드 변경 없음
#                        — 이월 사유는 IMPROVEMENT_PLAN_v1.5.md §B/§C 그대로 유효).
#
#                        [진단 핵심] `03_지표검증` 실측: 짧은이력이 아닌(커버리지(가중) ~1.000,
#                        데이터 문제 전혀 없는) 30개 지표(DGS2/DGS10/DGS30/MORTGAGE30US/ANFCI/
#                        BOGMBASE/CPILFESL/PCEPILFE/DFF/DTWEXBGS/M2SL/STLFSI4/T5YIE/T10YIE/
#                        DFII10 등 금리·인플레이션·달러·금융환경 계열)가 위험트랙AUC엣지
#                        0.05~0.18(HAZARD_MIN_AUC_EDGE=0.05를 통과)인데도 "AUC 방향안정성
#                        2/4 < 3"(또는 2/3 < 3) 사유로만 위험트랙 FAIL했다. 원인: _hazard_
#                        track_verdict()의 구간안정성 게이트가 여전히 표준트랙과 공유하는
#                        cfg.MIN_SUBPERIOD_AGREE(=3, 4구간 초다수결)를 그대로 썼기 때문 —
#                        v1.4.0 §3(a)에서 엣지게이트(MIN_AUC_EDGE→HAZARD_MIN_AUC_EDGE)만
#                        분리했을 뿐 "커버리지·구간안정성 게이트는 변경하지 않는다"고 명시적
#                        으로 남겨둔 부분이었다. 그런데 이 지표군은 1990~2026을 4등분한 서로
#                        다른 통화정책 국면(1990년대 긴축→2008 GFC→2010년대 ZIRP→2022년 이후
#                        긴축)에 걸쳐 "금리/인플레이션 상승=위험"이라는 방향 자체가 국면마다
#                        자연히 뒤집힐 수 있다 — 표준트랙(수익률 IC 방향)에는 3/4 초다수결이
#                        적절하지만, 애초에 "AUC 방향이 IC 방향과 다를 수 있다"는 지표를
#                        구제하기 위해 신설된 위험트랙(v1.3.0 §4)에 그대로 적용하는 것은 설계
#                        취지와 맞지 않았다.
#
#                        [CompositeLayer §A ⚠ 검증게이트 파라미터] 신규 Config.HAZARD_MIN_
#                        SUBPERIOD_AGREE=2(4구간 중 과반) — 표준트랙 Config.MIN_SUBPERIOD_
#                        AGREE=3은 전혀 건드리지 않는다(v1.4.0 §3(a)와 동일한 최소변경 패턴).
#                        0(무조건 통과)이 아니라 2로 둔 이유: 실측에서 0/4·1/4로 방향이 아예
#                        불안정한 지표(PERMIT_CHG120 0/4, UNRATE_Z 1/4 등)는 2 기준에서도
#                        여전히 FAIL해야 하고 단위테스트로 실제 그렇게 동작함을 확인(게이트
#                        무력화 아님). validate_indicators()의 지표별 루프에서 표준트랙용
#                        eff_min_subperiod_agree(기존, 불변)와 별개로 위험트랙 전용
#                        eff_min_subperiod_agree_haz를 새로 계산해(짧은이력 지표는 기존처럼
#                        MIN_SUBPERIOD_AGREE_SHORT_HISTORY=1이 그대로 우선 적용 — 이번 변경의
#                        영향을 받지 않음, SOFR/IORB처럼 짧은이력허용목록 밖의 신생시리즈 2종은
#                        유효구간이 1개뿐이라 이번 완화로도 구제되지 않음 — 별도 사안, 이번
#                        라운드 범위 밖) _hazard_track_verdict() 호출에 전달한다.
#                        03시트에 "위험트랙유효최소구간일치수" 컬럼 신규(표준트랙용 "유효최소
#                        구간일치수"와 분리 노출), VALIDATE 로그에 min_agree_eff_haz 필드 추가,
#                        실행 요약에 event=hazard_subperiod_relax_summary 신규(이 변경으로
#                        새로 PASS 전환된 지표수·코드 목록) — 완화 효과를 매 실행 로그로 추적
#                        가능하게 함.
#
#                        [검증] 신규 test_hazard_subperiod_relax.py(4개 테스트): TEST1 Config
#                        기본값(MIN_SUBPERIOD_AGREE=3 불변/HAZARD_MIN_SUBPERIOD_AGREE=2 신규)
#                        확인. TEST2 _hazard_track_verdict() 오버라이드로 agree=2가 threshold=3
#                        에서 FAIL·threshold=2에서 PASS로 뒤집히고, agree=1은 threshold=2에서도
#                        여전히 FAIL함을 확인(게이트 무력화 아님). TEST3(핵심) report5.xlsx의
#                        국면전환 패턴을 재현한 합성데이터(전체이력 커버리지=1.0, 오래된 절반=
#                        약한 반대신호/최근 절반=강한 정방향신호 — 감쇠가중이 최근을 지배하므로
#                        전체표본 AUC엣지는 정방향으로 유의하게 나오면서도 4구간 중 2구간만
#                        명확히 일치하는 패턴을 만듦)로 validate_indicators()를 직접 호출 —
#                        표준트랙 유효최소구간일치수(3, 불변)와 위험트랙유효최소구간일치수(2,
#                        신규)가 서로 다르게 계산되고, 위험트랙판정이 FAIL→PASS로 정확히
#                        뒤집힘을 확인. TEST4 짧은이력 지표는 위험트랙에서도 MIN_SUBPERIOD_
#                        AGREE_SHORT_HISTORY(1)를 그대로 쓰고 이번 신설값(2)의 영향을 받지
#                        않음을 확인(우선순위 보존). 기존 회귀테스트 7종(test_hazard_verdict/
#                        test_hazard_topk/test_weighted_coverage/test_series_cap/test_hazard_
#                        weight_period/test_generate_signals_hazard/test_short_history_gate_
#                        relax) 전부 재실행, 회귀 없음 확인(test_short_history_gate_relax.py의
#                        일반지표 위험트랙 FAIL 사유 문구가 "< 3"에서 "< 2"로 바뀐 것은 의도된
#                        변경 — 여전히 FAIL이라는 결론 자체는 동일해 테스트 통과 유지).
#                        test_hazard_e2e_small.py(SELF_TEST 전체 run() 파이프라인) 재실행해
#                        예외 없이 정상 완료 확인. py_compile 매 편집 후 확인.
#
#                        [이번 라운드도 보류, 코드 변경 없음] §B(실행시간 벡터화)·§C(fast-
#                        trigger 하저드 개념)는 IMPROVEMENT_PLAN_v1.5.md에 남긴 이월 사유가
#                        그대로 유효 — 검증 안 된 변경을 서두르지 않는다는 원칙, 정확성(1) >
#                        성능(3) 우선순위. log5.txt 실측으로도 06_워크포워드재추정이
#                        1,197.83초(96.3%)로 v1.4.0/v1.5.0과 동일하게 지배적임을 재확인(이번
#                        라운드는 게이트 로직만 손댔으므로 런타임 영향은 무시할 수준이어야
#                        정상이고, 실측이 그것과 일치함).
#  v1.5.0 | 2026-09-01 | 사용자가 v1.4.0 실행 결과(market_regime_report_4.xlsx, log4.txt)를
#                        검토 요청 — "시장 상황을 제대로 예측하는지, 지표 검증에서 중요한
#                        지표가 통과 못 했는지, 지표가 부족한지, 무엇보다 하락을 잘 회피하는지
#                        확인하고 이번엔 진단만이 아니라 실제로 코드를 고쳐달라"는 요청에 따라
#                        IMPROVEMENT_PLAN_v1.5.md를 작성하고 §A(BAML/신용스프레드 검증게이트
#                        완화)를 실제로 구현했다(§B 실행시간 벡터화·§C "fast-trigger" 하저드
