#
#                        [진단 핵심] 03_지표검증 시트 실측: HY_OAS_CHG20/HY_OAS_LEVEL/IG_OAS_
#                        CHG20 및 BAML 자동생성 파생지표(BAMLH0A0HYM2_Z 등)가 위험트랙AUC엣지
#                        0.10~0.2943(위험트랙 임계 HAZARD_MIN_AUC_EDGE=0.05를 2~6배 상회 —
#                        하락판별력이 결코 약하지 않음)인데도 전원 FAIL. 판정사유 확인 결과
#                        원인은 통계적 유의성 부족이 아니라 서로 독립적인 두 개의 구조적 게이트:
#                          (a) 가중커버리지 상한 — HALF_LIFE_DAYS=913(반감기) 감쇠에서, 시리즈가
#                              실제로 W일만 존재하면 100% 밀도로 채워도 weighted_coverage <=
#                              1 - 0.5**(W/913)의 수학적 상한이 걸린다. BAML 9종은 FRED가 서버
#                              측에서 2023-09-01부터만 제공(v1.4.0 §2에서 이미 "단축이력 수용"
#                              대상으로 확정)하므로 W≈1095일 -> 상한 ≈0.565, MIN_COVERAGE=0.60을
#                              데이터 품질과 무관하게 항상 밑돈다(실측 03시트 가중커버리지
#                              0.498~0.561로 정확히 이 상한과 부합).
#                          (b) 부호일치구간수 — validate_indicators()는 DATA_START(1990)~현재
#                              전체이력을 4등분(blocks)해 부호안정성을 보는데, 2023-09 이후에만
#                              데이터가 있는 시리즈는 4구간 중 1구간에만 유효값이 있어
#                              MIN_SUBPERIOD_AGREE=3(4구간 중 3구간 이상)을 원천적으로 만족할
#                              수 없다(실측 판정사유 "부호안정성 1/1 < 3"). (a)와 완전히 독립된
#                              두 번째 구조적 게이트 — 하나만 고쳐서는 해소되지 않음.
#
#                        [CompositeLayer §A ⚠ 검증게이트 파라미터] 신규 Config 필드 MIN_COVERAGE_
#                        SHORT_HISTORY=0.45, MIN_SUBPERIOD_AGREE_SHORT_HISTORY=1(FRED_ALLOW_
#                        SHORT_HISTORY 정의부 바로 아래, 위 (a)(b) 증명과 report4.xlsx 실측치를
#                        주석에 명시) — 이 값을 넘지 못하면(예: 커버리지가 완화하한 0.45조차
#                        밑돌면) 여전히 FAIL한다(게이트 삭제가 아니라 완화 — 무분별한 통과 방지,
#                        test_short_history_gate_relax.py TEST4로 확인). 신규 순수함수
#                        _is_short_history_indicator(spec, cfg) — 기존 SERIES_WEIGHT_CAP
#                        그룹키 판정(spec.base_series or (spec.series_id if spec.auto else ""))을
#                        그대로 재사용해 FRED_ALLOW_SHORT_HISTORY 소속 여부를 판정(이미 검증된
#                        패턴 재사용 — 새 버그 표면적 최소화). validate_indicators()의 지표별
#                        루프에서 매 지표마다 이 판정으로 유효임계값(eff_min_coverage/eff_min_
#                        subperiod_agree)을 계산해 (i) 표준트랙 커버리지·부호안정성 게이트,
#                        (ii) _hazard_track_verdict()에 신규 오버라이드 파라미터(min_coverage/
#                        min_subperiod_agree, None이면 기존과 100% 동일 — 하위호환)로 전달해
#                        위험트랙 게이트, (iii) _select_and_weight_period()의 보조채택(soft-
#                        adopt) 커버리지 필터(기존엔 고정 cfg.MIN_COVERAGE라 정식게이트와
#                        모순 가능 — 03시트의 지표별 "유효최소커버리지" 컬럼을 그대로 재사용해
#                        일관되게 함) 3곳 모두에 일관 적용. 세 수기 지표(HY_OAS_CHG20/_LEVEL,
#                        IG_OAS_CHG20)에 base_series="BAMLH0A0HYM2"/"BAMLC0A0CM" 명시(이전엔
#                        미지정이라 이 판정에서도, 기존 SERIES_WEIGHT_CAP 그룹핑에서도 누락돼
#                        있었다 — 더 보수적인 방향으로만 바뀌므로 회귀 위험 없음).
#
#                        [ReportLayer §A 정직성] 03시트에 지표별 "짧은이력완화적용"(bool),
#                        "유효최소커버리지", "유효최소구간일치수" 3컬럼 신규 — 완화가 "몰래"
#                        적용되지 않도록 어떤 지표에 어떤 값이 실제로 쓰였는지 노출. VALIDATE
#                        로그에 short_hist/min_cov_eff/min_agree_eff 필드 추가, 실행 요약에
