#                        통계치를 가진 두 지표 중 base_series만 다르게 설정했을 때 일반 지표는
#                        표준·위험 트랙 모두 FAIL(가중 커버리지 56%<60% / 부호안정성 1/1<3),
#                        짧은이력 지표는 두 트랙 모두 PASS로 정확히 뒤집힘을 확인 — "중요한
#                        지표가 게이트 탓에 통과 못 하던 문제"가 실제로 해소됐다는 직접 증거.
