#                        이미 "A" 사용).
#
#                        [PerfLayer §1(B)] validate_indicators()에 full_report: bool = True,
#                        fwd_full: Optional[Dict[int, pd.Series]] = None 파라미터 신규(정확성
#                        영향 0 — 단위테스트로 확인, /tmp/test_validate_indicators_perf_equiv.py
#                        4개 eval_end 절단시점 × 10개 핵심컬럼 diff<1e-9). full_report=False면
#                        PASS/FAIL·가중치 산정에 쓰이는 평가지평(h_eval) IC 1개만 계산(워크포워드
#                        전용 호출에서 IC 계산량 1/3). fwd_full은 forward_return()을 전체이력
#                        1회만 계산해두고 재추정마다 재인덱싱+마지막 h일 강제 NaN 마스킹으로 절단
#                        재계산과 동일한 결과를 냄(마스킹을 빼먹으면 룩어헤드가 되므로 이 동치성이
#                        핵심 검증 대상). build_walkforward_weights()가 이 두 옵션으로 호출.
#                        [중요한 발견] forward_maxdd()(dd_label)는 같은 방식(dd_label_full 전역
#                        계산+마스킹)으로 재사용을 시도했으나, rolling(h, min_periods=max(3,h//3))
#                        의 부분윈도우 특성 때문에 절단 재계산과 하락AUC 등에서 실제 수치 차이
#                        (최대 0.0017)가 발생함을 단위테스트로 발견 — 사용자 지침 우선순위
