#                        벡터화(계획서 §1(B)3)는 이번 구현에서 보류 — 위 두 항목만으로 워크포워드
#                        단계가 자기서술 시간모델 기준 목표(~300초대) 근접이 기대되고, 벡터화는
#                        효과 대비 리스크가 커 정확성 우선 원칙상 별도 검증 사이클로 분리.
#
#                        [PerfLayer §1(C)] fetch_fred() 재작성 — ① 실패 네거티브 캐시: 확정 제외된
