#                        전략을 건너뜀(이번 로그에서 CSV 36회 전부 ConnectionError — 경로 자체가
#                        막힌 환경). ③ JSON 2경로가 동일한 무결성실패 메시지를 반환하면 재시도
#                        라운드를 생략(skip_retry_round)하고 §2 단축이력 판정으로 즉시 이동. 단위
#                        테스트 /tmp/test_fetch_fred_v14.py(4그룹: 단축이력 수용/비허용목록 제외
#                        유지/네거티브캐시 스킵/CSV회로차단 有无API키 2케이스) 전부 통과.
#
#                        [DataLayer §2] _check_fred_integrity() 반환형 Tuple[bool,str]→Tuple[str,str]
#                        (하위호환 깨짐 — 호출부 1곳(fetch_fred) 확인 후 갱신)로 변경, "OK"/"SHORT"/
