#                        — FRED가 서버측에서 짧게(3년) 제공하는 것이지 장애가 아니므로, 이 목록의
#                        시리즈는 늦은 시작일이어도 "SHORT"로 즉시 수용한다(제외가 아니라 수용).
#                        10_데이터품질에 "[단축이력]" 접두(기존 "[FRED제외]"와 구분, 실제 수집
#                        행수/범위 노출)로 표시, 00시트 FRED 수집률 문구에 "(그중 단축이력 N개)"
#                        병기 — 단축이력 수용은 수집 성공에 포함되지만 "제외 아님"을 감추면 정직성
#                        원칙에 어긋나므로 명시.
#
#                        [CompositeLayer §3(a) ⚠ 신호(위험) 파라미터] 해저드 트랙 희석 해소.
#                        _hazard_track_verdict()의 엣지게이트를 공유 cfg.MIN_AUC_EDGE(0.03) 대신
#                        신규 전용 cfg.HAZARD_MIN_AUC_EDGE(기본 0.05)로 분리(커버리지·구간안정성
#                        게이트는 변경 없음 — 최소변경 원칙). _select_and_weight_hazard_period()에
#                        신규 Config HAZARD_TOP_K(기본 15) 압축 로직 추가: 게이트 통과 지표가
#                        HAZARD_TOP_K를 초과하면 |위험트랙AUC엣지| 내림차순 상위 K개만 채택(미만
#                        이면 있는 그대로, 인위적 패딩 없음) — 판정(게이트)과 압축(TOP_K)을 분리해
#                        두 파라미터 효과를 로그(event=hazard_topk_applied)에서 독립 추적 가능.
#                        08시트 워크포워드 기록에 "위험게이트통과수"(TOP_K 적용 전 원본 통과수)
#                        컬럼 추가 — "위험채택지표수"와의 차이로 압축 폭을 시트에서 바로 확인.
#                        단위테스트 /tmp/test_hazard_topk.py(5케이스: K초과시 정확히 K개+상위엣지
#                        일치, K미만시 패딩없이 전부, 가중치 정규화·부호 검증, K값에 따른 채택수
#                        변화·부분집합관계, 게이트전원FAIL시 안전처리) 전부 통과. self_test()의
#                        기존 §4(D) 해저드판별력 케이스(AUC=0.5613)도 새 HAZARD_MIN_AUC_EDGE=0.05
#                        기준을 여전히 통과함을 확인(회귀 없음).
#
#                        [SignalLayer §4.2 ⚠ 신호(위험) 파라미터] PCT_RISK_ON 0.50→0.60. 06c
