#                        따라 격자 최적값(0.70)이 아닌 중간값 0.60을 채택하고 선택편향 가능성을
#                        여기 명시(같은 표본에서 관찰된 수치). 정당화는 사전에 세울 수 있는 비대칭
#                        원칙 — "100% 비중(POS_RISK_ON) 진입에는 50%(중립) 진입보다 강한 확신
