#                        보류(§9: 한 커밋에 신호 파라미터 2개 이상 동시 변경 금지 — 이번 커밋은
#                        PCT_RISK_ON 단독). generate_signals()의 event=generated 로그에 pct_risk_on/
#                        pct_risk_off 실제 적용값 병기(효과 실행별 추적).
