#                        [ReportLayer §6] ① 00시트 "위험트랙 채택 지표수"를 전체기간 합집합(예:
#                        175개, 항상 커서 매 시점 실제 채택 규모를 가림)에서 wlog 기반 "최신
#                        재추정 기준 채택수 + 기간 중 범위(min~max)"로 교체(합집합 목록은 참고
#                        정보로 문구 뒤에 유지). ② 06c 해저드 격자에 "상태변경일수(vs미적용)"
#                        컬럼 신규 — 위험트랙을 완전히 끈 기준(base) 상태 대비 실제로 국면이
#                        바뀐 일수를 조합마다 계산(base는 조합과 무관해 1회만 계산). 0에 가까우면
#                        그 (ENTER,BLOCK) 조합이 사실상 발동하지 않은 "죽은 규칙"임을 격자만
#                        보고 바로 확인 가능. ③ event_study()에 haz_pct 파라미터 추가, 이벤트별
#                        "H백분위 T-20/T-5/저점시점" 3컬럼 신규 — 해저드 트랙이 각 급락에 실제로
#                        반응했는지 이벤트 단위 확인(§3 개선 효과의 사후 검증 도구). ④ run()에
#                        stage_timing 딕셔너리 신규(단계별 time.time() 체크포인트, 순수 계측 코드
#                        — 기존 로직/반환값 영향 없음), build_report()가 00시트에 "실행시간 - N_
#                        단계명" 행을 단계별로 1행씩 추가(§1 진단표와 동일 단계 구분) — §1(A)·(B)·
#                        (C) 성능개선 효과를 재실행 리포트만 보고 바로 확인 가능.
#
#                        [버그수정] write_excel()의 열너비 자동계산이 Series.astype(str)을 썼는데,
#                        pandas의 이 메서드는 열 전체가 NaN이면 NaN을 문자열 'nan'으로 바꾸지
#                        않고 float NaN 그대로 남기는 특성이 있어(.map(str)과 다른 동작), 그 결과
#                        .str.len().max()가 NaN이 되고 int(NaN)에서 ValueError로 리포트 저장 전체가
