#                        (1) SPY 가격이 실제로는 RSP였고 여러 티커가 상장 전 데이터를 가진 교차오염
#                        발견, (2) BAML 신용스프레드 9계열이 2023-09부터만 존재(절단), (3) 284개 중
#                        6개만 PASS, (4) 하락을 사전에 회피하지 못함(추세필터로만 사후 대응) 4가지
#                        문제를 진단하고 IMPROVEMENT_PLAN_v1.2.md로 정리한 뒤 전 항목을 구현했다.
#                        사용자 요구사항: 매매판단 2022년~현재, 예측일이 지나면 그 데이터도 학습에
#                        추가(일 단위 expanding), 오래된 데이터는 영향만 줄이고 최신 데이터에 비중
#                        — 세부 수치/범위는 위임받아 결정.
#
#                        [DataLayer-Yahoo] fetch_all_yahoo(): v1.1.0의 ThreadPoolExecutor 병렬
#                        yf.download() 호출이 원인이었다(yfinance 내부가 스레드 안전하지 않아 티커 간
#                        데이터가 뒤섞임) -> 앱 레벨 스레딩을 제거하고 yfinance 자체의 다중종목 배치
#                        API(단일 호출, group_by="ticker", threads=True 내부위임)로 교체. 실패 종목만
#                        순차 폴백. validate_price_data() 신규: (a) YAHOO_EXPECTED_START 대비 실제
#                        시작일이 PRICE_START_TOLERANCE_DAYS 이상 늦으면 그 티커 제외, (b) 종가가
#                        99% 이상 일치하는 티커 쌍을 교차오염으로 판정해 둘 다 제외, (c) 매매대상
#                        SPY가 (a)에 해당하거나 가격범위/일변동성이 비정상이면 즉시 RuntimeError로
#                        중단(다른 티커는 제외만 하고 계속 진행). CACHE_SCHEMA_VERSION=2로 캐시
#                        파일명에 버전 태그를 넣어 기존 오염 캐시를 자동 무효화.
#
#                        [DataLayer-FRED] fetch_fred()/_fetch_fred_json(): JSON/CSV 두 엔드포인트
#                        모두 조회기간(observation_start/end, cosd/coed)을 명시하지 않아 서버가
#                        임의 범위(최근 구간)만 반환한 것이 BAML 9계열 절단의 원인으로 추정 —
#                        DATA_START~end를 양쪽에 명시. _check_fred_integrity() 신규: FRED_EXPECTED_START
#                        대비 FRED_START_TOLERANCE_DAYS 이상 늦으면 1회 자동 재시도 후 그래도
#                        실패하면 해당 시리즈만 제외(캐시 쓰기는 무결성 통과 후에만).
#
#                        [ValidationLayer] IndicatorSpec에 eval_horizon(지표별 평가지평)·trend_track
#                        (추세필터 트랙 여부) 필드 추가. 200일선/12-1모멘텀 등 후행 추세지표는 짧은
#                        지평(21일)에서 평균회귀로 부호가 반전되던 문제를 eval_horizon=63일 지정으로
#                        해소하고, trend_track=True 지표는 IC/NW-t 게이트를 면제(AUC+구간안정성만
#                        적용) — 뒤늦게 반응하는 지표 특성상 IC/t값이 원래 약하기 때문. MIN_ABS_TSTAT를
#                        2.00→1.65로 완화(방향을 사전 경제이론으로 이미 특정한 일방검정이므로 임계값을
#                        1.645(95% 단측)에 맞춤 — 종전 2.00은 양측검정 기준을 일방검정에 오적용한 것).
#                        build_walkforward_weights(): 보조채택(soft-adoption) 신규 — 엄격 PASS가
#                        MIN_INDICATORS(3) 미만이면 FAIL 중 커버리지·사전방향 일치 지표를 |IC| 순
#                        최대 SOFT_ADOPT_MAX(5)개까지 가중치 50% 할인 적용해 보충(신호 공백 방지,
#                        기준 자체를 낮추는 게 아님). TREND_TRACK_WEIGHT_CAP(30%) 신규 — 추세트랙
#                        지표군의 절대가중치 합이 상한을 넘으면 축소 후 선행지표군에 재분배해
#                        후행지표가 '선행지표 기반 조기경보'라는 목적을 압도하지 않도록 함.
#
#                        [CompositeLayer] build_walkforward_weights()를 "매년 1월" 고정 루프에서
#                        재추정 경계일(_reestimation_boundaries) 기반으로 일반화 —
#                        SIGNAL_START 이전은 WARMUP_REWEIGHT_FREQ(연1회, 기존과 동일), 이후는
#                        REWEIGHT_FREQ(D/W/M)로 재추정. 매 재추정마다 decay_weights()로 그 시점
#                        (asof=train_end, 룩어헤드 차단 위해 매번 재계산)까지의 전체 이력에 지수감쇠
#                        표본가중(w=0.5^(age_days/HALF_LIFE_DAYS))을 적용해 spearman_ic/
#                        newey_west_tstat(WLS-HAC 새드위치)/auc_downside(가중 Mann-Whitney, 동순위
#                        보정)를 가중 버전으로 계산 — weights=None이면 기존과 100% 동일한 코드경로
#                        (하위호환, 단위테스트로 검증). N_eff=(Σw)²/Σw² < N_EFF_MIN(500)이면 그
#                        재추정을 건너뛰고 직전 가중치를 이어붙임(불안정한 재추정 방지).
#                        03/04시트용 val_full은 더 이상 SIGNAL_START 이후로 제한하지 않고 전체
#                        이력+감쇠가중(asof=최종일자)을 사용 — 실제 walk-forward와 동일한 방법론으로
#                        일치시킴(신호 생성에는 재사용되지 않으므로 룩어헤드 아님).
#                        lookahead_audit()에 감쇠가중 IC 감사 1건 추가(§4.4) — asof가 실수로
#                        고정일자가 되는 회귀를 자동으로 잡아냄.
#                        [버그수정-단위] 최초 설계는 HALF_LIFE_DAYS=630을 "약 2.5년"이라 문서화했으나
#                        이는 거래일(연 252일) 환산치였다. decay_weights()는 달력일 기준으로 age를
#                        계산하므로 630 달력일은 실제로는 약 1.73년 반감기였다(의도보다 훨씬 빠른
#                        감쇠) — 06d 시트 라벨을 자동계산하며 발견. 달력일 기준 진짜 2.5년인
#                        913일(2.5*365.25)로 수정, 06d의 세 케이스도 548/913/1461일(1.5/2.5/4년)로
#                        동일하게 수정.
#                        [성능-실측 후 기본값 변경] 최초 설계는 REWEIGHT_FREQ 기본값을 "W"(주1회, 약
#                        12분 예상)로 뒀으나, 실제 구현(가중치 계산 추가 + expanding 학습창이 재추정
#                        마다 계속 커짐)을 합성데이터로 실측한 결과 SIGNAL_START~현재 전체를 "W"로
#                        돌리면 30분을 넘을 수 있음을 확인 — 기본값을 "M"(월1회, 실측 약 4~5분)로
#                        변경(정확도 저하 아닌 재추정 '빈도'만 조정, "W"/"D"는 여전히 선택 가능).
#
#                        [ReportLayer] 03_지표검증에 검증트랙/평가지평/N_eff/IC_평가지평 컬럼 추가
#                        (어떤 지표가 어느 트랙·지평으로 통과했는지 감사 가능). 04_채택근거상세에
#                        트랙별 요약 문구 추가. 05_이벤트스터디에 사전경고 지표수/비율(T-60/20/5)
#                        집계 컬럼 추가(§5.1). 09_국면통계의 서술형 경고를 00_실행요약의 명시적
#                        PASS/FAIL 수용기준("국면정의 검증(수용기준)")으로 승격(§5.2). 06d_반감기민감도
#                        시트 신규 — HALF_LIFE_DAYS 4케이스(1.5/2.5/4년/감쇠없음)로 walk-forward
#                        전체를 재실행해 곡선맞춤 여부 자가점검(cfg.RUN_HALF_LIFE_SENSITIVITY로 토글,
#                        기본 True). 00_실행요약에 가중치 산정/시간감쇠 가중 방법론 라인 갱신.
#                        신규 지표는 추가하지 않음(문제는 개수가 아닌 데이터 품질/검증기준이었음) —
#                        차기 후보만 코드 주석으로 메모(CBOE 풋콜비율/NYSE 신고가-신저가/FINRA
#                        마진부채/MOVE지수, §5.3).
#
#                        [검증] 합성데이터 self_test(): 판별력 3/3(true_lead) / 0/4(pure_noise) 유지,
#                        룩어헤드 감사 13/13 OK(신규 감쇠IC 감사 포함), 신규 보조채택/추세트랙상한/
#                        N_eff 건너뛰기 로직은 몽키패치 기반 단위테스트로 별도 검증. self_test()는
#                        REWEIGHT_FREQ="A"로 고정 실행(SIGNAL_START를 1997로 앞당겨 30년 합성이력을
#                        검증하는 기존 설계와 기본값 "M"이 겹치면 재추정이 과도해지므로 — 판별력은
#                        재추정 주기와 무관해 이 오버라이드가 self_test 결과에 영향 없음).
#                        데이터 무결성(Yahoo/FRED) 수정은 실제 네트워크가 필요해 이 샌드박스에서는
#                        라이브 검증 불가 — 사용자 Colab 재실행에서 10_데이터품질 시트로 확인 필요
#                        (기대: SPY 시작 ≤1995, BAML 시작 ≤1998, 프레임 중복 0건).
#  v1.1.1 | 2026-09-01 | [DataLayer] fetch_fred()/_http_session(): 사용자 Colab 실행 로그(log2.txt)에서
#                        FRED CSV 엔드포인트(fred.stlouisfed.org)가 매 시리즈마다 100% 타임아웃되고
#                        JSON API(api.stlouisfed.org)는 매번 즉시 성공하는 패턴 확인. 원인 2가지:
#                        (1) HTTPAdapter의 urllib3 Retry(total=FETCH_RETRIES)와 fetch_fred()의 수동
#                        재시도 루프가 이중으로 겹쳐 시리즈 1개당 최악 9회의 25초 타임아웃(약 237초)을
#                        허비 후에야 JSON 폴백으로 넘어갔음 -> 어댑터 레벨 재시도를 끄고(total=0)
#                        재시도는 수동 루프 한 곳으로 단일화. (2) FRED_API_KEY가 있는데도 항상 CSV를
#                        먼저 시도한 뒤 실패해야 JSON으로 넘어가는 순서였음 -> 키가 있으면 JSON API를
#                        먼저 시도하고, CSV는 키가 없거나 JSON도 실패했을 때만 쓰는 폴백으로 순서 변경.
#                        (54개 FRED 시리즈 전체 다운로드가 기존 20분 이상 -> JSON 우선 시 수 초 내로
#                        단축될 것으로 예상. 샌드박스 네트워크 제약상 라이브 검증은 사용자 Colab에서 필요)
#  v1.1.0 | 2026-09-01 | [DataLayer] FRED 순차호출 타임아웃 연쇄실패 수정 — ThreadPoolExecutor 병렬
#                        다운로드(fetch_all_yahoo/fetch_all_fred), 재시도/타임아웃 단축(Session+
#                        HTTPAdapter/Retry), 선택적 FRED JSON API 키 폴백 추가.
#                        [IndicatorLayer] 지표 유니버스 22 -> 284개로 확장 (MacroSeries 52종 x
#                        level_z/chg(5,20,60,120일) + CrossAssetSeries 12종 x mom(5,20,60,120일),
#                        MACRO_SERIES/CROSS_ASSET_SERIES 로부터 IndicatorSpec 자동생성
#                        _generate_universe_indicators(), build_indicators()에 규칙기반 자동계산
#                        루프 추가. 섹터 지표(XLY_XLP_MOM, SMH_SPY_MOM)는 섹터 레이어 별도 예정으로
#                        제외(CURATED_YAHOO 주석에 재추가 방법 기재).
#                        [ValidationLayer] validate_indicators()에 compute_quintiles 옵션 추가 —
#                        walk-forward 연차 재검증(26~28회)에서 PASS/FAIL 미반영 필드인 5분위
#                        계산을 생략해 지표 수 13배 증가에 따른 성능 저하 방지.
#  v1.0.5 | 2026-08-31 | [ReportLayer] build_report(): 감사 표본이 30개 미만이라 lookahead_audit()이
#                        '일치' 컬럼 없는 1행 안내 DataFrame을 반환할 때, .get("일치")=="OK" 가
#                        스칼라 False를 만들어 뒤의 .all() 호출이 AttributeError로 실패하던 버그 수정.
#                        (Colab 실전 실행에서 재현·보고됨)
#  v1.0.4 | 2026-08-31 | [EventStudy] event_study(): 구간 최고가/최저가 대신 '최대낙폭 쌍'으로
#                        고점·저점을 탐지. 회복이 큰 구간에서 고점이 구간 끝에 잡혀 하락 사건이
#                        소멸하던 문제 수정. '구간종료일 회복률' 컬럼 추가.
#  v1.0.3 | 2026-08-31 | [SignalLayer] 채택지표 3개 미만 구간을 '현금'이 아닌 200일선 추세필터로
#                        폴백(TREND_ONLY_IN/OUT). 기존에는 검증 초기 수년간 무조건 현금이 되어
#                        장기 상승분을 놓쳤다. (합성데이터 자체검증에서 NO_SIGNAL 1,826일 발견)
#                        [ReportLayer] 09_국면통계에 '국면정의 검증' 자동판정 컬럼 추가 —
#                        위험선호 국면의 익일수익률이 위험회피보다 실제로 높은지 기계적으로 확인.
#  v1.0.2 | 2026-08-31 | [SignalLayer] generate_signals(): 이력현상 streak 카운터 버그 수정.
#                        기존에는 streak 을 확정상태(cur)와 비교해 매일 1로 초기화 -> 국면 전환이
#                        사실상 봉쇄되어 36년간 전환 4회/거래 1회만 발생. 직전 raw_state 와
#                        비교하도록 수정. (합성데이터 자체검증에서 발견)
#                        [SignalLayer] 국면 임계값을 복합점수 절대값 -> expanding 백분위 기준으로 변경.
#                        채택 지표 구성에 따라 점수 스케일이 달라지는 문제 제거.
#                        [ValidationLayer] threshold_sensitivity(): 임계값 격자 민감도 시트(06c) 추가.
#                        [CompositeLayer] 가중치 산출을 SIGNAL_START 이전부터 워밍업(백분위 안정화).
#  v1.0.1 | 2026-08-31 | [AuditLayer] 룩어헤드 감사에서 FRED 발표지연을 동일하게 재적용하도록 수정
#                        (감사 대상에 발표지연 처리 자체를 포함)
#  v1.0.0 | 2026-08-31 | 최초 작성
#          - [DataLayer]        yfinance + FRED CSV(무키) 로더, 로컬 캐시, 발표지연(publication lag) 반영
#          - [IndicatorLayer]   5개 카테고리 22개 후보 지표 (변동성/신용/금리·매크로/크로스에셋/추세·내부)
#          - [ValidationLayer]  Spearman IC, Newey-West t, 5분위 스프레드/단조성, 하락 AUC,
#                               4구간 부호 안정성, 커버리지 -> PASS/FAIL 자동 판정
#          - [CompositeLayer]   expanding z-score(룩어헤드 차단) + 연 1회 walk-forward 가중치 재추정
#          - [SignalLayer]      3단계 포지션(0/0.5/1.0) + 이력현상(hysteresis) + 200MA 오버라이드
#          - [BacktestLayer]    t일 종가 신호 -> t+1일 시가 체결(정확한 open-split 수익률 분해), 거래비용
#          - [ReportLayer]      11개 시트 Excel (일별로그/거래/지표검증/이벤트스터디/성과/연도별/가중치/데이터품질)
#          - [AuditLayer]       룩어헤드 재계산 감사 + 합성데이터 SELF_TEST
