from typing import Callable, Dict, List, Optional, Tuple

import numpy as np
import pandas as pd

warnings.filterwarnings("ignore")

# =============================================================================
# [0] 실행 설정 (CONFIG)
# =============================================================================
@dataclass
class Config:
    # ---- 매매 대상 ------------------------------------------------------
    TRADE_TICKER: str = "SPY"          # 미국 시장 대표 티커 (S&P500 ETF)
    # ---- 기간 -----------------------------------------------------------
    DATA_START: str = "1990-01-01"     # 데이터 수집 시작 (지표 워밍업 포함)
    # [v1.2.0] 사용자 요청: 매매 판단/평가는 2022년부터. 학습(검증·가중치·z-score)은
    # DATA_START(1990)부터 매 시점까지의 전체 이력을 시간감쇠 가중으로 계속 사용한다.
    # [v1.9.0 §A ⚠ 평가구간 파라미터 — 신호 '로직'은 무변경] 사용자 요청("일별 예측을 2018년부터
    # 하는걸로 변경")에 따라 2022-01-03 → 2018-01-02(2018년 첫 거래일). 신호 생성 규칙·임계값은
    # 그대로이며 백테스트/일별기록/백분위 마스크의 시작일만 앞당긴다. 효과: 2018-02 변동성 쇼크,
    # 2018-Q4 금리 급락장, 2020-03 코로나 급락, 2020~2021 회복장이 평가구간에 새로 포함돼
    # 하락/상승 구간 예측력(05b 시트)을 더 긴 표본으로 검증 가능. ⚠ 비용: SIGNAL_START 이후는
    # 월 1회 재추정(REWEIGHT_FREQ="M")이라 재추정 횟수가 약 57회→105회로 늘어 06_워크포워드
    # 재추정 실행시간이 기존 ~1,240초에서 약 1.7~2배(대략 35~40분대)로 증가할 것으로 예상됨
    # (§B 벡터화 이월 항목의 우선순위가 그만큼 올라감 — CHANGELOG v1.9.0 명시).
    SIGNAL_START: str = "2018-01-02"   # 실제 매매신호 시작 [v1.9.0: 2022-01-03 → 2018-01-02]
    DATA_END: Optional[str] = None     # None = 오늘
    # ---- 체결 -----------------------------------------------------------
    EXEC_MODE: str = "next_open"       # t일 종가 신호 -> t+1일 시가 체결
    COST_BPS: float = 5.0              # 편도 거래비용 (bp, 수수료+슬리피지)
    # ---- 포지션 ---------------------------------------------------------
    POS_RISK_ON: float = 1.00
    POS_NEUTRAL: float = 0.50
    POS_RISK_OFF: float = 0.00
    # 복합점수의 절대 스케일은 채택지표 구성에 따라 달라지므로,
    # '자기 자신의 과거 분포 대비 백분위'로 국면을 정의한다(expanding rank, 룩어헤드 없음).
    # [v1.4.0 §4.2 ⚠ 신호(위험) 파라미터] 0.50 -> 0.60. IMPROVEMENT_PLAN_v1.4.md §4 진단:
    # report3.xlsx 06c 임계값민감도 격자에서 PCT_RISK_ON=0.50이 전 행(0.85~0.95 구간)에서
    # MDD가 가장 나쁜 셀이었고, 0.60~0.70이 0.50을 일관되게 지배함을 확인 — 단일 셀의 우연이
    # 아니라 구조적 패턴. 단, 같은 표본에서 관찰한 수치이므로 §9 금지사항("격자 최적 셀을
    # 그대로 채택 금지")에 따라 격자 최적값 0.70이 아닌 중간값 0.60을 채택하고, 이 선택에
    # 잔존하는 선택편향 가능성을 여기 및 CHANGELOG에 명시한다. 정당화 근거는 데이터마이닝이
    # 아니라 사전에 세울 수 있는 비대칭 원칙: "포지션 100%(POS_RISK_ON) 진입에는 50%(중립)
    # 진입보다 더 강한 확신 증거를 요구한다"는 것 — 복합점수 백분위 상위 50%라는 절반 확률
    # 이벤트만으로 풀베팅하던 기존 기준이 애초에 느슨했다는 해석과 일치한다.
    # [v1.4.0 §4.2] 선택(2)안(HYSTERESIS_DAYS_UPGRADE, 상향전환만 확인일수 3일로 강화)은
    # 계획서상 "2로 부족할 때만" 적용하는 조건부 항목이므로, 이번 구현에서는 보류하고 §3(a)
    # 재실행 검증(과제 #35) 결과를 본 뒤 필요 시 별도 커밋으로 추가한다(§9: 한 커밋에 신호
    # 파라미터 2개 이상 동시 변경 금지 — 이번 커밋은 PCT_RISK_ON 단독 변경).
    PCT_RISK_ON: float = 0.60          # 백분위 > 이 값 -> 위험선호(100%) [v1.4.0: 0.50→0.60]
    PCT_RISK_OFF: float = 0.20         # 백분위 < 이 값 -> 위험회피(0%)
    HYSTERESIS_DAYS: int = 2           # 국면 전환에 필요한 연속 확인일수
    MIN_HOLD_DAYS: int = 3             # 최소 보유일 (휩쏘 방지)
    USE_TREND_OVERRIDE: bool = True    # 200MA 하회 + 복합점수<0 -> 강제 위험회피
    # ---- 검증 통과 기준 (PASS criteria) ---------------------------------
    VAL_HORIZONS: Tuple[int, ...] = (5, 21, 63)   # 선행성 검증 지평(거래일)
    VAL_PRIMARY_H: int = 21                        # 대표 지평 (약 1개월)
    MIN_ABS_IC: float = 0.030          # |Spearman IC| 최소치
    # [v1.2.0] 2.00(양측 5%) -> 1.65(단측 5%)로 완화. 모든 지표는 이미 경제적 사전방향(prior_sign)을
    # 지정해두고 있어 방향에 대한 가설이 사전에 고정되므로 단측검정이 정당하다(사후에 유리한 방향을
    # 골라 데이터마이닝하는 것이 아님 -- '사전방향일치' 게이트가 별도로 방향 정합성을 확인한다).
    # 실사용 리포트에서 VIX_TERM(IC 0.15, 하락AUC 0.66, 4구간 부호일치 3/3)이 NW-t=1.22 하나로
    # 탈락하는 등, 2.0 기준이 이 검증체계(다른 5개 게이트가 이미 충분히 엄격)에는 과도했다.
    MIN_ABS_TSTAT: float = 1.65        # Newey-West |t| 최소치 (단측 5% 근사)
    MIN_AUC_EDGE: float = 0.030        # |AUC - 0.5| 최소치 (하락 판별력)
    MIN_SUBPERIOD_AGREE: int = 3       # 4개 구간 중 부호 일치 최소 개수
    MIN_COVERAGE: float = 0.60         # 백테스트 구간 내 데이터 커버리지
    DD_LABEL_THRESHOLD: float = -0.05  # 향후 h일 내 -5% 이상 하락 = '하락 이벤트'
    # ---- walk-forward ---------------------------------------------------
    TRAIN_MIN_YEARS: int = 5           # 최초 가중치 추정에 필요한 최소 학습연수
    WARMUP_REWEIGHT_FREQ: str = "A"    # SIGNAL_START 이전 워밍업 구간 재추정 주기 (연 1회 고정, 성능)
    # (SIGNAL_START 이후 재추정 주기는 REWEIGHT_FREQ — 아래 v1.2.0 섹션에서 정의)
    # ---- 재현성 ---------------------------------------------------------
    RANDOM_SEED: int = 20260831
    # ---- 입출력 ---------------------------------------------------------
    CACHE_DIR: str = "./cache_market_data"
    OUT_XLSX: str = "market_regime_report.xlsx"
    LOG_LEVEL: str = "INFO"            # DEBUG로 바꾸면 지표별 상세 로그
    # [v1.9.0 §B] 05b_하락상승구간 시트(사후 진단 전용, 신호 로직에 미사용)의 구간 분할 임계값.
    # 사용자 요청 "최고점 대비 -2% 이상 하락한 기간 / 하락 후 -2% 이상 재하락하지 않고 상승한
    # 기간"을 대칭 ±2% 지그재그로 구현: 종가가 직전 러닝고점 대비 -2% 이상 내려오면 하락구간
    # 시작(고점 확정), 러닝저점 대비 +2% 이상 올라오면 상승구간 시작(저점 확정). 구간별로
    # 매도(감축)/매수(증액) 타이밍이 고점/저점 대비 선행·지연 며칠이었는지 판정한다.
    # 사후(전체표본) 확정이므로 진단 전용이며 어떤 신호 계산에도 재사용하지 않는다(룩어헤드 무관).
    DRAWDOWN_EPISODE_THRESHOLD: float = 0.02
    # ---- 네트워크 (v1.1.0: FRED 타임아웃 대응) ---------------------------
    FETCH_TIMEOUT_CONNECT: float = 10.0  # 연결 타임아웃(초)
    FETCH_TIMEOUT_READ: float = 25.0     # 응답 타임아웃(초). 기존 30초 고정 1회당보다 짧게 끊고
                                          # 더 자주/더 병렬로 재시도하는 쪽이 총 대기시간이 짧다.
    FETCH_RETRIES: int = 2               # 시리즈당 재시도 횟수 (기존 3 -> 2. 병렬화로 상쇄)
    FETCH_MAX_WORKERS: int = 8           # 동시 다운로드 스레드 수 (Yahoo/FRED 각각)
    # [v1.11.0] 사용자 제공 키를 기본값으로 설정("api key는 이걸로 넣어" 요청) — 설정 시
    # JSON API(api.stlouisfed.org)를 CSV보다 먼저 시도해 수집 안정성이 올라간다(v1.1.1 §참조).
    FRED_API_KEY: Optional[str] = "5a586c94ed745a6193f625c0620f5da4"
                                          # 지정 시 CSV 엔드포인트 실패 후 JSON API로 한 번 더 시도한다.
    # ---- 지표 유니버스 (v1.1.0) ------------------------------------------
    # 섹터 로테이션 지표(경기소비재/필수소비재, 반도체 등)는 사용자 요청으로 이번 버전에서 제외.
    # MACRO_SERIES/CROSS_ASSET_SERIES 하단에 재도입 지점을 주석으로 남겨둠.
    TRANSFORM_HORIZONS: Tuple[int, ...] = (5, 20, 60, 120)  # 자동생성 지표의 관측 지평(거래일)
    # ---- 데이터 무결성 (v1.2.0) -------------------------------------------
    # 캐시 스키마 버전. 올릴 때마다 이전 로컬 캐시 파일이 자동 무시되고 재수집된다.
    # v1.1.x의 yfinance 병렬 다운로드가 티커 간 가격을 뒤섞는 교차오염 버그를 만들어(예:
    # "SPY" 종가가 실제로는 RSP 가격으로 저장됨), 오염된 캐시가 재사용되지 않도록 버전을 올렸다.
    CACHE_SCHEMA_VERSION: int = 2
    PRICE_START_TOLERANCE_DAYS: int = 365   # Yahoo 티커 실제시작일이 예상보다 이만큼 늦으면 제외
    FRED_START_TOLERANCE_DAYS: int = 730    # FRED 시리즈 실제시작일이 예상보다 이만큼 늦으면 제외
    # [v1.4.0 §1(C) 성능] 실사용 로그(log3.txt)에서 BAML 9종이 매 실행마다 4경로×2라운드
    # (JSON 2회 + CSV 2회, 무결성실패 확인 후 전체 1회 재시도) = 최대 8회의 왕복을 반복해
    # 실행당 ~190초, 같은 날 재실행 시 또 ~200초를 낭비했다(원인은 §2에서 확인 — FRED가
    # 해당 시리즈를 구조적으로 최근 3년만 반환하는 것이지, 일시적 오류가 아니다). 세 가지로
    # 낭비를 없앤다: (1) 실패 확정 시리즈는 당일 재실행에서 재시도 없이 즉시 제외(네거티브
    # 캐시), (2) CSV 경로가 이 환경에서 구조적으로 막혀 있으면(연속 ConnectionError) 그
    # 배치의 나머지 시리즈는 CSV 시도를 건너뛰는 회로차단기, (3) JSON 두 변형이 동일한
    # 무결성실패 메시지를 반환하면(서버가 그렇게 주는 것이 확실하므로) 전체 재시도 라운드를
    # 생략하고 바로 최종 판정(§2 단축이력 수용 또는 제외)으로 넘어간다.
    FRED_FAILURE_CACHE_HOURS: float = 20.0    # 무결성/다운로드 실패 확정 시리즈를 이 시간 동안 재시도하지 않음(대략 "당일")
    CSV_CIRCUIT_BREAKER_THRESHOLD: int = 3    # 한 배치 내 CSV 경로 연속 ConnectionError 이 값 이상이면 나머지는 CSV 스킵(JSON 있을 때만 적용)
    # [v1.15.1 §A 견고성] report16(v1.15.0 실행) 사고의 재발 방지. 그 실행은 FRED 54개 시리즈가
    # 전부 ConnectionError(JSON 경로 2종 모두 — 해당 Colab 세션에서 FRED 자체에 도달 불가)로
    # 실패했고(00시트 "FRED 수집률 0/54 FAIL"), 12시간 캐시는 이미 만료돼 있어 파이프라인이
    # **가격 데이터만으로** 지표검증→가중→신호까지 조용히 완주했다(표준 PASS 15→3, 위험 PASS
    # 111→17). 그 결과 CAGR 14.83→10.93%, 2022 -7.8→-17.95%로 무너진 리포트가 "정상 산출물"
    # 처럼 나갔다. 이것은 규칙 ⑦ 때문이 아니라(그 리포트의 06c deep_recovery 격자: off 9.95%
    # vs -20% 10.93%) 입력 데이터가 사라진 사고였으며, 세 겹의 안전장치를 추가한다:
    #  (1) 지연캐시 대체: 4경로 전부 '다운로드 실패'(무결성 실패가 아닌 전송 실패)면 최근
    #      FRED_STALE_CACHE_MAX_DAYS 이내의 만료 캐시를 경고와 함께 대신 쓴다(지표는 며칠
    #      늦어도 '없음'보다 훨씬 낫고, 10시트에 [지연캐시]로 반드시 드러낸다).
    #  (2) 배치 재시도: 1차 배치 수집률이 FRED_MIN_COLLECT_RATIO 미만이면 FRED_BATCH_RETRY_
    #      WAIT_S 대기 후 회로차단기를 리셋하고 전송 실패 시리즈만 1회 재배치한다.
    #  (3) 수집률 하한 게이트: 그래도 수집률이 FRED_MIN_COLLECT_RATIO 미만이면 리포트를 만들지
    #      않고 즉시 중단한다(RuntimeError, 한국어 조치 안내). ALLOW_DEGRADED_RUN=True로 명시한
    #      경우에만 경고와 00시트 "성능저하 실행" 표기를 달고 계속 진행한다.
    #  또한 전송 실패는 네거티브 캐시에 기록하지 않는다 — 일시적 네트워크 장애를 20시간
    #  동안 "실패 확정"으로 고정해 복구 후 재실행까지 망치는 2차 피해(report16 직후 재실행
    #  시 실제로 발생했을 경로)를 막는다. 무결성 실패(서버 구조 문제)만 종전대로 기록한다.
    FRED_STALE_CACHE_MAX_DAYS: float = 30.0   # 전송 실패 시 이 일수 이내의 만료 캐시를 지연캐시로 대체 사용(0이면 비활성)
    FRED_MIN_COLLECT_RATIO: float = 0.80      # 실데이터 실행의 FRED 수집률 하한(배치 재시도 트리거 겸 중단 게이트)
    FRED_BATCH_RETRY_WAIT_S: float = 15.0     # 배치 재시도 전 대기(초). 음수면 배치 재시도 비활성
    ALLOW_DEGRADED_RUN: bool = False          # True면 수집률 미달이어도 경고+"성능저하 실행" 표기로 진행(기본 중단)
    # [v1.21.0 §A 견고성] report22(v1.20.0 실행) 사고의 재발 방지 — Yahoo 배치 다운로드가 ^VIX3M·^VIX9D를
    # **1행(당일)만** 반환했고(10시트: "실제시작 2026-09-03 vs 예상 2008-01-01"), 그 1행짜리 프레임이 정상
    # 캐시를 덮어쓴 뒤 무결성 검사에서 제외되면서 VIX_TERM이 전 구간 NaN → 급락트리거(규칙 ⓪) 백분위가
    # 2,180일 전부 결측 → 2020-02/03 급락을 0.5로 통과(2020 +27.6→+15.8%), MDD -8.4→-14.6%. 리포트 상단은
    # "FRED 54/54 PASS"였고 트리거 결측은 01시트 빈 열로만 드러났다(FRED report16 사고와 같은 종류).
    #  (1) 퇴화 수집 판정: 행수 < YAHOO_MIN_ROWS 이거나 실제 시작일이 YAHOO_EXPECTED_START(DATA_START로
    #      클램프)보다 PRICE_START_TOLERANCE_DAYS 이상 늦으면 '퇴화'로 보고 **캐시에 쓰지 않는다**(정상
    #      캐시 덮어쓰기 금지). 12시간 이내 캐시라도 퇴화면 무시하고 재수집한다.
    #  (2) 개별 재시도 → 지연캐시 대체: 퇴화면 YAHOO_CRITICAL_RETRY_WAIT_S 대기 후 단일 티커로 1회 재수집,
    #      그래도 퇴화면 YAHOO_STALE_CACHE_MAX_DAYS 이내의 만료 캐시(정상 이력)를 경고와 함께 대신 쓴다
    #      (10시트 [지연캐시] 표기).
    #  (3) 신호핵심 게이트: 그래도 SIGNAL_CRITICAL_TICKERS(매매대상 + 급락트리거 입력 ^VIX·^VIX3M) 중 하나라도
    #      없으면 리포트를 만들지 않고 즉시 중단한다(RuntimeError, 조치 안내). ALLOW_DEGRADED_RUN=True일 때만
    #      경고 + 00시트 "성능저하 실행" 표기로 진행.
    #  (4) 커버리지 투명화: 급락트리거 백분위의 신호구간 커버리지를 로그·00시트에 명시하고, 커버리지가
    #      FAST_TRIGGER_MIN_COVERAGE 미만이면 (3)과 같은 게이트를 적용한다(원인이 무엇이든 규칙 ⓪이 죽은
    #      리포트는 정상 실행과 비교할 수 없다).
    SIGNAL_CRITICAL_TICKERS: Tuple[str, ...] = ("SPY", "^VIX", "^VIX3M")
    YAHOO_MIN_ROWS: int = 250                  # 이보다 짧은 일별 프레임은 퇴화 수집으로 간주(1년 미만)
    YAHOO_STALE_CACHE_MAX_DAYS: float = 30.0   # 퇴화/실패 시 이 일수 이내의 만료 캐시를 지연캐시로 대체(0이면 비활성)
    YAHOO_CRITICAL_RETRY_WAIT_S: float = 10.0  # 퇴화 수집 개별 재시도 전 대기(초). 음수면 재시도 비활성
    FAST_TRIGGER_MIN_COVERAGE: float = 0.90    # 신호구간 급락트리거 백분위 커버리지 하한(미만이면 중단 게이트)
    # [v1.4.0 §2] FRED가 구조적으로 짧은 이력만 반환하는 것으로 확인된 시리즈(BAML 신용
    # 스프레드 9종, log3.txt에서 JSON 양쪽 변형 모두 "실제시작 2023-09-01"로 일관되게 확인
    # — CSV는 이 환경에서 전부 ConnectionError라 대안이 되지 못함). 이 목록의 시리즈는
    # _check_fred_integrity()에서 무결성 "실패"가 아니라 "단축이력 수용"으로 처리해 짧게라도
    # 살려 쓴다(§2 상세 근거는 _check_fred_integrity()/fetch_fred() 주석 참조).
    FRED_ALLOW_SHORT_HISTORY: Tuple[str, ...] = (
        "BAMLH0A0HYM2", "BAMLC0A0CM", "BAMLH0A1HYBB", "BAMLH0A2HYB", "BAMLH0A3HYC",
        "BAMLC0A1CAAA", "BAMLC0A2CAA", "BAMLC0A4CBBB", "BAMLEMCBPIOAS",
    )
    # [v1.5.0 §A] ⚠ 검증게이트 파라미터 — 아래 2개 필드는 지표 채택 여부(=신호 구성요소)를
    # 바꾸므로 CHANGELOG에 명시 플래그됨.
    # 배경(실사용 리포트 market_regime_report_4.xlsx, 03_지표검증 시트 실측): FRED_ALLOW_
    # SHORT_HISTORY 소속 지표(BAML 신용스프레드 계열)가 위험트랙AUC엣지 0.10~0.2943으로
    # 하락판별력이 뚜렷함에도(위험트랙 임계 0.05를 크게 상회) 아래 두 구조적 게이트에
    # 걸려 전원 FAIL 처리되고 있었다:
    #   (a) 가중커버리지 상한선 문제 — 가중커버리지는 최근일에 지수적으로 더 큰 가중치를
    #       주는 weighted_coverage = 1 - sum(w_t * I(결측_t)) 방식(HALF_LIFE_DAYS=913)이라,
    #       시리즈 전체 이력이 실제로 W일뿐이면(BAML 9종은 FRED가 구조적으로 2023-09-01부터만
    #       제공 — 위 §2 주석 참조, 즉 W≈1095일) 그 구간에서 100% 결측이 없어도
    #       weighted_coverage <= 1 - 0.5**(W/HALF_LIFE_DAYS) = 1 - 0.5**(1095/913) ≈ 0.565로
    #       수학적으로 상한이 걸린다. 즉 데이터 품질과 무관하게 MIN_COVERAGE=0.60을 절대
    #       넘을 수 없다(실측 03_지표검증 가중커버리지 0.498~0.561로 이 상한과 정확히 부합).
    #   (b) 부호일치구간수 문제 — validate_indicators()는 DATA_START(1990)~현재 전체 이력을
    #       4등분(blocks = np.array_split(...))해 부호일치구간수를 계산하는데, 2023-09
    #       이후에만 데이터가 있는 시리즈는 이 4구간 중 1구간에만 유효값이 존재해
    #       MIN_SUBPERIOD_AGREE=3(4구간 중 3구간 이상 부호일치 요구)을 원천적으로 만족할 수
    #       없다(실측 판정사유: "부호안정성 1/1 < 3"). (a)와 독립적인 두 번째 구조적 게이트.
    # 두 게이트 모두 "이 지표군은 이력이 짧다"는 사실 자체가 원인이지 통계적 유의성 부족이
    # 아니므로, FRED_ALLOW_SHORT_HISTORY 소속 지표에 한해서만(그 외 지표는 기존 MIN_COVERAGE/
    # MIN_SUBPERIOD_AGREE 그대로 적용, 완화 아님) 아래 값으로 대체 적용한다.
    #   MIN_COVERAGE_SHORT_HISTORY=0.45: (a)의 이론상한 0.565에 여유를 두어, 상한 자체가
    #     낮은 것과 실제 결측이 많은 것을 여전히 구분(예: 상한 부근이 아니라 그보다도 낮으면
    #     여전히 FAIL).
    #   MIN_SUBPERIOD_AGREE_SHORT_HISTORY=1: (b)에서 유효 구간이 최대 1개뿐이므로, "그 1개
    #     구간에서는 부호가 사전방향과 일치해야 한다"는 최소 요건만 유지(0으로 완전히 없애지
    #     않음 — 부호가 아예 반대인 지표까지 통과시키지는 않는다).
    MIN_COVERAGE_SHORT_HISTORY: float = 0.45      # FRED_ALLOW_SHORT_HISTORY 소속 지표 전용 커버리지 완화 하한
    MIN_SUBPERIOD_AGREE_SHORT_HISTORY: int = 1    # FRED_ALLOW_SHORT_HISTORY 소속 지표 전용 부호일치구간수 완화 하한
    # ---- 검증기준 재설계 (v1.2.0) ------------------------------------------
    MIN_INDICATORS: int = 3            # 복합점수 산출에 필요한 최소 채택지표 수 (composite_score와 동기화)
    SOFT_ADOPT_MAX: int = 5            # 엄격PASS가 부족할 때 보조채택으로 채울 목표 최소 지표 수
    SOFT_ADOPT_WEIGHT_DISCOUNT: float = 0.5  # 보조채택 지표의 가중치 할인율
    TREND_TRACK_WEIGHT_CAP: float = 0.30     # E.추세 카테고리(국면필터 트랙) 가중치 합산 상한
    # [v1.3.0 §6] 정식 PASS 8개 중 5개가 달러(DXYNYB/DTWEXBGS)·본원통화(BOGMBASE) 단 2개
    # 기저 시리즈에서 파생된 변형이었다(실사용 리포트 market_regime_report_2.xlsx 확인,
    # IMPROVEMENT_PLAN_v1.3.md §6) — 한 데이터 소스의 이상이 복합점수 전체를 흔들 수 있는
    # 구조. 같은 기저 시리즈(IndicatorSpec.base_series, 자동생성 지표는 series_id)에서
    # 나온 지표들의 절대가중치 합이 이 값을 넘으면 축소 후 다른 시리즈에 비례 재분배한다
    # (TREND_TRACK_WEIGHT_CAP과 동일한 단일패스 설계, _select_and_weight_period에 구현).
    SERIES_WEIGHT_CAP: float = 0.20
    # ---- 위험(해저드) 트랙 (v1.3.0 §4/§5) ---------------------------------
    # ⚠ 위험(신호) 파라미터 — 아래 4개 필드는 매매신호 자체를 바꾸므로 CHANGELOG에 명시 플래그됨.
    # 배경: VIX_LEVEL(하락AUC 0.623)처럼 "IC(수익예측)로는 사전방향과 반대(공포=매수기회,
    # 평균회귀)지만 하락사건 판별력(AUC)은 사전방향 그대로"인 지표가 기존 표준트랙(IC/NW-t 게이트)
    # 에서 전부 FAIL해, 시스템이 빠른 조정(2025-04, 2026-02~03 등)에 무방비였다
    # (실사용 리포트 market_regime_report_2.xlsx, IMPROVEMENT_PLAN_v1.3.md §4). 표준트랙(수익
    # 예측용, 기존 그대로 유지)과 별개로, "하락사건 판별력"만 보는 위험 트랙을 신설해 이런
    # 지표를 살리고, 그 위험점수(H)로 진입 가속·오진입 차단·해제 안전판을 보강한다.
    USE_HAZARD_TRACK: bool = True      # False -> v1.2.0과 완전히 동일한 신호(하위호환 회귀테스트용)
    HAZARD_ENTER: float = 0.85         # H 백분위가 이 값을 넘으면(위험 급등) 단독으로 위험회피 진입
    HAZARD_BLOCK: float = 0.70         # H 백분위가 이 값을 넘으면 위험선호(RISK_ON) 신규진입을 중립까지만 허용
    # [v1.3.0 §5] 위험회피 해제 안전판: 매크로(수익트랙) 점수는 후행적이라 저점 이후에도 한동안
    # 위험회피를 유지하는 경향이 있다(실사용 리포트 2023-09~11, 2026-03~04 재진입 지연 확인).
    # 가격이 이미 200일선을 회복했고 빠른 위험지표(H)도 정상화됐다면(백분위가 이 값 미만) 매크로
    # 점수의 회복을 기다리지 않고 최소 중립(0.5)까지는 승격한다. 2022년형 완만한 베어마켓은
    # 가격이 200일선 아래 머무는 기간이 대부분이라 이 안전판이 거의 발동하지 않아(가격 조건이
    # 우선 걸림) 그 해의 방어력을 훼손하지 않는다 — §5 수용기준(2022 MDD 악화 ≤2pp)의 근거.
    # [v1.7.0 §A ⚠ 신호(위험) 파라미터] 0.50 → 0.70. 실사용 리포트(market_regime_report_6.xlsx,
    # v1.6.0 실행) 01_일별기록 실측: 이 안전판이 설계 목적("매크로 점수의 후행성 보완")의 대표
    # 연도인 2023년에 단 하루도 발동하지 못했다(발동일수: 2022년 19일/2026년 30일/2023년 0일).
    # 원인: 2023년 위험회피 167일 중 H백분위<0.50인 날이 정확히 0일 — 2022 위기 직후에는 위기
    # 학습 직후의 워크포워드 위험트랙(금리·통화·커브 지표가 상위 가중)이 "금리 급등 지속"을 계속
    # 위험으로 읽어 H백분위가 중앙값(0.50) 아래로 내려오는 데 수개월~수년이 걸리기 때문. 그 결과
    # 가격이 200일선 위(추세오버라이드 미발동 151일)인데도 연평균 비중 0.18로 +26% 상승장을
    # 통째로 놓쳤다(초과수익 -17.4pp — 현 시점 최대 잔존 성과 문제). 새 값 0.70의 근거는 격자
    # 최적화가 아니라 임계값 의미론의 통일이다: HAZARD_BLOCK=0.70이 이미 "이 값을 넘으면 능동적
    # 위험(위험선호 신규진입 차단)"의 경계로 정의돼 있으므로, 안전판도 "능동적 위험이 아닌 한
    # (H<0.70) 가격 회복을 인정"하는 같은 경계를 쓰는 것이 일관적이다(기존 0.50은 "중앙값 미만의
    # 저위험"까지 요구 — 위기 직후 구간에서는 구조적으로 도달 불가능한 기준). 예상 효과(01시트
    # 일 단위 근사, 상태 경로의존성 무시한 1차 추정): 위험회피&가격>200MA&0.5<=H<0.7 일수는
    # 2022년 10일(익일 시장수익 평균 +0.19%), 2023년 39일(+0.11%), 2024년 5일(+0.35%), 2025년
    # 10일(-0.34% — 이 해는 소폭 방어력 반납, 정직하게 명시), 2026년 2일(+0.27%) — 순효과는
    # 양(+)이나 2025년 반납이 있음. 06c 시트에 HAZARD_NEUTRAL_FLOOR 단독 민감도 4케이스
    # (0.50/0.60/0.70/0.80)를 신설해 다음 실행부터 실측 검증 가능(§9 원칙 준수: 격자 최적 셀
    # 채택이 아니라 사전 정당화 가능한 값 + 민감도는 사후 확인용).
    HAZARD_NEUTRAL_FLOOR: float = 0.70
    # [v1.8.0 §B ⚠ 신호(위험) 파라미터 — 이번 라운드 유일 변경(§9): 기존 HAZARD_ENTER/BLOCK/
    # NEUTRAL_FLOOR는 전혀 건드리지 않음] 집행일 매수(비중 증가) 보류 게이트.
    # 배경(market_regime_report_7.xlsx 02_거래내역+01_일별기록 실측, 14건 전수): HAZARD_BLOCK은
    # RISK_ON 신규진입만 차단하고 RISK_OFF→NEUTRAL 상향(반포지션 매수)은 차단하지 않는 비대칭
    # 구멍이 있었다. H>0.70(BLOCK 초과)에서 집행된 매수 2건(#13 H=0.877, #14 H=0.77) 모두 손실,
    # H<0.70 매수 12건 중 손실 3건(그중 1건은 신호시작일 워밍업 아티팩트) — 표본 14건으로
    # 통계적 확증은 아니나 메커니즘 결함의 예시. 특히 #13은 신호확정일 H=0.817 대비 익일
    # 집행일 H=0.877로 더 악화된 뒤 체결, 히스테리시스+최소보유일(5일)에 묶여 07-22 손절.
    # 대응: 비중을 늘리는 확정 전환 시점에 그 날의 H백분위를 재확인해 BUY_HOLD_GATE_THRESHOLD를
    # 넘으면 전환을 보류(취소 아님 — H가 임계값 이하로 내려온 날 그대로 확정)한다. 비중을
    # 줄이는 전환(SELL/REDUCE)은 절대 보류하지 않는다(안전 비대칭 — 손실 회피 경로를 막지
    # 않음). 적용 범위: 정상 확정 경로(streak/held 히스테리시스)에만 적용하고, TREND_ONLY·
    # NO_SIGNAL의 강제전환(fallback, §C-3 별도 이슈)에는 적용하지 않는다.
    # 임계값(BUY_HOLD_GATE_THRESHOLD) 근거: 격자 최적화가 아니라 HAZARD_BLOCK과의 의미론
    # 통일(v1.7.0 HAZARD_NEUTRAL_FLOOR와 동일 원칙) — "능동적 위험(H>0.70)"의 경계를 신규진입
    # 차단뿐 아니라 모든 비중증가 전환에 동일하게 적용한다. 단, HAZARD_BLOCK 필드 자체를 바꾸는
    # 것이 아니라 별도 필드로 분리해(HAZARD_NEUTRAL_FLOOR와 동일 패턴) 두 메커니즘을 독립적으로
    # 민감도 검증·재튜닝할 수 있게 한다. ⚠ 주의(IMPROVEMENT_PLAN_v1.8.md §B-1 명시): 2023-11-21
    # 진입(#8, H=0.71, +14.5% 최대 승리거래)이 0.70 기준에 아슬아슬하게 걸려 지연될 수 있음 —
    # 06c 시트에 BLOCK(0.70)/0.75/0.80/ENTER(0.85) 4케이스 전용 민감도를 신설해 다음 실행부터
    # "지연으로 잃는 상승분 vs 회피하는 휩쏘"를 실측 확인한다(격자 최적 셀 채택 금지 원칙 유지).
    USE_BUY_HOLD_GATE: bool = True
    BUY_HOLD_GATE_THRESHOLD: float = 0.70   # = HAZARD_BLOCK과 동일값에서 출발(의미론 통일), 별도 필드
    # [v1.10.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일 변경(§9)] 급락 fast-trigger(규칙 ⓪).
    # IMPROVEMENT_PLAN_v1.8.md §A-1에서 제안, v1.9 §D-1로 승계, 사용자 지시("등락률 큰 하락은
    # 반드시 회피, 하락 전날이 아니라 좀 더 일찍 회피해도 됨")로 이번 라운드 구현.
    # 근거(market_regime_report_9.xlsx, SIGNAL_START=2018 확장 실측): 2020 코로나 급락에서
    # 시스템이 -24.3% 낙폭을 그대로 맞았다. 01시트 실측 실패 사슬: (i) 수익트랙 복합점수
    # 백분위가 급락 내내 0.82~0.99 — 패닉성 금리 인하가 금리계열 지표에 '호재'로 찍혀 매크로
    # 점수가 역방향으로 상승(단순 지연이 아니라 부호 자체가 반대), (ii) H백분위는 02-19 0.29
    # → 03-13에야 0.854로 HAZARD_ENTER(0.85) 도달 — 고점 후 17거래일, 시장 -20% 이후,
    # (iii) 그 사이 H가 0.70 부근에서 진동하며 차단이 풀려 03-09(-7.6% 당일) 시가에 풀포지션
    # ADD까지 발생. 같은 패턴(빠른 이벤트에 레벨 규칙 무력)이 2018-02(-10.1%, 0.5 통과),
    # 2019-07(-6.0%, 1.0 통과), 2020-06(-7.0%, 1.0), 2024-08 엔캐리(-6.1%, 0.5) 등 반복.
    # 대응: 합성 H(느린 지표에 희석됨)와 무관하게, 빠른 단독 지표 하나의 자기과거분포
    # (expanding, 룩어헤드 없음) 백분위가 FAST_TRIGGER_PCT를 넘으면 그 날 raw_state를 즉시
    # RISK_OFF로 강제한다(규칙 ① haz_enter와 동일 효과의 OR 조건). 위험회피 해제 안전판
    # (규칙 ③)은 fast-trigger 발동일에는 적용하지 않는다 — 급성 변동성 급등은 합성 H 레벨이
    # 낮아도 '능동적 위험'이므로 안전판이 이를 되돌리면 트리거가 무력화된다(2020-02-24~28처럼
    # 가격>200MA & H<0.70인 급락 초입이 정확히 그 사례).
    # 지표 선택 근거: VIX_TERM(VIX3M/VIX 기간구조) — 옵션시장 헤지수요는 현물 매도에 수일
    # 선행(스펙 명시 근거)하며, 위험트랙 AUC엣지 상위(0.142)로 이미 검증 통과된 기존 지표의
    # 재사용(§E 신규 지표 추가 금지에 저촉되지 않음). prior_sign=+1(클수록 호재)이므로 위험
    # 방향 백분위는 부호 반전값의 expanding rank로 계산한다.
    # 임계값 0.97 근거(사전 정당화 — 격자 최적화 아님): expanding 분포 상위 3% ≈ 연 7~8
    # 거래일 수준의 극단 꼬리로, "진짜 스트레스 이벤트"만 잡고 통상 조정(-2~-3%)에는 침묵
    # 하도록 설계. 0.90은 연 ~25일로 과다 발동(오탐), 0.99는 연 2~3일로 중형 쇼크를 놓칠
    # 위험. 06c에 0.90/0.95/0.97/0.99 전용 민감도 + 오탐률(발동 후 21일 시장수익)을 신설해
    # 다음 실행부터 실측 확인(§9: 격자 최적 셀 채택 금지 — 민감도는 사후 확인용).
    USE_FAST_TRIGGER: bool = True
    FAST_TRIGGER_INDICATOR: str = "VIX_TERM"
    FAST_TRIGGER_PCT: float = 0.97
    # [v1.11.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일 변경(§9)] 회복 승격 규칙(규칙 ⑤).
    # 사용자 요청("상승 구간은 최저점 이후 상승 시 최대한 근처에서 비중을 늘려 매수")의 인과적
    # 구현. 배경(market_regime_report_10.xlsx 실측): fast-trigger로 2020 낙폭은 -24.3%→-9.3%로
    # 막았지만 여전히 buy-and-hold에 뒤짐(CAGR 11.4% vs 14.6%) — 잔여 격차의 주범은 회복장
    # 재진입 실패다. 06c 오탐률 실측이 이를 정량화: 트리거 발동일 이후 21일 시장수익 중앙값이
    # +4.6%(양수비율 73%) — 트리거는 최악 구간을 피하게 하지만, 패닉이 끝난 뒤 반등을 놓치면
    # 회피 이득을 도로 반납한다. 재진입을 막던 3중 자물쇠(01시트 실측): (i) 매크로 점수
    # 백분위가 회복 초기 0.08~0.24 저공비행(2020-04, 2023, 2026 공통), (ii) 추세오버라이드
    # (가격<200MA & 점수<0.5 — 2020-03~05 내내), (iii) H백분위 0.7+ 지속으로 매수보류게이트
    # 차단. 대응: 종가가 최근 RECOVERY_LOW_WINDOW(120거래일≈6개월, 통상 조정의 진짜 저점을
    # 포괄하는 참조창) 저점 대비 RECOVERY_CONFIRM_PCT(+5%, 일상 노이즈(일변동 1~2%)를 넘는
    # 반등 확인폭) 이상 회복했고, 그 날 급락트리거·haz_enter가 침묵하면, 점수·추세·게이트와
    # 무관하게 최소 중립(0.5)까지 승격한다(규칙 ③ 안전판의 '가격 확인' 확장판 — ③은
    # 가격>200MA & H<0.70을 요구해 위기 직후 회복장에서 구조적으로 침묵했다). 이 승격은
    # 매수보류게이트(규칙 ④) 적용 대상에서 제외한다 — 실측상 승격 대상일의 74%(166/225일)가
    # H>0.70이라 제외하지 않으면 규칙이 무력화되며(2020-04, 2023 전부), +5% 가격 확인 +
    # 트리거/ENTER 침묵이라는 자체 안전장치가 게이트의 역할(위험 상승 중 매수 차단)을 대신한다.
    # 1차 근사 실측(report10, 일 단위): 승격 예상일 225일, 연도별 기여 2020 +6.7pp/2023 +4.5pp/
    # 2019 +1.6pp/2026 +1.1pp, 2022 -0.2pp(방어 사실상 무손상 — §E 수용기준 충족 예상).
    # 첫 승격일 실측: 2020-03-30(3-23 저점 후 4거래일), 2025-04-14(4-08 저점 후 4거래일),
    # 2019-01-02, 2026-04-08 — "저점 최대한 근처 매수"를 룩어헤드 없이 달성. ⚠ 정직 고지:
    # 기본값(120, 0.05)은 사전 근거(6개월 참조창·노이즈 초과 확인폭)로 먼저 정했고 위 1차
    # 근사가 이를 확인했다 — 같은 표본에서 관찰했으므로 선택편향 잔존 가능성을 명시하며,
    # 06c 전용 민감도(0.03/0.05/0.07/0.10)로 다음 실행부터 강건성을 실측 확인한다.
    USE_RECOVERY_FLOOR: bool = True
    RECOVERY_LOW_WINDOW: int = 120
    RECOVERY_CONFIRM_PCT: float = 0.05
    # [v1.12.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일 변경(§9)] 추세 승격 규칙(규칙 ⑥).
    # 사용자 요청("상승 추세를 못 타는 문제 해결, buy-and-hold보다 높아야 함")의 직접 해법.
    # 배경(market_regime_report_11.xlsx 실측): 규칙 ⑤로 위기 후 재진입(0→0.5)은 해결됐지만
    # (2020년 +0.0pp 초과수익 — 시장 추격 성공), 이제 병목은 0.5→1.0 승격이다. 완만한 강세장
    # (2021·2019·2023·2024·2026)에서 매크로 점수 백분위가 0.2~0.5 저공비행해 PCT_RISK_ON
    # (0.60)에 못 미치고, 전략은 시장이 수십 % 오르는 동안 반포지션(0.5)으로 관전했다 —
    # 2021년 실측: 0.5 보유 171일 전부 가격>200MA, 그중 170일 H<0.70(능동적 위험 없음),
    # 점수 중앙값 0.312. 잔여 격차(CAGR 12.9% vs 14.6%)의 사실상 전부가 이 구간이다.
    # 대응: 원시상태가 중립이고 (i) 가격>200일선(장기 추세 위), (ii) 복합점수 백분위 >=
    # TREND_PROMOTION_MIN_SCORE_PCT(0.30 — 위험회피 경계 PCT_RISK_OFF(0.20)에서 0.10 이상
    # 떨어진 '매크로가 반대하지 않는' 구간), (iii) H백분위 < HAZARD_BLOCK(0.70, 능동적 위험
    # 아님 — 기존 경계 의미론 재사용), (iv) 급락트리거 침묵이면 위험선호(1.0)로 승격한다.
    # "매크로가 강세를 확인해줄 때만 풀포지션"에서 "매크로가 명확히 반대하지 않고 추세·위험
    # 지표가 허락하면 풀포지션"으로의 전환 — 매크로 점수가 강세장 계량기로는 구조적으로
    # 보수적이라는 4개 리포트 연속 실측(2019/2021/2023/2026 공통)에 근거한다.
    # 1차 근사(report11 일 단위): 승격 대상 433일, 기여 2019 +3.6pp/2021 +4.2pp/2023 +2.4pp/
    # 2024 +1.9pp/2025 +4.4pp/2026 +1.7pp/2020 -0.4pp, **2022 +0.0pp(방어 완전 무손상 —
    # 2022의 0.5 보유일은 전부 점수<0.30이라 승격 조건 미달)**, 합계 +17.9pp(≈CAGR +1.9pp).
    # ⚠ 정직 고지: 점수 하한 0.30은 후보 {0.30, 0.40} 중 1차 근사 비교로 골랐다(0.40은 2021
    # 포착률이 절반으로 줄어 총 +11.7pp) — 같은 표본 관찰이므로 선택편향 가능성을 명시하며,
    # 사전 근거는 "위험회피 경계(0.20)+버퍼 0.10"이라는 경계 의미론이다. 06c 전용 민감도
    # (0.25/0.30/0.35/0.40)로 다음 실행부터 강건성을 실측 확인한다(§9 격자 최적 셀 금지 준수).
    # 매수보류게이트(규칙 ④)와의 관계: 승격 조건 (iii)이 게이트 임계(0.70)와 동일 경계라
    # 승격일은 구조적으로 게이트에 걸리지 않는다(별도 제외 불필요 — 단위테스트로 확인).
    USE_TREND_PROMOTION: bool = True
    TREND_PROMOTION_MIN_SCORE_PCT: float = 0.30
    # [v1.13.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일 변경(§9)] 비대칭 히스테리시스(A-3,
    # v1.8 계획서 §A-3에서 제안된 뒤 3라운드 이월). 사용자 요청("마저 못 피한 하락 더 피하고,
    # 성능이 더 나빠지면 절대 안 됨")에 대응. 원칙(사전 정당화 — 격자 아님): "손실 회피는
    # 빠르게, 진입은 신중하게" — 위험을 줄이는 전환(목표비중 감소: RISK_ON→NEUTRAL→RISK_OFF)
    # 은 확인일수 HYSTERESIS_DAYS_DOWN(1일)로 단축하고 최소보유일 적용을 면제(MIN_HOLD_EXEMPT_
    # DOWN)하며, 위험을 늘리는 전환은 기존 HYSTERESIS_DAYS(2일)·MIN_HOLD_DAYS(3일)를 그대로
    # 유지한다. 실측 근거: (i) report7 #13 — H가 ENTER(0.85)를 넘은 뒤에도 최소보유일에 잘못된
    # 매수 포지션이 5일 잠김, (ii) 급락트리거(v1.10)·haz_enter가 이미 발동한 날에도 확인 2일
    # 대기로 집행이 이틀 늦음(급락 하루하루가 -3~-12%였던 2020-02~03에서 이틀은 결정적).
    # report12 리플레이 실증(01시트 실데이터로 동일 신호엔진 재현, 아래 CHANGELOG 수치):
    # 비대칭 ON이 대칭(현행) 대비 성과 개선을 보인 뒤에만 기본 활성화했다("나빠지면 절대 안 됨"
    # 제약의 사전 검증). 06c에 (확인일수다운×최소보유면제) 4조합 민감도 신설.
    USE_ASYM_HYSTERESIS: bool = False  # ⚠ 리플레이 실증 결과 기본 비활성 — 아래 설명 참조
    HYSTERESIS_DAYS_DOWN: int = 1      # 위험축소 전환의 확인일수(활성 시 2 → 1, 상향 전환은 2 유지)
    MIN_HOLD_EXEMPT_DOWN: bool = True  # 위험축소 전환은 최소보유일(3일) 적용 면제(활성 시)
    # [v1.13.0 §B ⚠ 신호(위험) 파라미터 — 이번 라운드 유일한 '활성' 변경(§9)] 추세 승격(규칙 ⑥)
    # 의 H 상한 분리. v1.12.0은 H<HAZARD_BLOCK(0.70)을 요구했는데, report12 실측에서 2023년이
    # 평균비중 0.508로 여전히 과소투자(-8.5pp)였다 — 2022 위기 직후의 금리편중 위험트랙이
    # 2023년 내내 H백분위를 0.7+로 유지해(v1.7.0 §A와 동일 기제) 규칙 ⑥이 봉쇄된 것. 대응:
    # 승격 허용 H 상한을 별도 필드로 분리하고 기본값을 HAZARD_ENTER(0.85)와 통일 — "능동적
    # 위험(급등 강제진입)이 아닌 한 추세·점수가 허락하면 풀포지션". 진입 차단 경계(BLOCK,
    # 0.70)는 '신규 위험 확대를 막는' 경계이고, ENTER(0.85)는 '강제 위험회피' 경계다 — 이미
    # 추세 위에 있고 점수도 반대하지 않는 상태의 유지·승격에는 후자가 의미론적으로 맞다는
    # 재해석 시도 → ⚠ 리플레이 실증이 기각: 0.70(현행) CAGR 13.51%/샤프 1.302 대비 0.75→
    # 13.15%, 0.80→13.09%, 0.85→12.94%로 단조 악화 — H 0.70~0.85 구간의 승격일은 실제로
    # 손실 기여(그 구간의 H는 진짜 위험 정보를 담고 있음이 실증됨). 따라서 기본값은 기존
    # 경계(0.70=HAZARD_BLOCK)를 유지하고, 이 필드는 06c 단독 민감도(0.70/0.75/0.80/0.85)로
    # 실데이터에서 같은 결론이 재현되는지 사후 확인하는 용도로만 분리해 둔다(기본값에서
    # v1.12.0과 비트 단위 동일 — "성능이 더 나빠지면 절대 안 됨" 제약 준수).
    TREND_PROMOTION_MAX_H: float = 0.70
    # [v1.13.0 §C ⚠ 신호(위험) 파라미터] H 속도(ΔH) 조기경보(A-2, v1.8 계획서 §A-2 이월).
    # H백분위의 HAZARD_VELOCITY_WINDOW(15거래일) 변화가 HAZARD_VELOCITY_DELTA를 넘으면 레벨과
    # 무관하게 위험선호(RISK_ON)를 중립 상한으로 강등하고 추세 승격(규칙 ⑥)을 차단한다.
    # 근거: 2026-03 리셋에서 H가 T-20 0.175→T-5 0.713(15일 +0.54) — 레벨(0.85)보다 속도가
    # 2주 빨랐다(v1.8 §A 원인 2). 기본 활성 여부는 리플레이 실증 결과에 따름(CHANGELOG 참조).
    # [v1.14.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일한 활성 변경(§9)] False → True.
    # 활성 근거(두 번의 독립 실증, 사전 정당화 파라미터(15일, +0.40) 그대로): (i) report12
    # 리플레이 — CAGR +0.05pp/샤프 +0.017/MDD 동일, (ii) report14 실데이터 06c 보류메커니즘
    # 확인 격자 — CAGR 14.80→14.83%/샤프 1.426→1.442/칼마 1.711→1.715/MDD 동일. 두 실험
    # 모두 어떤 지표도 악화 없음("성능이 더 나빠지면 절대 안 됨" 기준 충족 — 이 기준을 두 번
    # 통과한 뒤에만 켠다는 v1.13 §D 예고 그대로). 06c 보류 격자에 계속 남아 매 실행 재검증됨.
    USE_HAZARD_VELOCITY: bool = True
    HAZARD_VELOCITY_WINDOW: int = 15
    HAZARD_VELOCITY_DELTA: float = 0.40
    # [v1.14.0 §B ⚠ 검증게이트/가중 파라미터 — 기본 비활성(None)] 위험트랙 카테고리 가중 상한.
    # 4개 리포트 연속 관찰된 구조 문제(위기 직후 H의 금리계열 편중 — 2023·2026 강세장에서
    # H 0.7+ 고착으로 차단·게이트·승격상한을 통해 노출 축소)의 해법 후보. 값이 주어지면
    # 위험트랙 채택 지표의 카테고리별 |가중치| 합을 이 값 이하로 제한하고 초과분을 다른
    # 카테고리에 비례 재분배한다(SERIES_WEIGHT_CAP·TREND_TRACK_WEIGHT_CAP과 동일한 단일패스
    # 설계, _select_and_weight_hazard_period에 구현). H 산출 자체가 바뀌므로 사전 리플레이
    # 검증이 불가능해 기본은 None(비활성 — 라이브 동작 불변)으로 두고, 06c에 신설한
    # hazard_cap_sensitivity(무제한/0.50/0.40/0.30 — 캐시된 재추정별 검증표로 재선정만 다시
    # 하는 저비용 재시뮬레이션)로 다음 실행부터 실측 근거를 쌓아 활성 여부를 결정한다
    # (A-2와 동일한 "두 번 실증 후 활성" 절차).
    HAZARD_CATEGORY_WEIGHT_CAP: Optional[float] = None
    # [v1.15.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일한 활성 변경(§9)] 깊은 낙폭 회복
    # 풀매수 부스트(규칙 ⑦). 사용자 요청 "큰 상승은 저점 매수 시 비중 최대한 높이고"의 구현.
    # 배경(report15 전수조사·리플레이): 규칙 ⑤는 회복 확인 시 중립(0.5)까지만 승격한다 —
    # 2020-04, 2022-저점 이후 같은 '베어마켓급 낙폭 후 회복'에서 가장 강한 상승 구간을 절반
    # 비중으로만 탔다. 대응: 회복 확인 상태에서, 최근 120거래일 저점이 같은 창 고점 대비
    # DEEP_RECOVERY_DD(-20%) 이상 깊었던 경우(=베어마켓의 고전적 경계 — 사전 정당화 값,
    # 격자 아님)에 한해 중립이 아니라 위험선호(1.0)로 승격한다. 급락트리거·haz_enter·ΔH경보
    # 발동일은 제외(안전장치 유지). 리플레이 실증(report15 실데이터를 실제 신호엔진으로 재현,
    # 2019+): CAGR 13.56→15.63%(+2.07pp), 샤프 1.319→1.417(+0.10), **MDD -9.00% 동일**,
    # 2020년 +19.3→+32.1%(+12.8pp), **2022 -7.8% 완전 무손상(§E 충족 — -20% 경계 덕에
    # 2022년 중간 랠리들은 발동하지 않음)**, 발동 79일. 비용의 정직 명시: 전략 -1% 초과
    # 손실일 82→89일(+7일) — 저점 부근 고변동 구간의 풀포지션이므로 구조적으로 불가피한
    # 트레이드오프(사용자 승인: "큰 상승은 저점 매수 빨리해서 비중 늘리도록"). 같은 실증에서
    # 더 공격적인 -15% 경계는 CAGR 17.0%가 나오지만 MDD -12.9%·2022 -11.0%로 방어를 훼손해
    # 기각(§E — 격자 최고점 채택 금지의 실제 적용 사례). 06c에 off/-0.12/-0.15/-0.20 단독
    # 민감도 신설.
    # [v1.15.1 §B ⚠ 신호(위험) 파라미터 — 되돌림] True → False. 사용자 지시 "다시 수정 전으로
    # 돌아가서". report16(v1.15.0 첫 실사용)은 FRED 수집 0/54 사고(위 §A 주석)로 오염돼 규칙
    # ⑦의 실데이터 실증이 **무효**가 됐다 — 리플레이 근거(+2.07pp)만으로 켜둔 상태는 "두 번
    # 실증 후 활성"(v1.13 §D·A-2 선례) 절차 위반이므로, 절차대로 기본 비활성으로 되돌려
    # 신호를 v1.14.0과 비트 단위로 동일하게 복원한다. 메커니즘과 06c 격자(off/-12/-15/-20%)는
    # 그대로 남겨 다음 정상 실행에서 실데이터 실측을 다시 쌓는다(격자 조건을 기본값과 무관하게
    # 항상 산출하도록 변경). 활성은 그 실측이 리플레이 결과를 재현할 때만.
    # [v1.16.0 §A/§B ⚠ 신호(위험) 파라미터 — 이번 라운드 유일한 활성 변경(§9)] False → True,
    # 정의 두 곳 수정. 두 번째 실증이 도착했다: report17(v1.15.1, FRED 54/54 정상 실행)의 06c
    # 실데이터 격자에서 -20%가 CAGR 14.66→16.38%(+1.72pp)/샤프 1.430→1.496/**MDD -8.65% 동일**/
    # 칼마 1.695→1.894 — 리플레이(+2.07pp)와 같은 방향·크기. 다만 그 리플레이를 연도별로 분해하니
    # 발동 8구간 중 2022-08-09~17(21일 후 -8.0%)만 손실이었고(2022 -0.7pp), 2021-04·2024-04
    # 발동은 "저점→랠리→고점"을 -20% 낙폭으로 오인한 정의 결함이었다. 그래서 (i) 낙폭 정의를
    # 고점→저점 순서가 보장되는 형태로 고치고(DEEP_RECOVERY_DD_MODE="peak_to_trough"), (ii) 복합
    # 점수 백분위가 위험회피 밴드(<PCT_RISK_OFF) 안이면 승격하지 않는 가드(DEEP_RECOVERY_SCORE_
    # GUARD — 규칙 ⑤ 승격 위에 재승격하는 이중 승격 차단, 임계값은 기존 PCT_RISK_OFF 재사용)를
    # 달았다. 두 데이터셋 리플레이(2019+): report15 CAGR 13.56→15.33%(+1.77pp)/샤프 1.319→1.415/
    # MDD -9.00% 동일/2022 -7.8% 무손상, report17 13.38→15.30%(+1.92pp)/샤프 1.306→1.414/MDD
    # -9.68% 동일/2022 -8.5% 무손상, 발동 구간은 두 데이터셋에서 완전히 같음(2019-01/02, 2020-03~05,
    # 2020-09 — 진짜 베어마켓 회복만). 가드 없는 원정의(V0)는 CAGR이 +0.2pp 더 높지만 2022·MDD를
    # 훼손해 채택하지 않음(§E 격자 최고점 채택 금지·2022 방어 훼손 금지의 실적용 — 검토한 5개
    # 구조 변형의 전체 표는 IMPROVEMENT_PLAN_v1.16.md §B). 비용: -1% 손실일 +5일(82→87).
    # [v1.17.0 §A ⚠ 신호(위험) 파라미터 — 이번 라운드 유일한 활성 변경(§9)] DEEP_RECOVERY_DD
    # -0.20 → -0.15. 사용자 요청 "저점 매수 시 비중 많이"의 잔여 격차: report18(v1.16.0 정상
    # 실행)에서 2025-04 -19% 급락 뒤 +15.8% 반등을 평균비중 0.52로만 탔다 — 종가 기준 최대 낙폭이
    # -19.0%라 -20% 경계에 걸리지 않았기 때문. '베어마켓 -20%'는 관행상 장중 저가 기준이며 우리
    # 낙폭은 종가 기준이라(2025-04 장중 -21% vs 종가 -19.0%, 2018-12 -20.2%로 간신히) 종가 기준
    # 여유폭이 필요하다는 것이 사전 근거. v1.15에서 -15%를 기각한 이유(MDD -12.9%·2022 -11%)는
    # v1.16의 정의 수정(고점→저점)+점수 가드로 소멸했음이 확인됨 — 실증 3건: (i) report18 06c
    # 실데이터 격자 -15% CAGR 16.19→17.14%/샤프 1.504→1.549/**MDD -8.65% 동일**/칼마 1.872→
    # 1.982, (ii) report18 리플레이(2019+) 15.28→16.39%(+1.11pp)/샤프 +0.057/MDD 동일/2022 동일/
    # 2025 +18.7→+25.1%, (iii) report15 리플레이 15.33→16.20%(+0.87pp)/샤프 +0.039/MDD 동일/
    # 2022 동일. 추가 발동 3구간(2020-10, 2023-02(유일 손실, -4%), 2023-03, 2025-04) — 2022에는
    # 여전히 무발동(점수 가드). 비용: -1% 손실일 87→91(+4). -12%는 두 데이터셋 모두 -15%보다
    # 열위(격자 최고점이 -15%이지만 위 종가-기준 여유폭 근거가 먼저 있었고 세 실증이 일치함).
    USE_DEEP_RECOVERY_BOOST: bool = True
    DEEP_RECOVERY_DD: float = -0.15
    DEEP_RECOVERY_DD_MODE: str = "peak_to_trough"   # "peak_to_trough"(고점→저점 순서 보장) | "range"(v1.15 정의, 참고행 전용)
    DEEP_RECOVERY_SCORE_GUARD: bool = True          # 점수백분위 < PCT_RISK_OFF(위험회피 밴드)면 승격 금지
    # [v1.17.0 §B 보류 메커니즘 — 기본 비활성] 소프트 트리거 캡. 사용자 요청 "중간 규모 하락 완전
    # 회피/비중 대폭 축소"에 대한 전수 실증 결론: report18 05b의 -4% 이상 하락 52구간 중 미회피
    # 27구간(누적 -163%)은 고점 시점 H 중앙값 0.29·트리거 백분위 0.25·점수 0.42로 어떤 인과 신호도
    # 침묵했고, 첫 -2% 쇼크일 이후 남는 하락은 누적 -34%(21%)뿐 — 손실의 대부분이 첫 쇼크일에
    # 발생해 사후 브레이크가 잡을 여지가 작다. 후보 4계열 × 9변형을 두 데이터셋에 리플레이:
    # (-15% 기준, 2019+) 쇼크 브레이크(-2%/-2.5%, 5일 캡) CAGR -1.6~-2.2pp, 20일 고점 -3%/-5% 캡
    # -2.4~-3.8pp, 변동성 급등 캡 -0.4pp, 소프트 트리거 캡(0.90) -1.0pp / (0.93, 사후 캡) -0.2pp
    # / (0.93, 엔진 내 캡) -0.2pp·손실일 감소 0 — 전부 CAGR 손실, MDD는 어느 것도 개선 못 함
    # (MDD가 2018·2024의 단일 쇼크로 결정됨). "더 나빠지면 안 됨"을 우선해 어떤 브레이크도
    # 활성화하지 않고, 비용이 가장 작은 소프트 트리거 캡(0.93)만 기각 확인용 보류 메커니즘으로
    # 남겨 06c에서 매 실행 실측한다.
    USE_SOFT_TRIGGER_CAP: bool = False
    SOFT_TRIGGER_PCT: float = 0.93
    # [v1.18.0 §A ⚠ 신호(위험) 파라미터 — 기본 비활성(보류)] 규칙 ⑧ 구조적 저점 확인 승격. 사용자
    # 요청 "큰 하락 뒤 유효 저점을 판별해 비중 최대화, 데드캣 회피, MDD 최소화 우선"의 후보.
    # 설계: ≥8% 조정(고점→저점) 후 +5% 회복 확인 & 200일선 되찾기 & H<0.70 & 트리거/ΔH 침묵이면
    # 점수 하한(규칙 ⑥의 0.30) 없이 1.0. 실증(report19·report15 2018+ 리플레이, 충실도 99.95%):
    # CAGR 14.70→15.50%(+0.8pp), 발동 17구간 중 10승 7패(증분 손익 합 +5.5%), **MDD -8.98→-11.08%**
    # (2018-02-27~03-21: 2월 저점 +5% 회복·200MA 회복 직후 3월 재하락 -7.5%를 풀포지션으로 통과),
