    # ---- 재학습 주기 & 시간감쇠 가중 (v1.2.0) ------------------------------
    # 요청: "2022년부터 매매판단, 예측한 날짜가 지나면 그 데이터도 학습에 추가, 오래된 데이터는
    #        영향을 줄이고 최신 데이터에 비중". REWEIGHT_FREQ 는 SIGNAL_START '이후' 구간에만 적용
    #        (그 이전 워밍업 구간은 기존처럼 연 1회 -- 27년치를 매주 재검증하면 수십 분이 걸려
    #        성능이 무너지고, 워밍업 구간의 목적은 백분위 안정화일 뿐 정밀도가 필요 없음).
    # [v1.2.0 실측 후 기본값 수정] 최초 설계(개선명세서 §4.2)는 "약 3초/회 x 240회 ≈ 12분"을
    # 가정해 기본값을 "W"(주1회)로 뒀다. 그러나 실제 구현(시간감쇠 IC/NW-t/AUC 계산 추가 +
    # DATA_START부터의 expanding 학습창이 매 재추정마다 계속 커짐)을 합성데이터로 실측한 결과,
    # 2022년 근방부터는 재추정 1회당 약 7~9초로 늘어나 SIGNAL_START~현재(약 4.7년, 주 단위
    # 약 240회) 전체를 "W"로 돌리면 총 30분을 넘길 수 있음을 확인했다. 하루~한주 단위의 미세한
    # 재검증 차이가 통계량에 주는 실질적 영향은 미미하므로(추정치가 매주 크게 바뀌지 않음),
    # 기본값을 "M"(월 1회, 약 56회)로 낮춰 총 실행시간을 약 10분 내외로 되돌렸다 — 정확도
    # 저하가 아니라 재추정 '빈도'만 낮춘 것이며, 매 재추정은 여전히 그 시점까지의 전체 이력을
    # 사용한다. "W"/"D"는 더 정밀한 재추정을 원하는 사용자가 여전히 선택할 수 있도록 유지한다.
    REWEIGHT_FREQ: str = "M"           # SIGNAL_START 이후 재추정 주기: "D"(매일)/"W"(주)/"M"(월,기본)
    # [v1.2.0 버그수정] 최초 설계(개선명세서 §4.3)는 "630일 ≈ 2.5년"이라 적었으나, 이는
    # 거래일(연 252일) 기준 환산(2.5*252=630)이었다. 그러나 decay_weights()는 아래 주석처럼
    # '달력일' 기준으로 age를 계산하므로(pandas Timestamp 뺄셈의 .days), 630을 달력일로
    # 쓰면 실제 반감기는 630/365.25 ≈ 1.73년으로, 의도했던 2.5년보다 데이터를 훨씬 빠르게
    # 감쇠시키는 잘못된 값이었다(06d 반감기민감도 시트를 만들며 라벨을 자동계산하다가 발견).
    # 달력일 기준으로 진짜 2.5년을 표현하려면 2.5*365.25 ≈ 913일이어야 한다 -> 기본값 수정.
    HALF_LIFE_DAYS: Optional[int] = 913  # 표본가중 반감기(달력일 기준, 2.5*365.25≈913일=2.5년). None=감쇠 없음
    N_EFF_MIN: int = 500               # 유효표본수(N_eff)가 이보다 작으면 그 시점 재추정을 건너뛰고 직전 가중치 유지
    # ---- 모드 -----------------------------------------------------------
    SELF_TEST: bool = False            # True = 합성데이터로 파이프라인 자체검증
    RUN_LOOKAHEAD_AUDIT: bool = True   # 룩어헤드 재계산 감사 실행
    AUDIT_SAMPLE: int = 12             # 감사 표본 날짜 수
    # [v1.2.0] 반감기 민감도(06d 시트)는 HALF_LIFE_DAYS 4케이스마다 walk-forward 전체를
    # 다시 계산해야 해 비용이 크다(기본 REWEIGHT_FREQ="M" 기준 케이스당 약 4~5분 추가).
    # [v1.4.0 §1(A) 성능 — 실사용 실측] 사용자 Colab 실행(market_regime_report_3.xlsx,
    # log3.txt)에서 전체 파이프라인 6,569.67초(109.5분) 중 4,939초(75%)가 이 반감기
    # 민감도 4케이스에서 소요됨을 확인(IMPROVEMENT_PLAN_v1.4.md §1). 06d 시트는 진단용
    # 참고 지표이고 결론("기본 913일이 최고성과 — 선택 운 배제 불가, 재튜닝 금지")은 이미
    # 확정돼 있어 매 실행마다 82분을 지불할 이유가 없다 -> 기본값을 False로 변경, 필요할
    # 때만 사용자가 명시적으로 True로 켠다(신호 로직 자체는 전혀 바뀌지 않음 — 성능 전용
    # 변경이므로 CHANGELOG의 ⚠ 신호 파라미터 플래그 대상 아님).
    RUN_HALF_LIFE_SENSITIVITY: bool = False
    # [v1.4.0 §1(A)] RUN_HALF_LIFE_SENSITIVITY=True로 켤 때, half_life_sensitivity()의 4개
    # 케이스는 진단(반감기 간 상대 비교)이 목적이므로 REWEIGHT_FREQ를 이 값으로 강제한다.
    # self_test()도 이미 동일 이유로 "A"를 쓴다(§8 v1.2.0 항목 참조) — 케이스당 재추정
    # 횟수가 크게 줄어(월간 재추정 대신 연간) 82분 -> 약 24분으로 단축되면서, 비교 대상은
    # 여전히 "같은 재추정 주기 하에서 반감기만 다른 4케이스"라 비교 자체의 유효성은 그대로
    # 유지된다(4케이스가 모두 동일 주기를 쓰므로 케이스 간 상대적 우열 비교에는 영향 없음).
    HL_SENS_REWEIGHT_FREQ: str = "A"
    # [v1.3.0 §7] 반감기 앙상블(선택적 강건화). market_regime_report_2.xlsx 06d 시트에서
    # 기본값(913일)이 4케이스 중 최고 성과를 보인 것이 관측되어(IMPROVEMENT_PLAN_v1.3.md §7),
    # 이것이 우연(선택 운)인지 구분하기 어렵다는 문제가 있었다. 이를 "반감기 재튜닝"으로
    # 해결하는 것은 데이터 스누핑이므로 금지하고, 대신 여러 반감기의 복합점수를 평균한
    # 앙상블을 06d 시트에 참고용으로만 병기한다. None(기본)이면 기존 동작과 완전히 동일—
    # 이 옵션을 켜도 실거래 신호 생성 로직(run() 본경로)에는 전혀 영향을 주지 않는다
    # (06d 시트 전용, RUN_HALF_LIFE_SENSITIVITY가 True일 때만 계산됨).
    ENSEMBLE_HALF_LIVES: Optional[List[int]] = None   # 예: [548, 913, 1461]
    # ---- [v1.22.0] 결과 데이터 번들 저장 (I/O 전용 — 신호 로직 무관) ------------------
    # main()이 build_report() 뒤에 run() 반환 dict 전체를 gzip 피클로 저장하고(Colab이면 엑셀과
    # 함께 자동 다운로드), sector_rotation.py v0.2가 이 파일을 입력으로 받아 M을 다시 돌리지
