# =============================================================================
# [1] 로깅 : [STAGE] [TIMESTAMP] key=value ...
# =============================================================================
class StageFormatter(logging.Formatter):
    def format(self, record: logging.LogRecord) -> str:
        stage = getattr(record, "stage", "GENERAL")
        ts = dt.datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        return f"[{stage:<9}] [{ts}] {record.getMessage()}"

def _build_logger(level: str = "INFO") -> logging.Logger:
    lg = logging.getLogger("MRT")
    lg.setLevel(getattr(logging, level))
    lg.handlers.clear()
    h = logging.StreamHandler(sys.stdout)
    h.setFormatter(StageFormatter())
    lg.addHandler(h)
    lg.propagate = False
    return lg

LOG = _build_logger(CFG.LOG_LEVEL)

def log(stage: str, msg: str, level: str = "info") -> None:
    getattr(LOG, level)(msg, extra={"stage": stage})

def kv(**kwargs) -> str:
    """key=value 형태 로그 문자열 생성."""
    parts = []
    for k, v in kwargs.items():
        if isinstance(v, float):
            v = f"{v:.4f}" if abs(v) < 1e4 else f"{v:.2f}"
        parts.append(f"{k}={v}")
    return " ".join(parts)


