# [2] 데이터 레이어
#     - Yahoo(가격/변동성지수) : 당일 종가에 확정 -> 발표지연 0일
#     - FRED(매크로/신용)      : 참조일 기준으로 배포되므로 반드시 발표지연을 적용해야 함
#       (이 처리를 빠뜨리면 '아직 발표되지 않은 값'을 보고 매매하는 룩어헤드가 발생한다)
# =============================================================================
# 매매대상 + 기존 6개 카테고리 계산에 직접 이름으로 참조되는 "커스텀 계산" 티커.
# (경기소비재 XLY / 필수소비재 XLP / 반도체 SMH 는 섹터 지표라 사용자 요청으로 이번 버전 제외.
#  재도입 시 여기에 다시 추가하고 build_indicators()의 "D. 크로스에셋" 블록에 XLY_XLP_MOM /
#  SMH_SPY_MOM 계산을 복원하면 된다.)
#
# [v1.2.0 §5.3 메모] 이번 버전은 신규 지표를 추가하지 않는다 — 진단 결과 문제는 지표
# "개수"가 아니라 "데이터 품질/검증 기준"이었기 때문(개선명세서 §0, §3 참조). 다음 버전
# 검토 후보로만 남겨둔다: CBOE 풋콜비율(Put/Call Ratio), NYSE 신고가-신저가(New Highs -
# New Lows), 마진부채(FINRA Margin Debt), MOVE 지수(채권시장 변동성). 이들은 Yahoo/FRED
# 무료 API로 직접 받기 어려워(별도 소스 필요) 이번 버전 범위에서 제외했다.
