# 매매대상 + 커스텀계산 티커 + 크로스에셋 자동생성 티커를 합쳐 실제 다운로드 목록을 만든다.
YAHOO_SERIES: Dict[str, str] = {**CURATED_YAHOO,
                                **{c.ticker: c.name_kr for c in CROSS_ASSET_SERIES}}


@dataclass
class MacroSeries:
    """자동생성 매크로 지표의 원천이 되는 FRED 시리즈."""
    sid: str
    name_kr: str
    category: str
    kind: str            # "rate"(이미 정상성에 가까운 %/스프레드, 절대차분) | "index"(추세를 갖는 레벨, 변화율)
    lag_days: int         # 발표지연(달력일). 안전을 위해 보수적으로(넉넉하게) 설정.
    prior_level: int      # 수준(z-score) 지표의 사전방향. 0이면 수준 지표 생략(비정상 추세라 무의미).
    prior_chg: int         # 변화 지표의 사전방향. 0이면 변화 지표 생략.
    rationale: str
    mechanism: str

