# [v1.2.0] FRED 데이터 무결성 검증용 "실제 데이터가 있어야 하는 가장 이른 날짜"(best-effort).
# 실사용 리포트(10_데이터품질)에서 BAML 신용스프레드 9개 시리즈 전체가 2023-09-05부터만 존재하는
# (원래는 1996~1997년부터 있어야 함) 치명적 데이터 절단이 발견되어, 이를 재발 방지하기 위한 게이트.
# 확신이 낮은 시리즈(SOFR/IORB 등 실제로 최근에 신설된 지표)는 일부러 넣지 않았다 —
# 오탐으로 정상 데이터를 제외하는 것보다 검증을 건너뛰는 쪽이 안전하다.
# [v1.3.0 주의] 여기 적힌 날짜는 시리즈의 "진짜 역사적" 시작일이다. 실제 다운로드는 항상
# cfg.DATA_START부터 요청되므로(fetch_fred/_fetch_fred_json이 observation_start/cosd로 명시),
# 이 표의 값을 그대로 "기대 시작일"로 비교하면 안 된다 — _check_fred_integrity()에서
# max(이 값, cfg.DATA_START)로 보정해서 사용한다 (§1 버그수정, 아래 함수 참조).
