def _ensure_cache_dir(cfg: Config = CFG) -> None:
    os.makedirs(cfg.CACHE_DIR, exist_ok=True)

def _cache_path(name: str, cfg: Config = CFG) -> str:
    safe = name.replace("^", "IDX_").replace("=", "_").replace(".", "_").replace("-", "_")
    # [v1.2.0] 캐시 스키마 버전을 파일명에 포함 — CACHE_SCHEMA_VERSION을 올리면 이전 버전에서
    # 저장된(잠재적으로 오염된) 캐시 파일은 자동으로 무시되고 새로 수집된다.
    return os.path.join(cfg.CACHE_DIR, f"v{cfg.CACHE_SCHEMA_VERSION}_{safe}.csv")

def _read_cache(name: str, max_age_hours: float = 12.0, cfg: Config = CFG) -> Optional[pd.DataFrame]:
    """불필요한 재다운로드 방지 (성능 요구사항: 변경 없는 데이터 재수신 금지).
    [v1.21.0 §A] max_age_hours=None 이면 나이를 무시하고 읽는다(지연캐시 대체용)."""
    p = _cache_path(name, cfg)
    if not os.path.exists(p):
        return None
    age_h = (time.time() - os.path.getmtime(p)) / 3600.0
    if max_age_hours is not None and age_h > max_age_hours:
        return None
    try:
        df = pd.read_csv(p, index_col=0, parse_dates=True)
        log("DATA", kv(event="cache_hit", series=name, rows=len(df), age_h=round(age_h, 2)), "debug")
        return df
    except Exception as e:
        log("DATA", kv(event="cache_read_fail", series=name, err=type(e).__name__), "warning")
        return None

def _write_cache(name: str, df: pd.DataFrame, cfg: Config = CFG) -> None:
    try:
        df.to_csv(_cache_path(name, cfg))
    except Exception as e:
        log("DATA", kv(event="cache_write_fail", series=name, err=type(e).__name__), "warning")

def _cache_age_hours(name: str, cfg: Config = CFG) -> Optional[float]:
    """[v1.15.1 §A] 캐시 파일 나이(시간). 없으면 None. 지연캐시 대체 시 경고/리포트에 노출용."""
    p = _cache_path(name, cfg)
    if not os.path.exists(p):
        return None
    return (time.time() - os.path.getmtime(p)) / 3600.0


_SESSION_CACHE: Dict[int, "requests.Session"] = {}

def _http_session(cfg: Config = CFG) -> "requests.Session":
    """
    [v1.1.0] 재시도/백오프가 내장된 공용 세션을 프로세스당 하나만 만들어 재사용한다.
    기존 코드는 단일 요청 타임아웃을 30초로 고정하고 실패 시 1.5~4.5초만 쉬고 3번 재시도했는데,
    Colab에서 관측된 실패 패턴은 '느린 응답'이 아니라 '연결이 아예 걸리는' 것이었다.
    -> 연결 타임아웃을 짧게 끊어(기본 10초) 빨리 포기하고, urllib3 레벨 백오프로 자동 재시도한다.
    """
    import requests
    from requests.adapters import HTTPAdapter
    try:
        from urllib3.util.retry import Retry
    except ImportError:                      # 구버전 urllib3 호환
        from requests.packages.urllib3.util.retry import Retry

    key = id(cfg)
    if key in _SESSION_CACHE:
        return _SESSION_CACHE[key]
    sess = requests.Session()
    # [v1.1.1 버그수정] 이전 버전은 여기(urllib3 Retry, total=FETCH_RETRIES)와 fetch_fred()의
    # 수동 for 루프(n_try=FETCH_RETRIES+1)가 이중으로 재시도해, 엔드포인트가 완전히 막힌 경우
    # 시리즈 1개당 최악 (내부 재시도 3회) x (외부 재시도 3회) = 최대 9번의 25초 타임아웃을 겪었다.
    # (실사용 로그에서 FRED CSV 배치 1건에 약 237초 소모, JSON API로 전환 전까지 낭비됨)
    # -> 어댑터 레벨 자동 재시도는 끄고(total=0), 재시도/백오프는 fetch_fred()의 수동 루프
    #    한 곳에서만 수행하도록 단일화.
    retry = Retry(total=0, status_forcelist=[429, 500, 502, 503, 504],
                  allowed_methods=frozenset(["GET"]))
    adapter = HTTPAdapter(max_retries=retry, pool_connections=cfg.FETCH_MAX_WORKERS,
                          pool_maxsize=cfg.FETCH_MAX_WORKERS)
    sess.mount("https://", adapter)
    sess.mount("http://", adapter)
    sess.headers.update({"User-Agent": "Mozilla/5.0 (research script; market_regime_trader)"})
    _SESSION_CACHE[key] = sess
    return sess


def _yahoo_degenerate(ticker: str, df: Optional[pd.DataFrame], cfg: Config = CFG) -> Tuple[bool, str]:
    """[v1.21.0 §A] Yahoo 프레임이 '퇴화 수집'(report22: ^VIX3M 1행)인지 판정. (퇴화여부, 사유).
    행수 < YAHOO_MIN_ROWS 이거나, 실제 시작일이 max(YAHOO_EXPECTED_START, DATA_START)보다
    PRICE_START_TOLERANCE_DAYS 이상 늦으면 퇴화. 예상시작이 없는 티커는 행수만 본다."""
    if df is None or len(df) == 0:
        return True, "빈 프레임"
    n = int(len(df))
    if n < cfg.YAHOO_MIN_ROWS:
        return True, f"행수 {n} < {cfg.YAHOO_MIN_ROWS}"
    exp = YAHOO_EXPECTED_START.get(ticker)
    if exp:
        expected_start = max(pd.Timestamp(exp), pd.Timestamp(cfg.DATA_START))
        actual_start = pd.Timestamp(df.index.min())
        late_by = (actual_start - expected_start).days
        if late_by > cfg.PRICE_START_TOLERANCE_DAYS:
            return True, f"실제시작 {actual_start.date()} vs 예상 {expected_start.date()} ({late_by}일 늦음)"
    return False, ""


def _yahoo_stale_fallback(ticker: str, cfg: Config = CFG,
                          diag: Optional[List[dict]] = None, reason: str = "") -> Optional[pd.DataFrame]:
    """[v1.21.0 §A(2)] 만료됐지만 정상 이력인 캐시를 지연캐시로 대체. 없거나 퇴화면 None."""
    if cfg.YAHOO_STALE_CACHE_MAX_DAYS <= 0:
        return None
    stale = _read_cache(f"YH_{ticker}", max_age_hours=cfg.YAHOO_STALE_CACHE_MAX_DAYS * 24.0, cfg=cfg)
    bad, why = _yahoo_degenerate(ticker, stale, cfg)
    if stale is None or bad:
        return None
    age_h = _cache_age_hours(f"YH_{ticker}", cfg) or 0.0
    log("DATA", kv(event="yahoo_stale_cache_used", series=ticker, rows=len(stale),
                   start=str(stale.index.min().date()), end=str(stale.index.max().date()),
                   cache_age_h=round(age_h, 1), reason=reason[:80]), "warning")
    if diag is not None:
        diag.append({"시리즈": ticker, "종류": "지연캐시", "사유": f"{reason} → 캐시 {age_h/24:.1f}일 전 이력으로 대체",
                     "행수": int(len(stale)), "시작": str(stale.index.min().date()), "종료": str(stale.index.max().date())})
    return stale


def fetch_yahoo(ticker: str, cfg: Config = CFG, retries: Optional[int] = None,
                use_cache: bool = True, diag: Optional[List[dict]] = None) -> Optional[pd.DataFrame]:
    """단일 Yahoo 티커 다운로드(순차, 스레드 미사용). 배치 다운로드에서 빠진 티커의 개별
    재시도 용도로 쓰인다. 실패 시 None (조용히 실패하지 않고 로그 남김).
    [v1.21.0 §A] 퇴화 수집(_yahoo_degenerate)은 성공으로 치지 않고 캐시에도 쓰지 않는다 —
    재시도 후에도 퇴화면 지연캐시 대체를 시도하고, 그것도 없으면 None."""
    if use_cache:
        cached = _read_cache(f"YH_{ticker}", cfg=cfg)
        if cached is not None and len(cached) > 0:
            bad, why = _yahoo_degenerate(ticker, cached, cfg)
            if not bad:
                return cached
            log("DATA", kv(event="yahoo_cache_degenerate_ignored", series=ticker, rows=len(cached),
                           reason=why), "warning")
    try:
        import yfinance as yf
    except ImportError:
        log("DATA", kv(event="import_fail", pkg="yfinance", action="pip install yfinance"), "error")
        return None

    n_try = (retries if retries is not None else cfg.FETCH_RETRIES) + 1  # 최초 1회 + 재시도
    end = cfg.DATA_END or (dt.date.today() + dt.timedelta(days=1)).isoformat()
    t0 = time.time()
    for attempt in range(1, n_try + 1):
        try:
            df = yf.download(ticker, start=cfg.DATA_START, end=end,
                             auto_adjust=False, progress=False, threads=False,
                             timeout=cfg.FETCH_TIMEOUT_READ)
            if df is None or len(df) == 0:
                raise ValueError("empty frame")
            if isinstance(df.columns, pd.MultiIndex):          # yfinance 버전별 컬럼 형태 흡수
                df.columns = df.columns.get_level_values(0)
            df = df.loc[~df.index.duplicated(keep="last")].sort_index()
            df.index = pd.to_datetime(df.index).tz_localize(None)
            df = df.dropna(how="all")
            if len(df) == 0:
                raise ValueError("empty frame after dropna")
            bad, why = _yahoo_degenerate(ticker, df, cfg)
            if bad:   # [v1.21.0 §A(1)] 퇴화 수집은 성공이 아니다 — 캐시에 쓰지 않고 재시도
                raise ValueError(f"degenerate: {why}")
            _write_cache(f"YH_{ticker}", df, cfg)
            log("DATA", kv(event="yahoo_ok", series=ticker, rows=len(df),
                           start=str(df.index[0].date()), end=str(df.index[-1].date()),
                           elapsed_s=round(time.time() - t0, 1)))
            return df
        except Exception as e:
            log("DATA", kv(event="yahoo_retry", series=ticker, attempt=attempt, of=n_try,
                           err=type(e).__name__, msg=str(e)[:80]), "warning")
            if attempt < n_try:
                time.sleep(min(1.2 * attempt, 5.0))
    stale = _yahoo_stale_fallback(ticker, cfg, diag, reason="개별 재시도 전부 실패/퇴화")
    if stale is not None:
        return stale
    log("DATA", kv(event="yahoo_fail", series=ticker, elapsed_s=round(time.time() - t0, 1),
                   next_step="해당 지표는 자동 제외되고 나머지 지표로 진행됩니다"
                             "(신호핵심 티커면 run()의 게이트가 중단)"), "error")
    if diag is not None:
        diag.append({"시리즈": ticker, "종류": "제외", "사유": "다운로드 실패/퇴화(지연캐시 없음)",
                     "행수": 0, "시작": "-", "종료": "-"})
    return None


def _check_fred_integrity(series_id: str, s: pd.Series, cfg: Config = CFG) -> Tuple[str, str]:
    """[v1.2.0] 실제 데이터 시작일이 FRED_EXPECTED_START 대비 비정상적으로 늦는지 확인.
    (실사용 리포트에서 BAML 신용스프레드 9개가 2023-09-05부터만 존재하던 절단 사고 재발 방지)

    [v1.3.0 버그수정 — 치명] v1.2.0은 FRED_EXPECTED_START의 "진짜 역사적 시작일"(예: UNRATE
    1948-01-01)을 그대로 기대 시작일로 썼다. 그런데 실제 다운로드는 항상 cfg.DATA_START
    (기본 1990-01-01)부터 요청되므로, 1990년 이전부터 존재하던 시리즈는 "정상적으로" 1990년
    데이터부터 받아놓고도 late_by가 수만일로 계산되어 전부 무결성 실패로 제외되고 있었다
    (실사용 리포트 10_데이터품질에서 DGS3MO/DGS10/NFCI/UNRATE/CPIAUCSL 등 23개 시리즈가
    이 자기모순으로 몰살된 것을 확인 — IMPROVEMENT_PLAN_v1.3.md §1).
    이 함수는 "다운로드가 요청한 범위보다 실제 응답이 늦게 시작하는가"만 확인하면 되므로,
    비교 기준을 max(역사적 시작일, DATA_START)로 승격해 게이트 본연의 목적(BAML처럼 요청한
    범위보다 훨씬 늦게 시작하는 절단 응답 탐지)만 남긴다.

    [v1.4.0 §2] 반환 타입을 bool -> str 상태값(3종)으로 확장했다(유일한 호출부 fetch_fred()도
    함께 갱신, 하위 호출자 없음 — 확인됨).
      "OK"    — 정상(무결성 통과, 기존 True와 동일 의미)
      "SHORT" — cfg.FRED_ALLOW_SHORT_HISTORY에 등재된 시리즈가 예상보다 늦게 시작(기존이라면
                "FAIL"이었을 상황)했지만, 이는 이 시리즈에 대해 FRED가 구조적으로 짧은 이력만
                반환한다고 이미 확인된 것(§2 근거는 fetch_fred() 주석)이므로 "무결성 실패"가
                아니라 "단축이력 수용"으로 분류한다 — 다운로드된 데이터 자체는 신뢰할 수 있다.
      "FAIL"  — 등재되지 않은 시리즈가 예상보다 늦게 시작(기존 False와 동일 의미, 여전히 제외)
    """
    exp = FRED_EXPECTED_START.get(series_id)
    if exp is None or s is None or len(s.dropna()) == 0:
        return "OK", "체크대상아님"
    actual_start = s.dropna().index.min()
    # [v1.3.0] DATA_START 이전 데이터는 애초에 요청되지 않으므로, 기대 시작일이 DATA_START보다
    # 이를 수 없다 — 두 값 중 늦은 쪽을 기준으로 삼는다.
    expected_start = max(pd.Timestamp(exp), pd.Timestamp(cfg.DATA_START))
    late_by = (actual_start - expected_start).days
    if late_by > cfg.FRED_START_TOLERANCE_DAYS:
        msg = f"실제시작 {actual_start.date()} vs 예상 {expected_start.date()} ({late_by}일 늦음)"
        if series_id in cfg.FRED_ALLOW_SHORT_HISTORY:
            return "SHORT", msg
        return "FAIL", msg
    return "OK", "OK"


def _fetch_fred_json(series_id: str, cfg: Config, sess: "requests.Session",
                     ranged: bool = True) -> Optional[pd.Series]:
    """FRED_API_KEY가 설정된 경우의 JSON API 경로. CSV 그래프 엔드포인트와 인프라 경로가 달라
    한쪽이 막혀도 다른 쪽은 통과하는 경우가 있다.
    [v1.2.0] observation_start/observation_end 를 명시한다 — 미지정 시 일부 환경에서 기본
    관측범위만 반환되어 BAML 신용스프레드 등 장기 시리즈가 최근 몇 년치로 절단되는 문제가
    있었다(사용자 실행 리포트에서 재현).
    [v1.3.0] ranged=False 변형 추가 — v1.2.0은 "범위 파라미터 미지정"을 절단의 원인으로 추정해
    지정하는 쪽으로만 고쳤지만, BAML 9개는 v1.2.0에서도 여전히 수집되지 않았다(원인 미확정).
    범위 파라미터 자체가 문제인 환경(예: 캐싱 프록시가 쿼리스트링 있는 요청만 다르게 처리)도
    배제할 수 없으므로, §2 다전략 폴백에서 두 변형을 모두 시도해 실제 원인이 무엇이든 자동으로
    우회하도록 한다."""
    if not cfg.FRED_API_KEY:
        return None
    url = ("https://api.stlouisfed.org/fred/series/observations"
          f"?series_id={series_id}&api_key={cfg.FRED_API_KEY}&file_type=json")
    if ranged:
        end = cfg.DATA_END or dt.date.today().isoformat()
        url += f"&observation_start={cfg.DATA_START}&observation_end={end}"
    r = sess.get(url, timeout=(cfg.FETCH_TIMEOUT_CONNECT, cfg.FETCH_TIMEOUT_READ))
    r.raise_for_status()
    obs = r.json().get("observations", [])
    if not obs:
        return None
    df = pd.DataFrame(obs)
    df["date"] = pd.to_datetime(df["date"], errors="coerce")
    df["value"] = pd.to_numeric(df["value"].replace(".", np.nan), errors="coerce")
    s = df.dropna(subset=["date"]).set_index("date")["value"].astype(float)
    s = s[~s.index.duplicated(keep="last")].sort_index()
    s.name = series_id
    return s


def _fetch_fred_csv(series_id: str, cfg: Config, sess: "requests.Session",
                    ranged: bool = True) -> Optional[pd.Series]:
    """[v1.3.0] fetch_fred()에 인라인돼 있던 CSV(fredgraph.csv) 다운로드 로직을 재사용 가능한
    함수로 분리했다 — §2 다전략 폴백에서 CSV+범위지정/CSV+미지정 두 변형으로 호출된다.
    ranged=False는 cosd/coed(관측기간) 파라미터를 아예 빼고 요청한다(§2 이유는
    _fetch_fred_json의 동일 인자 설명과 같음: 원인이 범위 파라미터 자체일 가능성 배제)."""
    url = f"https://fred.stlouisfed.org/graph/fredgraph.csv?id={series_id}"
    if ranged:
        end = cfg.DATA_END or dt.date.today().isoformat()
        url += f"&cosd={cfg.DATA_START}&coed={end}"
    r = sess.get(url, timeout=(cfg.FETCH_TIMEOUT_CONNECT, cfg.FETCH_TIMEOUT_READ))
    r.raise_for_status()
    raw = pd.read_csv(io.StringIO(r.text))
    date_col, val_col = raw.columns[0], raw.columns[1]
    raw[date_col] = pd.to_datetime(raw[date_col], errors="coerce")
    raw[val_col] = pd.to_numeric(raw[val_col].replace(".", np.nan), errors="coerce")
    s = raw.dropna(subset=[date_col]).set_index(date_col)[val_col].astype(float)
    s = s[~s.index.duplicated(keep="last")].sort_index()
    s.name = series_id
    if len(s) == 0:
        raise ValueError("empty series")
    return s


# [v1.4.0 §1(C)] CSV 경로 회로차단기 — 한 배치(fetch_all_fred 1회 호출) 안에서 CSV 시도가
# 연속으로 ConnectionError를 내면(=경로 자체가 이 네트워크 환경에서 막혀 있다는 신호), 그
# 배치의 나머지 시리즈는 CSV 전략을 건너뛴다. 여러 시리즈가 ThreadPoolExecutor로 동시에
# fetch_fred()를 호출하므로 카운터는 락으로 보호한다. JSON 경로가 없는 환경(FRED_API_KEY
# 미설정)에서는 CSV가 유일한 경로이므로 회로를 열지 않는다(fetch_fred() 쪽에서 가드).
_CSV_CIRCUIT_LOCK = threading.Lock()
_CSV_CIRCUIT_STATE: Dict[int, int] = {}

def _csv_circuit_reset(cfg: Config = CFG) -> None:
    with _CSV_CIRCUIT_LOCK:
        _CSV_CIRCUIT_STATE[id(cfg)] = 0

def _csv_circuit_is_open(cfg: Config = CFG) -> bool:
    with _CSV_CIRCUIT_LOCK:
        return _CSV_CIRCUIT_STATE.get(id(cfg), 0) >= cfg.CSV_CIRCUIT_BREAKER_THRESHOLD

def _csv_circuit_record_failure(cfg: Config = CFG) -> None:
    with _CSV_CIRCUIT_LOCK:
        _CSV_CIRCUIT_STATE[id(cfg)] = _CSV_CIRCUIT_STATE.get(id(cfg), 0) + 1

def _csv_circuit_record_success(cfg: Config = CFG) -> None:
    with _CSV_CIRCUIT_LOCK:
        _CSV_CIRCUIT_STATE[id(cfg)] = 0


# [v1.4.0 §1(C)] 실패 확정 시리즈의 네거티브 캐시 — data_integrity_fail(등재되지 않은 시리즈의
# 무결성 실패, 또는 4경로 전체 다운로드 실패)로 제외가 확정되면 그 사유를 기록해두고,
# FRED_FAILURE_CACHE_HOURS(기본 20시간, 대략 "당일") 이내 재실행에서는 재시도 없이 즉시
# 제외한다 — 원인이 서버 쪽 구조적 제한(§2)일 때 매 실행마다 같은 4~8회 왕복(최대 ~190초)을
# 반복하는 낭비를 막는다. _read_cache/_write_cache(기존 캐시 인프라)를 그대로 재사용한다.
def _read_fred_failure_cache(series_id: str, cfg: Config = CFG) -> Optional[str]:
    cached = _read_cache(f"FRED_FAIL_{series_id}", max_age_hours=cfg.FRED_FAILURE_CACHE_HOURS, cfg=cfg)
    if cached is not None and len(cached) > 0 and "사유" in cached.columns:
        return str(cached["사유"].iloc[0])
    return None

def _write_fred_failure_cache(series_id: str, reason: str, cfg: Config = CFG) -> None:
    _write_cache(f"FRED_FAIL_{series_id}", pd.DataFrame({"사유": [reason]}), cfg)


def fetch_fred(series_id: str, cfg: Config = CFG, retries: Optional[int] = None,
               _integrity_retry: bool = False,
               diag: Optional[List[dict]] = None,
               _prior_attempts: Optional[List[str]] = None) -> Optional[pd.Series]:
    """FRED 다운로드. 반환 index는 '참조일'이며 발표지연은 뒤에서 적용한다.

    [v1.1.1] FRED_API_KEY가 설정돼 있으면 JSON API를 먼저 시도하고(사용자 환경에서 CSV
    엔드포인트가 100% 타임아웃, JSON API는 즉시 성공하는 패턴이 관측됨), CSV는 키가 없거나
    JSON도 실패했을 때만 폴백으로 쓴다.
    [v1.2.0] CSV 폴백 URL에 cosd/coed(관측기간)를 명시하고, 두 경로 모두 성공 후
    _check_fred_integrity()로 시작일이 비정상적으로 늦지 않은지 확인한다.

    [v1.3.0 §2] v1.2.0은 그래도 BAML 신용스프레드 9개를 계속 수집하지 못했다(원인 미확정 —
    범위 파라미터 자체 문제인지, 두 엔드포인트 모두 막힌 것인지 로그만으로는 알 수 없었다).
    "경로가 원인이든 무엇이든 자동으로 우회"하도록 4가지 독립 전략을 순서대로 시도하고,
    _check_fred_integrity()를 통과하는 첫 결과를 채택한다:
      1) JSON+범위지정 (FRED_API_KEY 있을 때만) 2) JSON+미지정 (〃) 3) CSV+범위지정 4) CSV+미지정
    네 전략 모두 실패(다운로드 자체 실패 또는 전부 무결성 실패)하면 캐시를 거치지 않은 상태이므로
    전체를 1회 자동 재시도하고(_integrity_retry), 그래도 실패하면 해당 시리즈를 제외한다.
    diag가 주어지면 제외 시 사유·시도한 경로·마지막으로 확보한 응답범위를 딕셔너리로 append한다
    (10_데이터품질의 "제외된 FRED 시리즈" 표에 노출하기 위함 — 이전 버전은 이 실패를 로그에만
    남기고 리포트에서는 조용히 사라져, BAML이 왜 없는지 리포트만으로는 알 수 없었다).

    [v1.4.0 §2] IMPROVEMENT_PLAN_v1.4.md §2로 원인이 확정됐다 — BAML 9종은 JSON 양쪽 변형
    모두 "2023-09-01부터만" 반환한다(서버가 이 시리즈군의 공개 이력을 최근 3년으로 제한하는
    것으로 추정, log3.txt에서 두 변형이 완전히 동일한 절단일을 반환함을 확인). CSV는 이
    환경에서 4경로 전부 ConnectionError라 대안이 아니다. 그래서 §1(C)/§2를 함께 구현한다:
    _check_fred_integrity()가 cfg.FRED_ALLOW_SHORT_HISTORY 등재 시리즈에 대해 "SHORT"를
    반환하면, 다운로드 자체는 성공했으므로 그 즉시 정상 채택하고(제외하지 않음) diag에는
    "단축이력" 유형으로 기록한다(10_데이터품질에서 "[FRED제외]"가 아니라 "[단축이력]"으로
    구분 표시). 등재되지 않은 시리즈가 늦게 시작하면 기존과 동일하게 "FAIL"로 제외된다.

    [v1.4.0 §1(C)] 세 가지 낭비 제거를 추가했다: (1) 이 함수 진입 시 네거티브 캐시
    (_read_fred_failure_cache)를 확인해, 최근 FRED_FAILURE_CACHE_HOURS 이내 제외가 확정된
    시리즈는 재시도 없이 즉시 제외한다. (2) CSV 경로가 이 배치에서 연속으로
    ConnectionError를 내면(_csv_circuit_is_open) 나머지 시리즈는 CSV 전략을 건너뛴다
    (FRED_API_KEY가 없어 CSV가 유일한 경로일 때는 회로를 열지 않는다). (3) JSON 두 변형이
    동일한 무결성실패 메시지를 반환하면(서버가 구조적으로 그렇게 주는 것이 확실하므로) 전체
    재시도 라운드(_integrity_retry)를 생략한다.

    [v1.15.1 §A] report16 사고(FRED 0/54 — Config 주석 참조) 대응 세 가지: (1) 전 경로가
    '전송 실패'(best_fail 없음)면 FRED_STALE_CACHE_MAX_DAYS 이내의 만료 캐시를 지연캐시로
    대체 채택하고 diag 종류 "지연캐시"로 기록한다. (2) 네거티브 캐시는 무결성 실패(서버 구조
    문제)에만 기록하고 전송 실패에는 기록하지 않는다 — 일시 장애를 20시간 동안 고정하는
    2차 피해 방지. (3) 재시도 라운드에서 diag를 쓸 때 1차 라운드의 시도 경로(_prior_attempts)
    를 함께 남긴다 — report16의 10시트에는 2차(회로 열린 뒤) JSON 2경로만 보여 CSV가 시도
    됐는지조차 리포트로 알 수 없었다."""
    cached = _read_cache(f"FRED_{series_id}", cfg=cfg)
    if cached is not None and len(cached) > 0:
        return cached.iloc[:, 0]
    # [v1.4.0 §1(C)] 네거티브 캐시 — 최근 제외 확정된 시리즈는 재시도하지 않는다.
    if not _integrity_retry:
        cached_fail = _read_fred_failure_cache(series_id, cfg)
        if cached_fail is not None:
            log("DATA", kv(event="fred_skip_cached_failure", series=series_id,
                           reason=cached_fail, retry_after_h=cfg.FRED_FAILURE_CACHE_HOURS),
                "warning")
            if diag is not None:
                diag.append({"시리즈": series_id, "사유": f"{cached_fail} (캐시됨 — 재시도 생략)",
                            "시도한경로": "-(네거티브 캐시 히트)", "응답범위": "-", "종류": "제외"})
            return None
    sess = _http_session(cfg)
    t0 = time.time()

    skip_csv = bool(cfg.FRED_API_KEY) and _csv_circuit_is_open(cfg)
    strategies: List[Tuple[str, Callable[[], Optional[pd.Series]]]] = []
    if cfg.FRED_API_KEY:
        strategies.append(("JSON+범위지정", lambda: _fetch_fred_json(series_id, cfg, sess, ranged=True)))
        strategies.append(("JSON+미지정", lambda: _fetch_fred_json(series_id, cfg, sess, ranged=False)))
    if not skip_csv:
        strategies.append(("CSV+범위지정", lambda: _fetch_fred_csv(series_id, cfg, sess, ranged=True)))
        strategies.append(("CSV+미지정", lambda: _fetch_fred_csv(series_id, cfg, sess, ranged=False)))
    elif diag is None:
        log("DATA", kv(event="fred_csv_circuit_open", series=series_id,
                       threshold=cfg.CSV_CIRCUIT_BREAKER_THRESHOLD), "debug")

    attempts: List[str] = []
    best_fail: Optional[Tuple[str, pd.Series]] = None   # 다운로드는 됐지만 무결성 실패한 최선 후보
    json_fail_msgs: List[str] = []   # [v1.4.0 §1(C)] JSON 두 변형의 무결성실패 메시지 일치 확인용
    s: Optional[pd.Series] = None
    chosen: Optional[str] = None
    short_history = False   # [v1.4.0 §2] True면 "SHORT"로 채택된 것(정상이지만 이력이 짧음)
    skip_retry_round = False
    for name, fn in strategies:
        try:
            got = fn()
        except Exception as e:
            # [v1.3.0 §2 안전판] HTTP 429(rate limit)는 다른 실패와 성격이 다르다 — 엔드포인트가
            # 막힌 게 아니라 "잠시 후 다시 시도하면 되는" 신호이므로, 다음 전략으로 즉시 넘어가지
            # 않고 60초 대기 후 같은 전략을 1회만 재시도한다. ThreadPoolExecutor로 여러 시리즈가
            # 동시에 이 경로를 타도 대기는 병렬로 겹치므로 배치 전체 지연은 약 60초 선에서 그친다.
            status = getattr(getattr(e, "response", None), "status_code", None)
            if status == 429:
                log("DATA", kv(event="fred_rate_limited", series=series_id, strategy=name,
                               wait_s=60), "warning")
                time.sleep(60)
                try:
                    got = fn()
                except Exception as e2:
                    attempts.append(f"{name}:다운로드실패({type(e2).__name__}, 429재시도후)")
                    if name.startswith("CSV"):
                        _csv_circuit_record_failure(cfg)
                    continue
            else:
                attempts.append(f"{name}:다운로드실패({type(e).__name__})")
                # [v1.4.0 §1(C)] ConnectionError류는 CSV 경로가 이 환경에서 막혔다는 신호로
                # 취급한다 — CSV 전략에서만 카운트(JSON 실패는 다른 원인일 수 있어 제외).
                if name.startswith("CSV"):
                    _csv_circuit_record_failure(cfg)
                continue
        if got is None or len(got) == 0:
            attempts.append(f"{name}:빈응답")
            continue
        if name.startswith("CSV"):
            _csv_circuit_record_success(cfg)
        fred_status, msg = _check_fred_integrity(series_id, got, cfg)
        if fred_status == "OK":
            s, chosen = got, name
            attempts.append(f"{name}:OK")
            break
        if fred_status == "SHORT":
            # [v1.4.0 §2] 다운로드 자체는 성공했고, 이 시리즈는 구조적으로 짧은 이력만 반환되는
            # 것으로 이미 확인된 것(FRED_ALLOW_SHORT_HISTORY) — 정상 채택하고 루프를 끝낸다.
            s, chosen, short_history = got, name, True
            attempts.append(f"{name}:단축이력수용({msg})")
            break
        attempts.append(f"{name}:무결성실패({msg})")
        if best_fail is None:
            best_fail = (msg, got)
        if name.startswith("JSON"):
            json_fail_msgs.append(msg)

    # [v1.4.0 §1(C)] JSON 두 변형이 완전히 동일한 무결성실패 메시지를 반환했다면 서버가
    # 구조적으로 그렇게 주는 것이 확실하므로(우연/일시적 오류가 아님), 전체 재시도 라운드를
    # 생략하고 바로 최종 판정으로 넘어간다.
    if len(json_fail_msgs) == 2 and json_fail_msgs[0] == json_fail_msgs[1]:
        skip_retry_round = True

    elapsed = round(time.time() - t0, 1)

    if s is None:
        if not _integrity_retry and not skip_retry_round:
            log("DATA", kv(event="data_integrity_retry", series=series_id,
                           attempts=" | ".join(attempts), elapsed_s=elapsed), "warning")
            return fetch_fred(series_id, cfg, retries, _integrity_retry=True, diag=diag,
                              _prior_attempts=list(attempts))
        # [v1.15.1 §A] 1차+2차 라운드의 시도 경로를 모두 남긴다(추적성).
        attempts_txt = (f"1차[{' | '.join(_prior_attempts)}] → 2차[{' | '.join(attempts)}]"
                        if _prior_attempts else " | ".join(attempts))
        reason = (f"무결성실패({best_fail[0]})" if best_fail is not None
                  else f"다운로드실패({len(strategies)}개 경로 모두 실패)")
        if skip_retry_round and not _integrity_retry:
            log("DATA", kv(event="fred_retry_round_skipped", series=series_id,
                           reason="JSON 양쪽 변형 동일 무결성실패"), "warning")
        resp_range = "-"
        if best_fail is not None:
            bs = best_fail[1].dropna()
            if len(bs):
                resp_range = f"{bs.index.min().date()}~{bs.index.max().date()}({len(bs)}행)"

        # [v1.15.1 §A(1)] 전송 실패(다운로드 자체가 안 됨 — 무결성 실패가 아님)면 최근
        # FRED_STALE_CACHE_MAX_DAYS 이내의 만료 캐시를 지연캐시로 대체한다. 지표가 며칠
        # 늦는 것은 "지표가 아예 없음"(report16: 가격만으로 신호 생성)보다 훨씬 낫다. 반드시
        # 경고 로그 + diag(10시트 [지연캐시])에 드러낸다(조용한 대체 금지).
        if best_fail is None and cfg.FRED_STALE_CACHE_MAX_DAYS > 0:
            stale = _read_cache(f"FRED_{series_id}",
                                max_age_hours=cfg.FRED_STALE_CACHE_MAX_DAYS * 24.0, cfg=cfg)
            if stale is not None and len(stale) > 0:
                age_h = _cache_age_hours(f"FRED_{series_id}", cfg) or 0.0
                st = stale.iloc[:, 0].dropna()
                st_range = (f"{st.index.min().date()}~{st.index.max().date()}({len(st)}행)"
                            if len(st) else "-")
                log("DATA", kv(event="fred_stale_cache_fallback", series=series_id,
                               cache_age_h=round(age_h, 1), rows=int(len(st)),
                               last_obs=str(st.index.max().date()) if len(st) else "-",
                               attempts=attempts_txt, elapsed_s=elapsed,
                               next_step="네트워크/FRED 복구 후 재실행하면 최신값으로 갱신됩니다"),
                    "warning")
                if diag is not None:
                    diag.append({"시리즈": series_id,
                                "사유": f"지연캐시 대체: 다운로드 실패로 {age_h/24.0:.1f}일 전 캐시 사용"
                                         f"(최종관측 {st.index.max().date() if len(st) else '-'}) "
                                         f"— FRED_STALE_CACHE_MAX_DAYS={cfg.FRED_STALE_CACHE_MAX_DAYS:.0f}",
                                "시도한경로": attempts_txt, "응답범위": st_range, "종류": "지연캐시"})
                return stale.iloc[:, 0]

        log("DATA", kv(event="data_integrity_fail", series=series_id, reason=reason,
                       attempts=attempts_txt, elapsed_s=elapsed,
                       next_step="해당 시리즈는 제외되고 나머지 지표로 진행됩니다"), "error")
        if diag is not None:
            diag.append({"시리즈": series_id, "사유": reason,
                        "시도한경로": attempts_txt, "응답범위": resp_range, "종류": "제외"})
        # [v1.4.0 §1(C)] 네거티브 캐시 기록 — [v1.15.1 §A(2)] 무결성 실패(서버 구조 문제)에만.
        # 전송 실패는 일시적일 수 있으므로 기록하지 않는다(복구 후 재실행이 즉시 정상화되도록).
        if best_fail is not None:
            _write_fred_failure_cache(series_id, reason, cfg)
        else:
            log("DATA", kv(event="fred_failure_cache_skipped", series=series_id,
                           reason="전송 실패는 네거티브 캐시 미기록(일시 장애 가능)"), "debug")
        return None

    if short_history:
        # [v1.4.0 §2] 제외가 아니라 수용 — 하지만 이력이 짧다는 사실은 로그와 리포트(10시트)에
        # 반드시 남긴다(사용자 지침: 조용히 사라지는 처리 금지, 투명성/추적성).
        log("DATA", kv(event="fred_short_history", series=series_id, via=chosen,
                       rows=int(s.notna().sum()), start=str(s.dropna().index.min().date()),
                       end=str(s.dropna().index.max().date()), elapsed_s=elapsed), "warning")
        if diag is not None:
            diag.append({"시리즈": series_id,
                        "사유": f"단축이력 수용: {s.dropna().index.min().date()}부터 "
                                 f"({int(s.notna().sum())}행) — FRED_ALLOW_SHORT_HISTORY, "
                                 f"IMPROVEMENT_PLAN_v1.4.md §2",
                        "시도한경로": " | ".join(attempts),
                        "응답범위": f"{s.dropna().index.min().date()}~{s.dropna().index.max().date()}"
                                    f"({int(s.notna().sum())}행)",
                        "종류": "단축이력"})
    else:
        log("DATA", kv(event="fred_ok", series=series_id, via=chosen, rows=int(s.notna().sum()),
                       start=str(s.dropna().index.min().date()), end=str(s.dropna().index.max().date()),
                       elapsed_s=elapsed))
    _write_cache(f"FRED_{series_id}", s.to_frame(), cfg)
    return s


def fetch_all_yahoo(tickers: List[str], cfg: Config = CFG,
                    diag: Optional[List[dict]] = None) -> Dict[str, Optional[pd.DataFrame]]:
    """
    [v1.2.0 버그수정] v1.1.0의 ThreadPoolExecutor 기반 병렬 다운로드가 yfinance의 스레드 안전성
    부족과 맞물려 티커 간 가격 데이터가 서로 뒤섞이는 교차오염을 일으켰다(실사용 리포트에서
    "SPY" 종가가 실제로는 RSP 가격으로, HYG/IEF/VVIX/VIX9D가 상장 전 날짜부터 존재하는 것으로
    확인됨 — 여러 앱 레벨 스레드가 yfinance의 공유 세션/전역 상태를 동시에 건드린 결과로 추정).
    -> 앱 레벨 스레드풀을 완전히 제거하고, yfinance 자체의 다중 티커 배치 API(단일 프로세스 호출,
    threads=True는 yfinance 내부에서만 사용 — 이 경로는 안전하게 설계돼 있다)로 한 번에 받는다.
    배치에서 빠지거나 실패한 티커만 순차로 개별 재시도한다(fetch_yahoo, 스레드 미사용).
    """
    t0 = time.time()
    out: Dict[str, Optional[pd.DataFrame]] = {}
    to_fetch: List[str] = []
    degenerate: Dict[str, str] = {}   # [v1.21.0 §A] 배치에서 퇴화로 판정된 티커 → 사유
    for t in tickers:
        cached = _read_cache(f"YH_{t}", cfg=cfg)
        if cached is not None and len(cached) > 0:
            bad, why = _yahoo_degenerate(t, cached, cfg)
            if bad:   # [v1.21.0 §A(1)] 12시간 이내 캐시라도 퇴화면(report22의 1행 캐시) 무시하고 재수집
                log("DATA", kv(event="yahoo_cache_degenerate_ignored", series=t, rows=len(cached), reason=why), "warning")
                to_fetch.append(t)
            else:
                out[t] = cached
        else:
            to_fetch.append(t)

    if to_fetch:
        try:
            import yfinance as yf
            end = cfg.DATA_END or (dt.date.today() + dt.timedelta(days=1)).isoformat()
            raw = yf.download(to_fetch, start=cfg.DATA_START, end=end, auto_adjust=False,
                              progress=False, group_by="ticker", threads=True,
                              timeout=cfg.FETCH_TIMEOUT_READ)
            for t in to_fetch:
                try:
                    if len(to_fetch) == 1:
                        sub = raw
                    else:
                        if t not in raw.columns.get_level_values(0):
                            continue
                        sub = raw[t]
                    sub = sub.dropna(how="all")
                    if len(sub) == 0:
                        continue
                    sub = sub.loc[~sub.index.duplicated(keep="last")].sort_index()
                    sub.index = pd.to_datetime(sub.index).tz_localize(None)
                    bad, why = _yahoo_degenerate(t, sub, cfg)
                    if bad:   # [v1.21.0 §A(1)] 퇴화 수집 — 캐시에 쓰지 않고 개별 재시도 대상으로
                        degenerate[t] = why
                        log("DATA", kv(event="yahoo_batch_degenerate", series=t, rows=len(sub),
                                       start=str(sub.index[0].date()), reason=why,
                                       action="캐시 미기록 → 개별 재시도 → 지연캐시 대체"), "warning")
                        continue
                    _write_cache(f"YH_{t}", sub, cfg)
                    out[t] = sub
                    log("DATA", kv(event="yahoo_ok", series=t, rows=len(sub),
                                   start=str(sub.index[0].date()), end=str(sub.index[-1].date()),
                                   elapsed_s=round(time.time() - t0, 1)))
                except Exception as e:
                    log("DATA", kv(event="yahoo_batch_split_error", series=t,
                                   err=type(e).__name__), "warning")
        except Exception as e:
            log("DATA", kv(event="yahoo_batch_fail", tickers=",".join(to_fetch),
                           err=type(e).__name__, msg=str(e)[:120]), "warning")

    # 배치에서 못 받은 티커만 순차 개별 재시도 (스레드 미사용 — 교차오염 원천 차단)
    # [v1.21.0 §A(2)] 퇴화 수집 티커도 여기서 단일 티커 재수집(배치 API가 일부 심볼을 당일 1행만
    # 돌려주는 Yahoo 측 간헐 장애는 단일 호출에서 정상인 경우가 많다) → 그래도 퇴화면 지연캐시.
    still_missing = [t for t in to_fetch if out.get(t) is None]
    if degenerate and cfg.YAHOO_CRITICAL_RETRY_WAIT_S >= 0:
        time.sleep(cfg.YAHOO_CRITICAL_RETRY_WAIT_S)
    for t in still_missing:
        out[t] = fetch_yahoo(t, cfg, use_cache=False, diag=diag)
        if out[t] is not None and t in degenerate and diag is not None:
            kind = "지연캐시" if any(d.get("시리즈") == t and d.get("종류") == "지연캐시" for d in diag) else "재수집"
            if kind == "재수집":
                diag.append({"시리즈": t, "종류": "재수집", "사유": f"배치 퇴화({degenerate[t]}) → 개별 재수집 정상",
                             "행수": int(len(out[t])), "시작": str(out[t].index.min().date()),
                             "종료": str(out[t].index.max().date())})

    n_ok = sum(1 for v in out.values() if v is not None)
    log("DATA", kv(event="yahoo_batch_done", requested=len(tickers), ok=n_ok,
                   failed=len(tickers) - n_ok, degenerate=len(degenerate),
                   elapsed_s=round(time.time() - t0, 1)))
    return out


def fetch_all_fred(series_ids: List[str], cfg: Config = CFG,
                   diag: Optional[List[dict]] = None) -> Dict[str, Optional[pd.Series]]:
    """FRED 시리즈 병렬 다운로드. fetch_all_yahoo와 동일한 이유.
    [v1.3.0 §2] diag 리스트가 주어지면(validate_series의 quality_rows와 동일한 by-reference
    누적 패턴) 각 시리즈의 fetch_fred() 호출에 그대로 전달해, 제외된 시리즈의 사유·시도한 경로를
    모은다 — CPython의 GIL 하에서 list.append는 원자적이므로 스레드풀에서 여러 fetch_fred가
    동시에 같은 리스트에 append해도 데이터 경합이 없다.
    [v1.4.0 §1(C)] 이 배치 시작 시 CSV 회로차단기를 리셋한다 — 회로는 "이번 배치 안에서"
    CSV 경로가 막혀 있는지를 보는 것이라, 배치가 바뀌면(예: 다음 날 재실행) 새로 판단해야
    한다.
    [v1.15.1 §A(2)] 1차 배치 수집률이 cfg.FRED_MIN_COLLECT_RATIO 미만이면(report16: 0/54)
    FRED_BATCH_RETRY_WAIT_S 대기 → 회로차단기 리셋 → '전송 실패' 시리즈만 1회 재배치한다.
    무결성 실패(서버 구조 문제)·네거티브 캐시 히트는 재시도해도 결과가 같으므로 제외한다.
    diag는 재시도 시리즈의 1차 항목을 2차 항목으로 교체해(in-place) 중복 행을 남기지 않는다."""
    import concurrent.futures as cf
    t0 = time.time()
    _csv_circuit_reset(cfg)
    out: Dict[str, Optional[pd.Series]] = {}

    def _run_batch(ids: List[str], dg: Optional[List[dict]]) -> Dict[str, Optional[pd.Series]]:
        res: Dict[str, Optional[pd.Series]] = {}
        with cf.ThreadPoolExecutor(max_workers=cfg.FETCH_MAX_WORKERS) as ex:
            futs = {ex.submit(fetch_fred, sid, cfg, None, False, dg): sid for sid in ids}
            for fut in cf.as_completed(futs):
                sid = futs[fut]
                try:
                    res[sid] = fut.result()
                except Exception as e:
                    log("DATA", kv(event="fred_thread_error", series=sid, err=type(e).__name__), "error")
                    res[sid] = None
                    if dg is not None:
                        dg.append({"시리즈": sid, "사유": f"스레드예외({type(e).__name__})",
                                   "시도한경로": "-", "응답범위": "-", "종류": "제외"})
        return res

    out.update(_run_batch(list(series_ids), diag))
    n_ok = sum(1 for v in out.values() if v is not None)
    log("DATA", kv(event="fred_batch_done", requested=len(series_ids), ok=n_ok,
                   failed=len(series_ids) - n_ok, workers=cfg.FETCH_MAX_WORKERS,
                   elapsed_s=round(time.time() - t0, 1)))

    # [v1.15.1 §A(2)] 수집률 미달 시 전송 실패 시리즈 1회 재배치.
    n_req = len(series_ids)
    ratio = (n_ok / n_req) if n_req else 1.0
    if n_req and ratio < cfg.FRED_MIN_COLLECT_RATIO and cfg.FRED_BATCH_RETRY_WAIT_S >= 0:
        failed_ids = [sid for sid, v in out.items() if v is None]
        retry_ids = set(failed_ids)
        if diag is not None:
            for d in diag:
                sid = d.get("시리즈")
                if sid in retry_ids and not str(d.get("사유", "")).startswith("다운로드실패"):
                    retry_ids.discard(sid)   # 무결성 실패/네거티브 캐시 히트/스레드예외는 재시도 무의미
        retry_list = [sid for sid in failed_ids if sid in retry_ids]
        if retry_list:
            log("DATA", kv(event="fred_batch_retry", reason="수집률 하한 미달(전송 실패 다수)",
                           ok=n_ok, requested=n_req, ratio=round(ratio, 3),
                           floor=cfg.FRED_MIN_COLLECT_RATIO, retry_series=len(retry_list),
                           wait_s=cfg.FRED_BATCH_RETRY_WAIT_S), "warning")
            if cfg.FRED_BATCH_RETRY_WAIT_S > 0:
                time.sleep(cfg.FRED_BATCH_RETRY_WAIT_S)
            _csv_circuit_reset(cfg)
            retry_diag: Optional[List[dict]] = [] if diag is not None else None
            retry_out = _run_batch(retry_list, retry_diag)
            out.update(retry_out)
            if diag is not None:
                kept = [d for d in diag if d.get("시리즈") not in retry_ids]
                for d in (retry_diag or []):
                    if d.get("종류") == "제외":
                        d = {**d, "사유": f"{d['사유']} [배치 재시도 후에도 실패]"}
                    kept.append(d)
                diag[:] = kept   # by-reference 리스트를 in-place로 교체(호출자 참조 유지)
            n_ok_retry = sum(1 for sid in retry_list if retry_out.get(sid) is not None)
            n_ok = sum(1 for v in out.values() if v is not None)
            log("DATA", kv(event="fred_batch_retry_done", recovered=n_ok_retry,
                           retried=len(retry_list), ok=n_ok, requested=n_req,
                           ratio=round(n_ok / n_req, 3), elapsed_s=round(time.time() - t0, 1)),
                "info" if n_ok_retry else "warning")

    if n_ok < len(series_ids):
        failed = [sid for sid, v in out.items() if v is None]
        log("DATA", kv(event="fred_batch_failures", series=",".join(failed[:20]),
                       more=max(0, len(failed) - 20)), "warning")
    return out


def apply_publication_lag(s: pd.Series, lag_days: int, calendar: pd.DatetimeIndex) -> pd.Series:
    """
    [룩어헤드 차단 핵심]
    참조일 d의 값은 d+lag_days 이후에야 시장이 알 수 있다.
    -> 인덱스를 lag만큼 미래로 밀고, 거래일 캘린더에 forward-fill.
    """
    if s is None or len(s) == 0:
        return pd.Series(index=calendar, dtype=float)
    shifted = s.copy()
    shifted.index = shifted.index + pd.Timedelta(days=int(lag_days))
    shifted = shifted[~shifted.index.duplicated(keep="last")].sort_index()
    out = shifted.reindex(calendar.union(shifted.index)).ffill().reindex(calendar)
    return out


def validate_series(name: str, s: pd.Series, quality_rows: List[dict]) -> pd.Series:
    """입력 데이터 무결성 점검: 결측/중복/비정상값/기간 공백 로깅."""
    n = len(s)
    n_na = int(s.isna().sum())
    n_dup = int(s.index.duplicated().sum())
    n_inf = int(np.isinf(s.replace([np.inf, -np.inf], np.nan).fillna(0)).sum()) if n else 0
    gap_max = 0
    idx_ok = s.dropna().index
    if len(idx_ok) > 2:
        gap_max = int(pd.Series(idx_ok).diff().dt.days.max())
    quality_rows.append({
        "시리즈": name, "행수": n, "결측": n_na,
        "결측비율(%)": round(100.0 * n_na / n, 2) if n else np.nan,
        "중복인덱스": n_dup, "무한값": n_inf, "최대공백(일)": gap_max,
        "시작": str(idx_ok[0].date()) if len(idx_ok) else "-",
        "종료": str(idx_ok[-1].date()) if len(idx_ok) else "-",
    })
    if n_dup:
        log("DATA", kv(event="anomaly_duplicate_index", series=name, count=n_dup), "warning")
    if gap_max > 20:
        log("DATA", kv(event="anomaly_long_gap", series=name, gap_days=gap_max), "warning")
    return s


def _yahoo_critical_gate(px_dict: Dict[str, Optional[pd.DataFrame]], cfg: Config,
                         yahoo_diag: List[dict], quality: List[dict]) -> bool:
    """[v1.21.0 §A(3)] 신호핵심 Yahoo 티커(매매대상 + 급락트리거 입력) 게이트. 하나라도 없으면
    RuntimeError(ALLOW_DEGRADED_RUN=True면 True 반환 = 성능저하 실행). SELF_TEST는 대상 아님."""
    yahoo_degraded = False
    if not cfg.SELF_TEST:
        _missing = [t for t in cfg.SIGNAL_CRITICAL_TICKERS if px_dict.get(t) is None]
        if _missing:
            _why = "; ".join(f"{d['시리즈']}: {d['사유']}" for d in yahoo_diag if d.get("시리즈") in _missing) or \
                   "; ".join(str(q.get("무결성판정")) for q in quality
                             if any(str(q.get("시리즈", "")).endswith(f" {t}") for t in _missing) and "제외" in str(q.get("무결성판정")))
            _msg = (f"[중단/데이터수집] 신호핵심 Yahoo 티커 {', '.join(_missing)} 를 정상 이력으로 확보하지 못했습니다"
                    f"({_why or '사유 미상'}). ^VIX3M 없이는 급락트리거(규칙 ⓪)의 VIX 기간구조가 전 구간 결측이 되어 "
                    f"급락 방어가 통째로 빠진 리포트가 나옵니다(report22 사례: 2020 +27.6→+15.8%, MDD -8.4→-14.6%). "
                    f"다음 단계: (1) 몇 분 뒤 재실행(Yahoo 배치가 일부 심볼을 당일 1행만 주는 간헐 장애 — 단일 재수집·"
                    f"지연캐시까지 실패한 상태) (2) Colab이면 런타임 재시작 후 재실행 (3) 정말 저하 상태로도 실행해야 하면 "
                    f"Config.ALLOW_DEGRADED_RUN=True로 명시(00시트에 '성능저하 실행' 표기).")
            if not cfg.ALLOW_DEGRADED_RUN:
                log("DATA", kv(event="yahoo_critical_abort", missing=",".join(_missing)), "error")
                raise RuntimeError(_msg)
            yahoo_degraded = True
            log("DATA", kv(event="yahoo_critical_degraded", missing=",".join(_missing),
                           note="ALLOW_DEGRADED_RUN=True — 경고 후 진행(00시트 성능저하 표기)"), "warning")
        else:
            log("DATA", kv(event="yahoo_critical_ok", tickers=",".join(cfg.SIGNAL_CRITICAL_TICKERS),
                           stale_used=sum(1 for d in yahoo_diag if d.get("종류") == "지연캐시"),
                           refetched=sum(1 for d in yahoo_diag if d.get("종류") == "재수집")))
    return yahoo_degraded


def validate_price_data(px_dict: Dict[str, Optional[pd.DataFrame]], cfg: Config,
                        quality_rows: List[dict]) -> Dict[str, Optional[pd.DataFrame]]:
    """
    [v1.2.0] 가격 데이터 무결성 게이트. 실사용 리포트에서 "SPY" 가격이 실제로는 RSP(동일가중 ETF,
    2003년 상장) 가격이었던 사고(v1.1.x의 yfinance 병렬 다운로드가 원인)가 발견되어 신설했다.
    세 가지를 확인한다:
      (1) 시작일 검증: 실제 데이터 시작이 YAHOO_EXPECTED_START보다 PRICE_START_TOLERANCE_DAYS
          이상 늦으면 해당 티커를 제외 (예: "SPY"가 2003년부터만 있으면 다른 티커와 뒤섞인 것).
      (2) 교차오염 검증: 서로 다른 티커인데 종가 시계열이 (반올림 후) 사실상 동일하면 스레드
          경합으로 데이터가 뒤섞였다는 뜻 -> 두 티커 모두 제외.
      (3) SPY 하드 요건: 매매대상 가격이 틀리면 전체 백테스트가 무의미하므로, SPY만은 통과하지
          못하면 파이프라인을 중단한다(다른 티커처럼 조용히 제외하고 넘어가지 않음).
    """
    def close_of(d: Optional[pd.DataFrame]) -> Optional[pd.Series]:
        if d is None or len(d) == 0:
            return None
        col = "Adj Close" if "Adj Close" in d.columns else "Close"
        return d[col].dropna()

    # (1) 시작일 검증
    excluded: List[str] = []
    for t, d in list(px_dict.items()):
        exp = YAHOO_EXPECTED_START.get(t)
        c = close_of(d)
        if exp is None or c is None or len(c) == 0:
            continue
        actual_start = c.index.min()
        expected_start = pd.Timestamp(exp)
        late_by = (actual_start - expected_start).days
        ok = late_by <= cfg.PRICE_START_TOLERANCE_DAYS
        quality_rows.append({
            "시리즈": f"[무결성체크] {t}", "행수": len(c), "결측": 0, "결측비율(%)": 0.0,
            "중복인덱스": 0, "무한값": 0, "최대공백(일)": 0,
            "시작": str(actual_start.date()), "종료": str(c.index.max().date()),
            "무결성판정": "OK" if ok else f"제외: 실제시작 {actual_start.date()} vs 예상 "
                                          f"{expected_start.date()} ({late_by}일 늦음)",
        })
        if not ok:
            log("DATA", kv(event="data_integrity_fail_start", series=t,
                           actual_start=str(actual_start.date()), expected_start=exp,
                           late_by_days=late_by), "error")
            px_dict[t] = None
            excluded.append(t)

    # (2) 교차오염 검증 (반올림된 종가 시계열의 해시 비교 — 서로 다른 티커가 동일 데이터를
    #     들고 있으면 스레드 경합으로 뒤섞였다는 뜻)
    closes: Dict[str, pd.Series] = {}
    for t, d in px_dict.items():
        c = close_of(d)
        if c is not None and len(c) > 50:
            closes[t] = c.round(6)
    tickers = [t for t in closes if t not in excluded]
    for i in range(len(tickers)):
        for j in range(i + 1, len(tickers)):
            t1, t2 = tickers[i], tickers[j]
            c1, c2 = closes[t1], closes[t2]
            common = c1.index.intersection(c2.index)
            if len(common) < 100:
                continue
            n_match = int((c1.loc[common].values == c2.loc[common].values).sum())
            match_ratio = n_match / len(common)
            if match_ratio > 0.99:
                log("DATA", kv(event="data_integrity_cross_contamination", series_a=t1, series_b=t2,
                               match_ratio=round(match_ratio, 4), overlap_days=len(common)), "error")
                px_dict[t1] = None
                px_dict[t2] = None
                excluded.extend([t1, t2])

    # (3) SPY 하드 요건 — 매매대상이 틀리면 그 무엇도 의미가 없으므로 즉시 중단
    trade_c = close_of(px_dict.get(cfg.TRADE_TICKER))
    if cfg.TRADE_TICKER in YAHOO_EXPECTED_START:
        if trade_c is None or len(trade_c) == 0:
            raise RuntimeError(f"[치명적/데이터무결성] 매매대상 {cfg.TRADE_TICKER} 가격 데이터가 "
                               f"없거나 무결성 검증에서 제외되었습니다. 캐시 삭제 후 재실행하거나 "
                               f"네트워크를 확인하세요.")
        last_px = float(trade_c.iloc[-1])
        max_ret = float(trade_c.pct_change().abs().max())
        if not (10.0 <= last_px <= 10000.0):
            raise RuntimeError(f"[치명적/데이터무결성] {cfg.TRADE_TICKER} 마지막 종가({last_px:.2f})가 "
                               f"비정상 범위입니다. 다른 티커 데이터가 섞였을 가능성이 높습니다. "
                               f"캐시 삭제 후 재실행하세요.")
        if max_ret > 0.25:
            bad_date = trade_c.pct_change().abs().idxmax()
            raise RuntimeError(f"[치명적/데이터무결성] {cfg.TRADE_TICKER}에 {bad_date.date()} "
                               f"±{max_ret:.1%} 이상치가 있습니다. 캐시 삭제 후 재실행하세요.")
        log("DATA", kv(event="spy_hard_check_passed", start=str(trade_c.index.min().date()),
                       last_px=round(last_px, 2), max_abs_daily_ret=round(max_ret, 4)))

    if excluded:
        log("DATA", kv(event="price_integrity_summary", excluded=",".join(sorted(set(excluded))),
                       n_excluded=len(set(excluded))), "warning")
    return px_dict


# =============================================================================
# [3] 지표 레이어
#     각 후보 지표는 (경제적 근거, 사전 방향, 계산식)을 함께 정의한다.
#     * prior_sign = +1 : 값이 클수록 향후 주가 상승에 유리 (위험선호)
#     * prior_sign = -1 : 값이 클수록 향후 주가 하락에 유리 (위험회피)
#     사전 방향은 '경제 논리'이고, 실제 채택 방향은 [4]검증 레이어의 실증 결과로 정한다.
#     둘이 어긋나면 경고를 남긴다(과최적화/우연 신호 가능성).
# =============================================================================
@dataclass
class IndicatorSpec:
    key: str
    name_kr: str
    category: str
    prior_sign: int
    rationale: str          # 왜 이 지표가 시장을 '선행'한다고 보는가
    source: str             # 사용 데이터
    lead_mechanism: str     # 선행 메커니즘 한 줄 요약
    # ---- 자동생성 지표용 (v1.1.0). 아래 20개 커스텀 지표는 전부 기본값(auto=False)으로 남는다 ----
    auto: bool = False           # True면 build_indicators()가 series_id/kind/transform으로 일반 계산
    series_id: str = ""          # FRED series id 또는 Yahoo 티커
    series_kind: str = ""        # "fred_rate" | "fred_index" | "yahoo_price"
    transform: str = ""          # "level_z" | "chg" | "mom"
    window: int = 0              # chg/mom 관측일수, level_z의 롤링윈도우
    # ---- 검증 지평 (v1.2.0) -------------------------------------------------
    # 지표마다 '진짜 신호가 나타나는 시차'가 다르다. 21일(월간) 단일 지평만 쓰면 느린 지표
    # (120일 변화율, 200일선 이격도 등)는 21일 시점에 단기 평균회귀로 부호가 뒤집혀 억울하게
    # 탈락한다(실사용 리포트에서 TREND_200/MOM_12_1/DD_FROM_252H 등이 이렇게 탈락했음).
    # None이면 cfg.VAL_PRIMARY_H(기본 21일)를 그대로 쓴다.
    eval_horizon: Optional[int] = None
    # ---- 국면필터 트랙 (v1.2.0) ----------------------------------------------
    # True인 지표는 IC/NW-t 게이트를 적용하지 않고 하락판별 AUC + 시대별 부호안정성만으로
    # PASS/FAIL을 판정한다(추세지표는 원래 '몇 주 후 수익률 예측'이 아니라 '지금 국면이 위험한가'를
    # 보는 필터라서 21/63일 예측회귀와 목적이 다르다). 복합점수에는 포함하되 가중치 합산 상한
    # (Config.TREND_TRACK_WEIGHT_CAP)을 적용한다.
    trend_track: bool = False
    # ---- 기저 시리즈 (v1.3.0 §6) ----------------------------------------------
    # 같은 원천 데이터에서 파생된 여러 지표(예: DXYNYB_MOM60/MOM120은 둘 다 "DX-Y.NYB")가
    # 복합점수 가중치를 독식하는 것을 막기 위한 그룹 키. 자동생성 지표(auto=True)는
    # series_id가 이미 기저 시리즈이므로 명시할 필요 없다(_select_and_weight_period에서
    # 자동으로 series_id를 사용). 수기 큐레이션 지표(auto=False) 중 명확히 다른 지표와
    # 원천을 공유하는 경우에만 여기 명시한다 — 빈 문자열("")이면 캡 대상에서 제외된다
    # (원천이 불분명한 지표를 임의로 묶어 캡을 적용하는 것을 방지, 하위호환 기본값).
    base_series: str = ""

