def _sanitize_key(raw: str) -> str:
    return raw.replace("^", "").replace("=F", "").replace("-", "").replace(".", "").replace("/", "")


def _generate_universe_indicators(cfg: Config = CFG) -> List[IndicatorSpec]:
    """
    [v1.1.0] "미국 주식시장 전체에 영향 줄만한 지표는 모두" 요청에 대응하는 자동생성 레이어.
    위 20개는 손으로 쓴 커스텀 계산(build_indicators()의 A~E 블록)이고, 여기서는
    MACRO_SERIES(FRED ~52종) + CROSS_ASSET_SERIES(Yahoo 크로스에셋 ~12종)를 대상으로
    (수준 z-score, {5,20,60,120}일 변화/모멘텀)을 규칙적으로 생성한다.
    개별 지표를 손으로 500개 쓰는 대신, "시리즈의 경제적 의미(왜 이 시리즈인가)"는 MacroSeries/
    CrossAssetSeries에, "변화율 관측이 왜 선행성을 갖는가"는 아래 템플릿에 각각 근거를 남겨
    03_지표검증/04_채택근거상세 시트에서 지표별로 여전히 사람이 읽을 수 있는 근거가 나오게 한다.
    일부(예: BAMLH0A0HYM2의 20일 변화)는 위 커스텀 지표(HY_OAS_CHG20)와 개념이 겹치지만,
    서로 다른 코드 경로로 독립 계산되므로 교차검증 용도로도 유효해 굳이 제외하지 않았다.
    """
    # [v1.2.0] 지표별 평가지평: 관측창이 60/120일처럼 느린 변화/모멘텀은 21일 예측회귀에서
    # 단기 평균회귀로 부호가 뒤집히기 쉬워 63일을 쓴다. 수준(z-score)과 5/20일 관측창은
    # 반응이 빠르므로 기본 21일을 유지한다.
    def _eval_h(transform: str, window: int) -> Optional[int]:
        if transform == "level_z":
            return None   # cfg.VAL_PRIMARY_H(21일) 그대로
        return 63 if window >= 60 else None

    specs: List[IndicatorSpec] = []
    for m in MACRO_SERIES:
        kind = "fred_index" if m.kind == "index" else "fred_rate"
        if m.prior_level != 0:
            specs.append(IndicatorSpec(
                key=f"{m.sid}_Z", name_kr=f"{m.name_kr}(수준 z)", category=f"F.매크로확장-{m.category}",
                prior_sign=m.prior_level, rationale=m.rationale, source=f"FRED {m.sid}",
                lead_mechanism=m.mechanism, auto=True, series_id=m.sid,
                series_kind=kind, transform="level_z", window=504,
                eval_horizon=_eval_h("level_z", 504)))
        if m.prior_chg != 0:
            for w in cfg.TRANSFORM_HORIZONS:
                unit = "변화율" if kind == "fred_index" else "변화"
                specs.append(IndicatorSpec(
                    key=f"{m.sid}_CHG{w}", name_kr=f"{m.name_kr}({w}일 {unit})",
                    category=f"F.매크로확장-{m.category}",
                    prior_sign=m.prior_chg, rationale=m.rationale, source=f"FRED {m.sid}",
                    lead_mechanism=m.mechanism, auto=True, series_id=m.sid,
                    series_kind=kind, transform="chg", window=w,
                    eval_horizon=_eval_h("chg", w)))
    for c in CROSS_ASSET_SERIES:
        if c.prior_mom == 0:
            continue
        base_key = _sanitize_key(c.ticker)
        for w in cfg.TRANSFORM_HORIZONS:
            specs.append(IndicatorSpec(
                key=f"{base_key}_MOM{w}", name_kr=f"{c.name_kr}({w}일 모멘텀)",
                category=f"G.크로스에셋확장-{c.category}",
                prior_sign=c.prior_mom, rationale=c.rationale, source=f"Yahoo {c.ticker}",
                lead_mechanism=c.mechanism, auto=True, series_id=c.ticker,
                series_kind="yahoo_price", transform="mom", window=w,
                eval_horizon=_eval_h("mom", w)))
    return specs


INDICATOR_SPECS.extend(_generate_universe_indicators(CFG))

SPEC_BY_KEY = {s.key: s for s in INDICATOR_SPECS}


def _z(s: pd.Series, win: int) -> pd.Series:
    """롤링 z-score (지표 내부 정규화용). 룩어헤드 없음: 과거 win일만 사용."""
    m = s.rolling(win, min_periods=max(20, win // 4)).mean()
    v = s.rolling(win, min_periods=max(20, win // 4)).std()
    return (s - m) / v.replace(0, np.nan)


def _mom(s: pd.Series, n: int) -> pd.Series:
    return s / s.shift(n) - 1.0


def build_indicators(px: Dict[str, pd.DataFrame], fred: Dict[str, pd.Series],
                     cal: pd.DatetimeIndex, verbose: bool = True) -> pd.DataFrame:
    """
    후보 지표 전량 계산 (벡터화). 원천 데이터가 없으면 해당 지표는 NaN 열로 생성되어
    검증 단계에서 커버리지 미달로 자동 탈락한다.
    """
    t0 = time.time()
    out = pd.DataFrame(index=cal)

    def close(t: str) -> Optional[pd.Series]:
        d = px.get(t)
        if d is None or "Close" not in d:
            return None
        return d["Close"].reindex(cal).ffill()

    def adj(t: str) -> Optional[pd.Series]:
        d = px.get(t)
        if d is None:
            return None
        col = "Adj Close" if "Adj Close" in d.columns else "Close"
        return d[col].reindex(cal).ffill()

    spy_c = close("SPY")
    spy_a = adj("SPY")

    # --- A. 변동성 ---
    vix, vix3m = close("^VIX"), close("^VIX3M")
    if vix is not None and vix3m is not None:
        out["VIX_TERM"] = (vix3m / vix.replace(0, np.nan))
    if vix is not None:
        out["VIX_CHG20"] = vix / vix.shift(20) - 1.0
        out["VIX_LEVEL"] = _z(np.log(vix.replace(0, np.nan)), 504)
    if spy_a is not None:
        r = np.log(spy_a).diff()
        rv20 = r.rolling(20).std()
        rv100 = r.rolling(100).std()
        out["RVOL_RATIO"] = rv20 / rv100.replace(0, np.nan)

    # --- B. 신용 ---
    hy = fred.get("BAMLH0A0HYM2")
    if hy is not None:
        out["HY_OAS_CHG20"] = hy - hy.shift(20)
        out["HY_OAS_LEVEL"] = _z(hy, 504)
    ig = fred.get("BAMLC0A0CM")
    if ig is not None:
        out["IG_OAS_CHG20"] = ig - ig.shift(20)
    hyg, ief = adj("HYG"), adj("IEF")
    if hyg is not None and ief is not None:
        out["HYG_IEF_MOM"] = _mom(hyg / ief.replace(0, np.nan), 60)

    # --- C. 매크로 ---
    if fred.get("T10Y3M") is not None:
        out["YC_10Y3M"] = fred["T10Y3M"]
    if fred.get("T10Y2Y") is not None:
        out["YC_STEEP_120"] = fred["T10Y2Y"] - fred["T10Y2Y"].shift(120)
    ic = fred.get("ICSA")
    if ic is not None:
        ic4 = ic.rolling(20, min_periods=5).mean()          # 캘린더 ffill 상태의 4주평균
        out["CLAIMS_MOM"] = ic4 / ic4.shift(130) - 1.0      # 약 26주 변화
    if fred.get("NFCI") is not None:
        out["NFCI"] = fred["NFCI"]
    if fred.get("DFII10") is not None:
        out["REAL_RATE_CHG"] = fred["DFII10"] - fred["DFII10"].shift(60)

    # --- D. 크로스에셋 ---
    cu, au = close("HG=F"), close("GC=F")
    if cu is not None and au is not None:
        out["COPPER_GOLD_MOM"] = _mom(cu / au.replace(0, np.nan), 60)
    # [v1.1.0] 섹터 지표(XLY/XLP, SMH) 제외 — 추후 섹터 레이어로 별도 추가 예정.
    #   재추가 시: CURATED_YAHOO 에 "XLY","XLP","SMH" 를 넣고 아래 두 블록을 복원.
    dxy = close("DX-Y.NYB")
    if dxy is not None:
        out["DXY_MOM"] = _mom(dxy, 60)

    # --- E. 추세 / 내부 ---
    if spy_a is not None:
        ma200 = spy_a.rolling(200, min_periods=150).mean()
        out["TREND_200"] = spy_a / ma200.replace(0, np.nan) - 1.0
        out["MOM_12_1"] = spy_a.shift(21) / spy_a.shift(252) - 1.0
        out["DD_FROM_252H"] = spy_a / spy_a.rolling(252, min_periods=120).max() - 1.0
        r63 = spy_a / spy_a.shift(63) - 1.0
        vol63 = np.log(spy_a).diff().rolling(63).std() * np.sqrt(252)
        out["VOL_ADJ_MOM"] = r63 / vol63.replace(0, np.nan)
        # [v1.12.0 §B] 기술적 지표 후보 3종 — 전부 과거 창만 쓰는 인과 계산(ewm/rolling은
        # backward-looking, shift/미래참조 없음). 검증게이트 통과 시에만 채택된다.
        _delta = spy_a.diff()
        _gain = _delta.clip(lower=0).ewm(alpha=1 / 14, adjust=False).mean()
        _loss = (-_delta.clip(upper=0)).ewm(alpha=1 / 14, adjust=False).mean()
        _rs = _gain / _loss.replace(0, np.nan)
        out["RSI_14"] = 100.0 - 100.0 / (1.0 + _rs)
        _ema12 = spy_a.ewm(span=12, adjust=False).mean()
        _ema26 = spy_a.ewm(span=26, adjust=False).mean()
        _macd = _ema12 - _ema26
        _sig9 = _macd.ewm(span=9, adjust=False).mean()
        out["MACD_HIST"] = (_macd - _sig9) / spy_a.replace(0, np.nan)
        _ma50 = spy_a.rolling(50, min_periods=40).mean()
        out["MA_50_200_SPREAD"] = _ma50 / ma200.replace(0, np.nan) - 1.0
    rsp = adj("RSP")
    if rsp is not None and spy_a is not None:
        out["RSP_SPY_MOM"] = _mom(rsp / spy_a.replace(0, np.nan), 60)

    # --- F/G. 자동생성 지표 (v1.1.0) ---------------------------------------
    # MACRO_SERIES/CROSS_ASSET_SERIES 로부터 생성된 auto=True 스펙을 규칙 기반으로 일괄 계산.
    # source series 원본은 fred[series_id] (FRED) 또는 px[series_id]의 종가/수정종가 (Yahoo).
    auto_ok, auto_missing = 0, 0
    for spec in INDICATOR_SPECS:
        if not spec.auto:
            continue
        if spec.series_kind == "yahoo_price":
            src = adj(spec.series_id)
            if src is None:
                src = close(spec.series_id)
        else:
            src = fred.get(spec.series_id)
        if src is None:
            auto_missing += 1
            continue
        try:
            if spec.transform == "level_z":
                col = _z(src, spec.window or 504)
            elif spec.transform == "chg":
                if spec.series_kind == "fred_index":
                    col = src / src.shift(spec.window) - 1.0
                else:
                    col = src - src.shift(spec.window)
            elif spec.transform == "mom":
                col = _mom(src, spec.window)
            else:
                auto_missing += 1
                continue
        except Exception as e:
            if verbose:
                log("INDICATOR", kv(event="auto_calc_error", indicator=spec.key,
                                    error=str(e)[:120]), "warning")
            auto_missing += 1
            continue
        out[spec.key] = col
        auto_ok += 1
    if verbose:
        log("INDICATOR", kv(event="auto_universe_built", ok=auto_ok, missing=auto_missing))

    # 정의된 스펙과 열 정렬 (없는 지표는 NaN 열로 채워 이후 단계가 일관되게 동작)
    for spec in INDICATOR_SPECS:
        if spec.key not in out.columns:
            out[spec.key] = np.nan
            if verbose:
                log("INDICATOR", kv(event="missing_source", indicator=spec.key,
                                    source=spec.source), "warning")
    out = out[[s.key for s in INDICATOR_SPECS]]
    out = out.replace([np.inf, -np.inf], np.nan)

    if verbose:
        n_ok = int((out.notna().sum() > 0).sum())
        log("INDICATOR", kv(event="built", candidates=len(INDICATOR_SPECS), with_data=n_ok,
                            rows=len(out), elapsed_s=round(time.time() - t0, 2)))
        for spec in INDICATOR_SPECS:
            cov = float(out[spec.key].notna().mean())
            log("INDICATOR", kv(indicator=spec.key, category=spec.category,
                                prior_sign=spec.prior_sign, coverage=cov), "debug")
    return out


# =============================================================================
# [4] 검증 레이어  ── "왜 이 지표를 쓰는가"에 대한 정량 근거 생성
#     지표 하나당 다음 6가지를 모두 계산하고, 전부 통과해야 실제 매매에 사용한다.
#       (1) Spearman IC          : 지표값과 향후 h일 수익률의 순위상관 (선행성)
#       (2) Newey-West t         : 중첩 표본 자기상관을 보정한 통계적 유의성
#       (3) 5분위 스프레드/단조성 : 관계가 선형·단조인지 (우연한 극단값 효과 배제)
#       (4) 하락판별 AUC          : '향후 h일 내 -5% 이상 하락' 이벤트를 실제로 구분하는가
#       (5) 4구간 부호 안정성     : 시대가 바뀌어도 같은 방향인가 (과최적화 배제)
#       (6) 커버리지              : 백테스트 구간에서 데이터가 충분한가
#
#     [v1.2.0] 시간감쇠 가중(time-decay weighting): 사용자 요구("오래된 데이터는 '그런
#     케이스가 있었다' 수준으로만, 최신 데이터에 비중")를 반영해 (1)(2)(4)(5)를 전부
#     지수감쇠 표본가중 버전으로 계산할 수 있도록 weights 파라미터를 추가한다.
#     weights=None이면 균등가중 — 기존 함수와 100% 동일한 코드경로/결과(하위호환 보장,
#     단위테스트로 검증됨). cfg.HALF_LIFE_DAYS가 None이면 감쇠를 아예 쓰지 않는다.
# =============================================================================
def decay_weights(idx: pd.DatetimeIndex, asof: pd.Timestamp,
                  half_life_days: Optional[int]) -> Optional[pd.Series]:
    """
    [v1.2.0 신규] 지수감쇠 표본가중치: w_i = 0.5 ** (age_days_i / half_life_days),
    age_days_i = (asof - date_i).days >= 0.
    [룩어헤드 차단 필수사항] asof는 반드시 '그 재추정 시점'(예: train_end)이어야 하며,
    데이터셋의 최종일자나 실행시점의 '오늘'을 쓰면 안 된다 — 최종일자를 쓰면 과거 시점의
    재검증에서조차 '얼마나 최근인지'가 미래 시점 기준으로 계산되어 새로운 룩어헤드가
    생긴다. 호출부(build_walkforward_weights)는 매 재추정 루프마다 이 함수를 다시 호출한다.
    half_life_days가 None이면 감쇠를 쓰지 않는다는 뜻이므로 None을 반환한다(호출부는
    이를 weights=None으로 해석 -> 기존 균등가중 동작 그대로).
    """
    if half_life_days is None or half_life_days <= 0:
        return None
    age_days = (asof - idx).days.values.astype(float)
    age_days = np.clip(age_days, 0.0, None)  # asof 이후 날짜(있어서는 안 됨)는 0으로 방어
    w = np.power(0.5, age_days / float(half_life_days))
    return pd.Series(w, index=idx)


def effective_n(weights: Optional[pd.Series]) -> float:
    """유효표본수 N_eff = (Σw)^2 / Σw^2. weights=None이면 실제 표본수를 그대로 의미하므로
    호출부에서 별도 처리한다(이 함수는 None을 받으면 nan 반환)."""
    if weights is None:
        return np.nan
    w = weights.dropna().values.astype(float)
    sw = w.sum()
    sw2 = (w ** 2).sum()
    if sw2 <= 0:
        return 0.0
    return float((sw ** 2) / sw2)


def spearman_ic(x: pd.Series, y: pd.Series,
                weights: Optional[pd.Series] = None) -> Tuple[float, int]:
    """
    순위상관(Spearman). 결측 제거 후 공통 표본만 사용.
    [v1.2.0] weights가 주어지면 순위값에 대한 가중 피어슨 상관(np.cov aweights)을 계산한다
    (=가중 Spearman). weights=None이면 기존과 완전히 동일한 코드/결과.
    """
    df = pd.concat([x, y], axis=1).dropna()
    if len(df) < 100:
        return np.nan, len(df)
    rx = df.iloc[:, 0].rank()
    ry = df.iloc[:, 1].rank()
    if weights is None:
        rx = rx - rx.mean()
        ry = ry - ry.mean()
        denom = np.sqrt((rx ** 2).sum() * (ry ** 2).sum())
        if denom == 0:
            return np.nan, len(df)
        return float((rx * ry).sum() / denom), len(df)
    w = weights.reindex(df.index).astype(float).fillna(0.0).values
    if w.sum() <= 0:
        return np.nan, len(df)
    cov = np.cov(np.vstack([rx.values, ry.values]), aweights=w)
    denom = math.sqrt(cov[0, 0] * cov[1, 1])
    if denom == 0 or not np.isfinite(denom):
        return np.nan, len(df)
    return float(cov[0, 1] / denom), len(df)


def newey_west_tstat(x: pd.Series, y: pd.Series, lags: int,
                     weights: Optional[pd.Series] = None) -> Tuple[float, float]:
    """
    중첩(overlapping) 예측회귀 y = a + b*x + e 의 b에 대한 Newey-West(HAC) t값.
    h일 선행수익률은 h-1일 중첩되어 자기상관을 가지므로 OLS t값은 크게 부풀려진다.
    -> lags = h 로 HAC 보정. (외부 패키지 의존 없이 직접 구현)

    [v1.2.0] weights가 주어지면 WLS(가중최소제곱)로 전환한다. 대각가중행렬 W=diag(w)인
    WLS는 설명변수·종속변수에 sqrt(w)를 곱한 변환값의 OLS와 수학적으로 동일(표준 WLS-OLS
    등가변환)하므로, 변환 후 기존 HAC(Bartlett) 새드위치 추정을 그대로 재사용한다
    (코드 변경 최소화, 검증은 별도 단위테스트로 완료). weights=None이면 Xw=X(별칭, 복사조차
    없음)이라 기존 함수와 완전히 동일한 연산 경로 — 하위호환이 코드 구조로 보장된다.
    """
    df = pd.concat([x, y], axis=1).dropna()
    if len(df) < 100:
        return np.nan, np.nan
    xv = df.iloc[:, 0].values.astype(float)
    yv = df.iloc[:, 1].values.astype(float)
    xv = (xv - xv.mean()) / (xv.std() + 1e-12)      # 스케일 표준화(수치 안정)
    n = len(xv)
    X = np.column_stack([np.ones(n), xv])

    if weights is not None:
        w = weights.reindex(df.index).fillna(0.0).values.astype(float)
        w = np.clip(w, 0.0, None)
        if w.sum() <= 0:
            return np.nan, np.nan
        sw = np.sqrt(w)
        Xw = X * sw[:, None]
        yw = yv * sw
    else:
        Xw = X
        yw = yv

    XtX_inv = np.linalg.pinv(Xw.T @ Xw)
    beta = XtX_inv @ (Xw.T @ yw)
    resid = yw - Xw @ beta
    # HAC (Bartlett kernel) — 가중변환된 X/resid에 그대로 적용(시간순서는 유지됨)
    S = (Xw * resid[:, None]).T @ (Xw * resid[:, None])
    for l in range(1, int(lags) + 1):
        wl = 1.0 - l / (lags + 1.0)
        u_t = (Xw[l:] * resid[l:, None])
        u_tl = (Xw[:-l] * resid[:-l, None])
        G = u_t.T @ u_tl
        S += wl * (G + G.T)
    cov = XtX_inv @ S @ XtX_inv
    se = math.sqrt(max(cov[1, 1], 1e-24))
    t = float(beta[1] / se)
    # 양측 p값 (정규근사)
    p = float(2.0 * (1.0 - 0.5 * (1.0 + math.erf(abs(t) / math.sqrt(2.0)))))
    return t, p


def quintile_profile(x: pd.Series, y: pd.Series, q: int = 5) -> Tuple[List[float], float, float]:
    """분위별 평균 향후수익률, 최상-최하 스프레드, 단조성(분위번호와 평균수익률의 순위상관)."""
    df = pd.concat([x, y], axis=1).dropna()
    df.columns = ["x", "y"]
    if len(df) < 200:
        return [np.nan] * q, np.nan, np.nan
    try:
        df["bin"] = pd.qcut(df["x"].rank(method="first"), q, labels=False)
    except Exception:
        return [np.nan] * q, np.nan, np.nan
    means = df.groupby("bin")["y"].mean()
    means = means.reindex(range(q))
    spread = float(means.iloc[-1] - means.iloc[0])
    valid = means.dropna()
    if len(valid) >= 3:
        rb = pd.Series(valid.index, dtype=float).rank()
        rm = valid.reset_index(drop=True).rank()
        mono = float(np.corrcoef(rb, rm)[0, 1])
    else:
        mono = np.nan
    return [float(v) if pd.notna(v) else np.nan for v in means], spread, mono


def auc_downside(x: pd.Series, label: pd.Series,
                 weights: Optional[pd.Series] = None) -> float:
    """
    Mann-Whitney U 기반 AUC. label=1(향후 큰 하락 발생) 을 지표가 얼마나 잘 구분하는가.
    AUC>0.5 : 지표값이 클수록 하락 위험 큼 / AUC<0.5 : 클수록 안전.

    [v1.2.0] weights가 주어지면 표본별 시간감쇠가중을 반영한 가중 AUC를 O(n log n)으로
    계산한다(동순위(tie) 구간 0.5 가중 보정 포함): 음성(label=0) 표본을 x값으로 그룹핑해
    누적가중치를 구한 뒤, 각 양성 표본에 대해 '더 작은 음성표본 가중치합 + 0.5*동순위
    음성표본 가중치합'을 누적한다. 브루트포스(O(n1*n0)) 및 균등가중 특수케이스가 기존
    비가중 공식과 정확히 일치함을 별도 단위테스트로 검증(오차 1e-9 이하)했다.
    weights=None이면 기존과 완전히 동일한 코드/결과.
    """
    df = pd.concat([x, label], axis=1).dropna()
    df.columns = ["x", "y"]
    if weights is None:
        n1 = int((df["y"] == 1).sum())
        n0 = int((df["y"] == 0).sum())
        if n1 < 30 or n0 < 30:
            return np.nan
        r = df["x"].rank()
        return float((r[df["y"] == 1].sum() - n1 * (n1 + 1) / 2.0) / (n1 * n0))

    n1 = int((df["y"] == 1).sum())
    n0 = int((df["y"] == 0).sum())
    if n1 < 30 or n0 < 30:
        return np.nan
    w = weights.reindex(df.index).fillna(0.0).astype(float)
    df = df.assign(w=w)
    w1_total = float(df.loc[df["y"] == 1, "w"].sum())
    w0_total = float(df.loc[df["y"] == 0, "w"].sum())
    if w1_total <= 0 or w0_total <= 0:
        return np.nan

    neg = df[df["y"] == 0]
    neg_by_x = neg.groupby("x")["w"].sum().sort_index()
    xs = neg_by_x.index.values
    neg_w = neg_by_x.values
    cum_upto = neg_w.cumsum()          # x<=xs[k]인 음성표본 누적가중치

    pos_x = df.loc[df["y"] == 1, "x"].values
    pos_w = df.loc[df["y"] == 1, "w"].values

    n_neg_levels = len(xs)
    idx_left = np.searchsorted(xs, pos_x, side="left")   # 첫 xs[k] >= v 인 위치
    idx_left_c = np.clip(idx_left, 0, max(n_neg_levels - 1, 0))

    less = np.where(idx_left > 0, cum_upto[np.clip(idx_left - 1, 0, max(n_neg_levels - 1, 0))], 0.0)
    is_eq = (idx_left < n_neg_levels) & (xs[idx_left_c] == pos_x)
    equal = np.where(is_eq, neg_w[idx_left_c], 0.0)

    contrib = pos_w * (less + 0.5 * equal)
    return float(contrib.sum() / (w1_total * w0_total))


def forward_return(px: pd.Series, h: int) -> pd.Series:
    """t 시점에서 본 향후 h거래일 수익률 (t+h / t - 1). 신호는 t의 정보만 사용."""
    return px.shift(-h) / px - 1.0


def forward_maxdd(px: pd.Series, h: int) -> pd.Series:
    """t 시점 이후 h거래일 동안의 최저점 낙폭 (하락 이벤트 라벨링용)."""
    fwd_min = px.shift(-1).rolling(h, min_periods=max(3, h // 3)).min().shift(-(h - 1))
    return fwd_min / px - 1.0


def _is_short_history_indicator(spec: "IndicatorSpec", cfg: Config = CFG) -> bool:
    """
    [v1.5.0 §A] 이 지표가 Config.FRED_ALLOW_SHORT_HISTORY 소속 "짧은이력" 기저 시리즈에서
    나온 것인지 판정한다 — validate_indicators()/_hazard_track_verdict()가 커버리지·
    부호일치구간수 게이트를 완화된 값(MIN_COVERAGE_SHORT_HISTORY/MIN_SUBPERIOD_AGREE_
    SHORT_HISTORY)으로 적용할지 결정하는 데 쓰인다.

    그룹키 판정은 SERIES_WEIGHT_CAP 로직(_select_and_weight_period/_select_and_weight_
    hazard_period)이 이미 쓰는 것과 동일한 패턴을 그대로 재사용한다: 수기 지표는
    spec.base_series(명시된 경우), 자동생성 파생지표(spec.auto=True)는 spec.series_id
    (원본 FRED 시리즈 id, 예: BAMLH0A0HYM2_CHG20 -> series_id="BAMLH0A0HYM2")를 그룹키로
    본다 — 이 패턴이 이미 검증된 것이라 새 버그를 만들 위험이 낮다. base_series가 비어있고
    auto=False인 수기 지표(그룹키 "")는 FRED_ALLOW_SHORT_HISTORY의 실제 FRED 시리즈 id와
    절대 일치하지 않으므로 False로 안전하게 처리된다.
    """
    group_key = spec.base_series or (spec.series_id if spec.auto else "")
    return bool(group_key) and group_key in cfg.FRED_ALLOW_SHORT_HISTORY


def _hazard_track_verdict(trend_track: bool, prior_sign: int, cov_w: float, auc: float,
                          block_aucs: List[float], cfg: Config = CFG,
                          min_coverage: Optional[float] = None,
                          min_subperiod_agree: Optional[int] = None,
                          ) -> Tuple[str, float, int, int, List[str]]:
    """
    [v1.3.0 §4] 위험(해저드) 트랙 PASS/FAIL 판정 — 순수 함수로 분리해 실제 가격경로 없이도
    (auc, block_aucs 값만으로) 단위테스트 가능하게 했다. validate_indicators()의 지표별 루프에서
    호출된다.

    핵심 아이디어: IC(수익 예측)와 AUC(하락사건 판별)는 다른 질문이다. VIX_LEVEL처럼 "공포가
    크면 오히려 이후 반등해 수익률 IC는 역방향이지만, 하락사건이 일어날 확률은 여전히 사전방향
    그대로 판별하는" 지표가 표준트랙에서 전부 탈락하던 문제(실사용 리포트에서 확인,
    IMPROVEMENT_PLAN_v1.3.md §4)의 해결책 — IC/NW-t는 전혀 보지 않고 AUC만 본다.

    prior_sign<0 (예: VIX, "높으면 위험") -> AUC>0.5가 사전방향과 일치하는 방향.
    prior_sign>0 (예: RSP/SPY 상대강도, "높으면 안전") -> AUC<0.5가 일치하는 방향.
    auc_edge_signed는 "방향 일치 시 양수, 불일치 시 음수"가 되도록 부호를 통일한 값이다.

    [v1.4.0 §3(a) ⚠ 신호(위험) 파라미터] 실사용 결과에서 해저드 트랙이 느린 매크로에 희석돼
    사실상 무력화된 것을 확인(IMPROVEMENT_PLAN_v1.4.md §3) — 표준트랙과 공유하던
    cfg.MIN_AUC_EDGE(0.03) 대신 해저드 전용의 더 엄격한 cfg.HAZARD_MIN_AUC_EDGE(기본 0.05)를
    쓴다. 커버리지·구간안정성 게이트는 변경하지 않는다(엣지 게이트만 분리 — 최소한의 변경으로
    문제를 해결). 나머지 TOP_K 압축은 이 함수가 아니라 _select_and_weight_hazard_period()에서
    수행한다(이 함수는 개별 지표 PASS/FAIL만 판정, TOP_K는 그 후 선택 단계).

    [v1.5.0 §A] min_coverage/min_subperiod_agree: 호출측(validate_indicators())이 짧은이력
    허용지표(Config.FRED_ALLOW_SHORT_HISTORY)에 한해 완화된 게이트값(MIN_COVERAGE_SHORT_HISTORY/
    MIN_SUBPERIOD_AGREE_SHORT_HISTORY)을 전달하기 위한 오버라이드. None이면(기존 호출부와
    100% 하위호환) cfg.MIN_COVERAGE/cfg.MIN_SUBPERIOD_AGREE 그대로 사용 — 단위테스트
    test_hazard_topk.py 등 기존 호출 시그니처는 값이 변하지 않는다.

    반환: (판정("PASS"/"FAIL"/"해당없음(추세트랙)"), auc_edge_signed, 구간일치수, 구간표본수, 사유리스트)
    """
    reasons: List[str] = []
    if trend_track:
        return "해당없음(추세트랙)", np.nan, 0, 0, reasons

    eff_min_coverage = cfg.MIN_COVERAGE if min_coverage is None else min_coverage
    eff_min_subperiod_agree = cfg.MIN_SUBPERIOD_AGREE if min_subperiod_agree is None else min_subperiod_agree

    if cov_w < eff_min_coverage:
        reasons.append(f"가중 커버리지 {cov_w:.0%} < {eff_min_coverage:.0%}")

    if prior_sign > 0:
        auc_edge_signed = (0.5 - auc) if pd.notna(auc) else np.nan
    elif prior_sign < 0:
        auc_edge_signed = (auc - 0.5) if pd.notna(auc) else np.nan
    else:
        auc_edge_signed = np.nan

    if pd.isna(auc_edge_signed):
        reasons.append("AUC 산출불가 또는 사전방향 미지정")
    elif auc_edge_signed < cfg.HAZARD_MIN_AUC_EDGE:
        reasons.append(f"방향일치 AUC엣지 {auc_edge_signed:.3f} < {cfg.HAZARD_MIN_AUC_EDGE}(해저드 전용, v1.4.0 §3)")

    agree_flags = []
    for ba in block_aucs:
        if pd.isna(ba):
            continue
        if prior_sign > 0:
            agree_flags.append(ba < 0.5)
        elif prior_sign < 0:
            agree_flags.append(ba > 0.5)
    signs_n = len(agree_flags)
    agree_n = int(sum(agree_flags))
    if agree_n < eff_min_subperiod_agree:
        reasons.append(f"AUC 방향안정성 {agree_n}/{signs_n} < {eff_min_subperiod_agree}")

    verdict = "PASS" if not reasons else "FAIL"
    return verdict, auc_edge_signed, agree_n, signs_n, reasons


def validate_indicators(ind: pd.DataFrame, px_adj: pd.Series, cfg: Config = CFG,
                        eval_start: Optional[pd.Timestamp] = None,
                        eval_end: Optional[pd.Timestamp] = None,
                        verbose: bool = True,
                        compute_quintiles: bool = True,
                        weights: Optional[pd.Series] = None,
                        full_report: bool = True,
                        fwd_full: Optional[Dict[int, pd.Series]] = None) -> pd.DataFrame:
    """
    전 후보 지표에 대해 검증표를 생성한다.
    eval_start/eval_end 를 주면 그 구간만 사용 -> walk-forward(과거 정보만) 재검증에 사용.
    compute_quintiles=False 이면 5분위 스프레드/단조성 계산을 건너뛴다(PASS/FAIL 판정에는
    영향 없음 — 참고용 리포트 필드일 뿐). 지표 수가 284개로 늘면서 walk-forward 재검증이
    연 26~28회 반복 호출되므로, 매 회 5분위 계산(정렬+분위 나누기)을 생략해 성능을 확보한다.
    최종 전체표본 리포트에서는 True로 호출해 정상적으로 채운다. [v1.1.0]

    [v1.2.0] weights(시간감쇠 가중, decay_weights()로 생성)를 주면 IC/NW-t/AUC/구간별IC를
    전부 가중 버전으로 계산한다(5분위·단조성은 참고용 필드라 plan §4.3 범위 밖 — 비가중
    유지). weights=None이면 기존과 완전히 동일 — 균등가중 하위호환.

    [v1.4.0 §1(B)] 실사용 실측(log3.txt)에서 워크포워드 재추정(79회 반복)이 전체 실행시간의
    상당 부분(1,352초)을 차지함을 확인 — IMPROVEMENT_PLAN_v1.4.md §1(B). 두 가지 성능
    개선을 추가했다(둘 다 PASS/FAIL 판정·가중치 산정에 영향을 주지 않음 — 결과가 기존과
    동일한지 단위테스트로 확인됨, /tmp/test_validate_indicators_perf_equiv.py):
      full_report=False — PASS/FAIL 판정과 가중치 산정에는 지표별 평가지평(h_eval) 하나의
        IC만 쓰인다(IC_5d/21d/63d, 표본수는 03시트 참고용 필드일 뿐, _select_and_weight_
        period()/_select_and_weight_hazard_period() 어디에도 쓰이지 않음 — 확인됨). 워크
        포워드 재추정(build_walkforward_weights)에서는 False로 호출해 IC 계산량을 지표당
        3회 -> 1회로 줄인다. 03시트를 채우는 최종 전체표본 호출은 기존처럼 True를 유지한다.
      fwd_full — forward_return()을 매 재추정(eval_end가 다른 79번의 호출)마다 그 시점까지로
        절단해 새로 계산하는 대신, 호출부(build_walkforward_weights)가 전체 이력에 대해 딱
        1회 계산해 넘겨주면 이 함수는 그 결과를 idx로 재인덱싱만 한다. 단, eval_end 이후의
        실제 데이터를 이미 본 값이 섞여 있으므로(전방 h일을 내다보는 값이라 eval_end 근처
        마지막 h개 관측치는 eval_end 너머의 값을 썼을 수 있음 — 이것이 룩어헤드다), 절단
        재계산이었다면 shift(-h)의 성질상 자연히 NaN이 됐을 idx의 마지막 h개 관측치를 그대로
        강제로 NaN 처리해 절단 재계산과 수학적으로 완전히 동일한 결과를 만든다(룩어헤드 차단
        유지, 단위테스트로 확인됨). None이면(기본, 기존 호출부와 하위호환) 기존과 동일하게
        이 함수 안에서 직접 계산한다.
        forward_maxdd()(dd_label)는 이 재사용 대상에서 제외했다 — rolling(h, min_periods=
        max(3,h//3))이 절단 구간 끝에서 "h일 전체가 아니어도" 부분 윈도우로 유효한 값을
        내는데, 전역계산을 그대로 마스킹하면 이 부분윈도우 값들까지 지워져 절단 재계산과
        결과가 미세하게(하락AUC 등에서) 달라짐을 단위테스트로 발견했다 — dd_label은 항상
        절단된 px로 직접 재계산해 기존과 100% 동일함을 보장한다(성능보다 정확성 우선 —
        사용자 지침 우선순위 (1) correctness > (3) performance).
    """
    t0 = time.time()
    idx = px_adj.index
    if eval_start is not None:
        idx = idx[idx >= eval_start]
    if eval_end is not None:
        idx = idx[idx <= eval_end]
    px = px_adj.reindex(idx)
    ind = ind.reindex(idx)
    w_all = weights.reindex(idx) if weights is not None else None

    # [v1.4.0 §1(B)2 정확성 수정] 최초 구현은 forward_maxdd() 결과(dd_label)도 fwd와 동일하게
    # "전역계산 + 마지막 h개 마스킹"으로 재사용하려 했으나, forward_maxdd()의 rolling(h,
    # min_periods=max(3,h//3))이 절단된 px에서는 구간 끝부분에서 "h일 전체가 아니라 h//3일
    # 이상만 있어도" 부분 윈도우로 유효한 값을 내는 것과 충돌해(전역계산을 그대로 마스킹하면
    # 이 부분윈도우 값들까지 지워져 절단 재계산과 결과가 달라짐 — 단위테스트
    # /tmp/test_validate_indicators_perf_equiv.py에서 발견/확인), dd_label은 안전하게
    # "절대 재사용하지 않고" 항상 절단된 px로 직접 재계산한다(기존과 100% 동일 보장).
    # fwd(forward_return)는 shift(-h) 단순 이동이라 부분윈도우 문제가 없어(경계선상 마지막
    # h개는 예외 없이 전부 NaN) 전역계산+마스킹 재사용이 절단 재계산과 수학적으로 완전히
    # 동일함이 단위테스트로 확인됐다 — fwd만 재사용해 일부 성능 이득을 취한다.
    if fwd_full is not None:
        fwd = {}
        for h in cfg.VAL_HORIZONS:
            fh = fwd_full[h].reindex(idx).astype(float).copy()
            cut = min(h, len(idx))
            if cut > 0:
                fh.iloc[-cut:] = np.nan
            fwd[h] = fh
    else:
        fwd = {h: forward_return(px, h) for h in cfg.VAL_HORIZONS}
    dd_label = {h: (forward_maxdd(px, h) <= cfg.DD_LABEL_THRESHOLD).astype(float)
                    .where(forward_maxdd(px, h).notna())
                for h in cfg.VAL_HORIZONS}

    # 시대별 안정성 확인용 4구간 분할
    blocks = np.array_split(np.arange(len(idx)), 4)
    rows: List[dict] = []

    for spec in INDICATOR_SPECS:
        x = ind[spec.key]
        cov = float(x.notna().mean()) if len(x) else 0.0
        # [v1.3.0 §3 버그수정] 커버리지가 "1990년부터의 전체 달력" 대비 비가중으로 계산되어,
        # 2000년대 이후 상장된 시리즈(VIX3M 2006년 등 기반 지표)는 최근 구간을 100% 커버해도
        # 구조적으로 불리했다(VIX_TERM 0.599 vs 기준 0.60처럼 0.1%p 차로 탈락 — 실사용 리포트
        # market_regime_report_2.xlsx에서 확인, IMPROVEMENT_PLAN_v1.3.md §3). v1.2.0에서
        # 도입된 시간감쇠(반감기)가 검증 통계 자체를 최근 구간 중심으로 계산하는 것과도
        # 방법론적으로 불일치했다. -> 판정에는 감쇠가중 커버리지(그 시점 가중치 총합 대비
        # 결측이 아닌 날의 가중치 비중)를 쓴다. weights=None이면 cov_w == cov로 완전히 동일
        # (하위호환 — 이 계산도 기존 평균과 수학적으로 같은 값이 된다).
        if w_all is not None:
            wsum_total = float(w_all.fillna(0).sum())
            cov_w = float(w_all.where(x.notna(), 0.0).fillna(0).sum() / wsum_total) if wsum_total > 0 else cov
        else:
            cov_w = cov
        # [v1.2.0] 지표별 평가지평(eval_horizon): 추세/저빈도 지표는 짧은 지평(기본 21일)에서
        # 평균회귀로 부호가 뒤집히는 경우가 있어, IndicatorSpec.eval_horizon이 지정되어 있고
        # cfg.VAL_HORIZONS에 포함된 값이면 그 지평을 검증에 사용한다. 미지정/비유효값이면
        # 기존과 동일하게 cfg.VAL_PRIMARY_H(기본 21일)를 그대로 쓴다 — 즉 하위호환.
        h_eval = spec.eval_horizon if spec.eval_horizon in cfg.VAL_HORIZONS else cfg.VAL_PRIMARY_H
        # [v1.2.0] 지표별 유효표본수: 이 지표가 실제 값을 가진 날짜만 골라 그 날짜들의
        # 감쇠가중치로 N_eff=(Σw)^2/Σw^2를 계산한다(투명성/추적성 — 03시트에 노출).
        n_eff_ind = effective_n(w_all.reindex(x.dropna().index)) if w_all is not None else np.nan
        # [v1.5.0 §A] 짧은이력(FRED_ALLOW_SHORT_HISTORY) 소속 지표는 커버리지/부호일치구간수
        # 게이트를 완화된 값으로 적용한다(근거: Config.MIN_COVERAGE_SHORT_HISTORY/
        # MIN_SUBPERIOD_AGREE_SHORT_HISTORY 정의부의 감쇠수학·4구간분할 증명 주석 참조).
        # 투명성/추적성(사용자 지침 우선순위 (2)) 확보를 위해 적용 여부와 실제 사용된 유효
        # 임계값을 03시트에 그대로 노출한다 — 완화가 "몰래" 적용되지 않도록.
        is_short_hist = _is_short_history_indicator(spec, cfg)
        eff_min_coverage = cfg.MIN_COVERAGE_SHORT_HISTORY if is_short_hist else cfg.MIN_COVERAGE
        eff_min_subperiod_agree = (cfg.MIN_SUBPERIOD_AGREE_SHORT_HISTORY if is_short_hist
                                    else cfg.MIN_SUBPERIOD_AGREE)
        # [v1.6.0 §A] 위험(해저드) 트랙 전용 구간일치수 유효임계값 — 표준트랙(eff_min_subperiod_
        # agree, 바로 위)과 별개로 계산한다. 짧은이력 지표는 유효구간이 원천적으로 1개뿐이므로
        # 기존처럼 MIN_SUBPERIOD_AGREE_SHORT_HISTORY(=1)가 우선 적용되고, 그 외 지표는 표준트랙의
        # MIN_SUBPERIOD_AGREE(=3, 4구간 초다수결) 대신 위험트랙 전용 HAZARD_MIN_SUBPERIOD_AGREE
        # (=2, 4구간 과반)를 쓴다 — 근거는 Config.HAZARD_MIN_SUBPERIOD_AGREE 정의부 주석 참조
        # (표준트랙 IC방향과 달리 위험트랙 AUC방향은 통화정책 국면에 따라 자연히 뒤집힐 수 있어
        # 초다수결 요구가 과함을 report5.xlsx 실측 30개 지표로 확인).
        eff_min_subperiod_agree_haz = (cfg.MIN_SUBPERIOD_AGREE_SHORT_HISTORY if is_short_hist
                                        else cfg.HAZARD_MIN_SUBPERIOD_AGREE)
        rec: Dict[str, object] = {
            "지표코드": spec.key, "지표명": spec.name_kr, "카테고리": spec.category,
            "사용데이터": spec.source, "선행메커니즘": spec.lead_mechanism,
            "경제적근거": spec.rationale, "사전방향": spec.prior_sign,
            "커버리지": round(cov, 3), "커버리지(가중)": round(cov_w, 3), "평가지평": h_eval,
            "추세트랙": bool(spec.trend_track),
            "N_eff": round(n_eff_ind, 1) if pd.notna(n_eff_ind) else np.nan,
            "짧은이력완화적용": is_short_hist,
            "유효최소커버리지": round(eff_min_coverage, 3),
            "유효최소구간일치수": eff_min_subperiod_agree,
            "위험트랙유효최소구간일치수": eff_min_subperiod_agree_haz,
        }

        # [v1.4.0 §1(B)1] full_report=False(워크포워드 호출)에서는 h_eval 하나만 계산한다 —
        # PASS/FAIL 판정·가중치 산정에 실제로 쓰이는 것은 IC_평가지평(=h_eval의 IC) 뿐이고
        # IC_5d/21d/63d·표본수는 03시트 참고용 필드일 뿐이다(위 docstring 근거).
        horizons_to_compute = cfg.VAL_HORIZONS if full_report else (h_eval,)
        for h in horizons_to_compute:
            ic, nobs = spearman_ic(x, fwd[h], weights=w_all)
            if full_report:
                rec[f"IC_{h}d"] = round(ic, 4) if pd.notna(ic) else np.nan
                if h == cfg.VAL_PRIMARY_H:
                    rec["표본수"] = nobs
            if h == h_eval:
                rec["IC_평가지평"] = round(ic, 4) if pd.notna(ic) else np.nan
                rec["표본수_평가지평"] = nobs

        h = h_eval
        ic_main = rec.get("IC_평가지평", np.nan)
        t_nw, p_nw = newey_west_tstat(x, fwd[h], lags=h, weights=w_all)
        rec["NW_t"] = round(t_nw, 3) if pd.notna(t_nw) else np.nan
        rec["NW_p"] = round(p_nw, 4) if pd.notna(p_nw) else np.nan

        if compute_quintiles:
            qm, qspread, mono = quintile_profile(x, fwd[h])
        else:
            qm, qspread, mono = [np.nan] * 5, np.nan, np.nan
        for i, v in enumerate(qm, start=1):
            rec[f"Q{i}수익률"] = round(v, 4) if pd.notna(v) else np.nan
        rec["Q5-Q1"] = round(qspread, 4) if pd.notna(qspread) else np.nan
        rec["단조성"] = round(mono, 3) if pd.notna(mono) else np.nan

        auc = auc_downside(x, dd_label[h], weights=w_all)
        rec["하락AUC"] = round(auc, 4) if pd.notna(auc) else np.nan
        rec["AUC엣지"] = round(abs(auc - 0.5), 4) if pd.notna(auc) else np.nan

        # 4구간 부호 안정성 (가중치도 구간별로 슬라이스하여 동일하게 가중 적용)
        # [v1.3.0 §4] 표준트랙(IC 부호 안정성)과 별개로, 위험트랙 판정에 쓸 "구간별 AUC"도
        # 같은 루프에서 함께 구한다(빈 슬라이스를 두 번 계산하지 않기 위함).
        signs, block_ics, block_aucs = [], [], []
        for b in blocks:
            if len(b) < 150:
                continue
            w_b = w_all.iloc[b] if w_all is not None else None
            sub_ic, _ = spearman_ic(x.iloc[b], fwd[h].iloc[b], weights=w_b)
            block_ics.append(round(sub_ic, 4) if pd.notna(sub_ic) else np.nan)
            if pd.notna(sub_ic):
                signs.append(np.sign(sub_ic))
            sub_auc = auc_downside(x.iloc[b], dd_label[h].iloc[b], weights=w_b)
            block_aucs.append(sub_auc)
        for i, v in enumerate(block_ics, start=1):
            rec[f"구간{i}IC"] = v
        if signs and pd.notna(ic_main) and ic_main != 0:
            agree = int(sum(1 for s in signs if s == np.sign(ic_main)))
        else:
            agree = 0
        rec["부호일치구간수"] = f"{agree}/{len(signs)}" if signs else "-"
        rec["_agree_n"] = agree

        # 실증 방향 (검증에서 확정)
        emp_sign = int(np.sign(ic_main)) if pd.notna(ic_main) and ic_main != 0 else 0
        rec["실증방향"] = emp_sign
        rec["사전방향일치"] = "일치" if emp_sign == spec.prior_sign else (
            "불일치(주의)" if emp_sign != 0 else "판정불가")

        # ---- PASS / FAIL 판정 ----
        # [v1.2.0] 추세트랙(spec.trend_track=True, 예: 200일선/12-1모멘텀/최고점대비낙폭 등
        # E.추세 카테고리): 후행적/느린 지표라 IC·Newey-West t 게이트를 그대로 적용하면
        # 항상 탈락하므로, 이 게이트는 면제하고 대신 하락판별력(AUC)과 4구간 부호안정성만으로
        # 채택 여부를 판단하는 별도 트랙을 적용한다. 커버리지·사전방향일치 게이트는 동일 적용.
        reasons: List[str] = []
        # [v1.3.0 §3] 판정은 가중 커버리지(cov_w) 기준 — weights=None이면 cov_w == cov.
        # [v1.5.0 §A] 짧은이력 지표는 eff_min_coverage(완화값)를 사용 — 그 외는 cfg.MIN_
        # COVERAGE와 동일(eff_min_coverage == cfg.MIN_COVERAGE이므로 결과 불변).
        if cov_w < eff_min_coverage:
            reasons.append(f"가중 커버리지 {cov_w:.0%} < {eff_min_coverage:.0%}"
                            + ("(짧은이력 완화값 적용, v1.5.0 §A)" if is_short_hist else ""))
        if not spec.trend_track:
            if pd.isna(ic_main) or abs(ic_main) < cfg.MIN_ABS_IC:
                reasons.append(f"|IC({h}d)| {abs(ic_main):.3f} < {cfg.MIN_ABS_IC}"
                               if pd.notna(ic_main) else "IC 산출불가")
            if pd.isna(t_nw) or abs(t_nw) < cfg.MIN_ABS_TSTAT:
                reasons.append(f"|NW t| {abs(t_nw):.2f} < {cfg.MIN_ABS_TSTAT}"
                               if pd.notna(t_nw) else "t값 산출불가")
        if pd.isna(auc) or abs(auc - 0.5) < cfg.MIN_AUC_EDGE:
            reasons.append(f"하락판별력 부족(AUC {auc:.3f})" if pd.notna(auc) else "AUC 산출불가")
        # [v1.5.0 §A] 짧은이력 지표는 eff_min_subperiod_agree(완화값)를 사용.
        if agree < eff_min_subperiod_agree:
            reasons.append(f"부호안정성 {agree}/{len(signs)} < {eff_min_subperiod_agree}"
                            + ("(짧은이력 완화값 적용, v1.5.0 §A)" if is_short_hist else ""))
        if emp_sign != 0 and emp_sign != spec.prior_sign:
            reasons.append("실증방향이 경제적 사전방향과 반대(신뢰도 낮음)")

        rec["판정"] = "PASS" if not reasons else "FAIL"
        rec["판정사유"] = " / ".join(reasons) if reasons else "모든 기준 통과"
        rec["검증트랙"] = "추세트랙(AUC+구간안정성만 게이트, IC/NW-t 면제)" if spec.trend_track \
            else "표준(IC+NW-t+AUC+구간안정성)"

        # ---- [v1.3.0 §4] 위험(해저드) 트랙 판정 ----------------------------------
        # VIX_LEVEL(하락AUC 0.623)처럼 "IC로는 사전방향과 반대(공포=매수기회, 평균회귀)지만
        # 하락사건 판별력(AUC)은 사전방향 그대로"인 지표가 표준트랙에서 전부 FAIL하는 문제가
        # 실사용 리포트에서 확인됐다(IMPROVEMENT_PLAN_v1.3.md §4) — IC(수익 예측)와 AUC(하락
        # 판별)는 서로 다른 질문이므로, 별도 트랙으로 분리한다. 대상은 추세트랙이 아닌 모든
        # 지표(추세트랙은 이미 자체 필터가 있어 제외). IC/NW-t는 전혀 보지 않고, "사전방향이
        # 가리키는 쪽으로 AUC가 실제로 치우쳐 있는가"만 본다 — prior_sign<0(예: VIX, "높으면
        # 위험")이면 AUC>0.5가, prior_sign>0(예: RSP/SPY 상대강도, "높으면 안전")이면 AUC<0.5가
        # 기대 방향이다(방향일치 시 값이 커지도록 부호를 붙인 auc_edge_signed로 통일).
        # 로직은 순수함수 _hazard_track_verdict()로 분리해 가격경로 없이도 단위테스트 가능하게 함.
        # [v1.5.0 §A] 커버리지는 표준트랙과 동일한 eff_min_coverage를 위험트랙 게이트에도 전달해,
        # 짧은이력 지표에 대해 두 트랙이 서로 다른 커버리지 기준을 쓰는 불일치가 생기지 않도록
        # 한다. [v1.6.0 §A] 구간일치수는 표준트랙(eff_min_subperiod_agree)과 분리된 위험트랙
        # 전용 eff_min_subperiod_agree_haz를 전달한다(짧은이력 지표는 두 값이 동일 — 우선순위
        # 변경 없음, Config.HAZARD_MIN_SUBPERIOD_AGREE 정의부 주석 참조).
        haz_verdict, auc_edge_signed, haz_agree, haz_signs_n, haz_reasons = _hazard_track_verdict(
            trend_track=spec.trend_track, prior_sign=spec.prior_sign, cov_w=cov_w, auc=auc,
            block_aucs=block_aucs, cfg=cfg,
            min_coverage=eff_min_coverage, min_subperiod_agree=eff_min_subperiod_agree_haz)
        rec["위험트랙판정"] = haz_verdict
        rec["위험트랙AUC엣지"] = round(auc_edge_signed, 4) if pd.notna(auc_edge_signed) else np.nan
        rec["위험트랙AUC방향안정성"] = f"{haz_agree}/{haz_signs_n}" if haz_signs_n else "-"
        rec["위험트랙판정사유"] = (" / ".join(haz_reasons) if haz_reasons else
                                  ("모든 기준 통과" if haz_verdict == "PASS" else ""))
        rows.append(rec)

        if verbose:
            log("VALIDATE", kv(indicator=spec.key, h=h_eval,
                               track="trend" if spec.trend_track else "std",
                               ic=ic_main if pd.notna(ic_main) else -9,
                               nw_t=t_nw if pd.notna(t_nw) else -9,
                               auc=auc if pd.notna(auc) else -9,
                               agree=rec["부호일치구간수"], cov=cov,
                               n_eff=n_eff_ind if pd.notna(n_eff_ind) else -1,
                               verdict=rec["판정"], haz_verdict=haz_verdict,
                               # [v1.5.0 §A] 짧은이력 게이트 완화 적용 여부/유효임계값을
                               # 로그에도 노출 — 완화가 실제로 몇 개 지표에, 어떤 값으로
                               # 적용됐는지 로그만으로 확인 가능하게(사용자 지침 §2 traceability).
                               short_hist=is_short_hist,
                               min_cov_eff=eff_min_coverage,
                               min_agree_eff=eff_min_subperiod_agree,
                               min_agree_eff_haz=eff_min_subperiod_agree_haz))

    res = pd.DataFrame(rows)
    n_pass = int((res["판정"] == "PASS").sum())
    if verbose:
        log("VALIDATE", kv(event="summary", candidates=len(res), passed=n_pass,
                           failed=len(res) - n_pass,
                           period=f"{idx[0].date()}~{idx[-1].date()}" if len(idx) else "-",
                           decay_weighted=w_all is not None,
                           elapsed_s=round(time.time() - t0, 2)))
        # [v1.5.0 §A] 짧은이력 게이트 완화가 실제로 몇 개 지표에 적용됐고 그 중 몇 개가
        # (표준트랙/위험트랙 각각) PASS로 전환됐는지 요약 — 완화의 실효과를 매 실행마다
        # 로그만으로 확인 가능하게 한다(사용자 지침 §2: "변경이 실제로 결과를 바꿨는지
        # 로그로 확인 가능해야 함").
        if "짧은이력완화적용" in res.columns:
            sh = res[res["짧은이력완화적용"]]
            if len(sh):
                log("VALIDATE", kv(event="short_history_gate_relax_summary",
                                   n_short_hist=len(sh),
                                   std_pass=int((sh["판정"] == "PASS").sum()),
                                   haz_pass=int((sh["위험트랙판정"] == "PASS").sum()),
                                   min_coverage_short=cfg.MIN_COVERAGE_SHORT_HISTORY,
                                   min_subperiod_agree_short=cfg.MIN_SUBPERIOD_AGREE_SHORT_HISTORY))
        # [v1.6.0 §A] 위험트랙 전용 구간일치수 완화(HAZARD_MIN_SUBPERIOD_AGREE)가 실제로 몇 개
        # (짧은이력이 아닌) 일반지표를 새로 PASS로 전환시켰는지 요약 — market_regime_report_5.
        # xlsx 실측(30개 지표, 커버리지(가중)~1.0인데 구간안정성 2/4<3 사유로만 FAIL)이 이
        # 변경의 직접 근거이므로, 매 실행마다 그 효과 규모를 로그로 확인 가능하게 한다.
        if "위험트랙AUC방향안정성" in res.columns and "짧은이력완화적용" in res.columns:
            def _parse_agree(s: object) -> Optional[int]:
                if not isinstance(s, str) or "/" not in s:
                    return None
                a, _, _b = s.partition("/")
                try:
                    return int(a)
                except ValueError:
                    return None
            haz_agree_n = res["위험트랙AUC방향안정성"].map(_parse_agree)
            rescued = res[(~res["짧은이력완화적용"]) & (res["위험트랙판정"] == "PASS") &
                          haz_agree_n.notna() &
                          (haz_agree_n >= cfg.HAZARD_MIN_SUBPERIOD_AGREE) &
                          (haz_agree_n < cfg.MIN_SUBPERIOD_AGREE)]
            if len(rescued):
                log("VALIDATE", kv(event="hazard_subperiod_relax_summary",
                                   n_rescued=len(rescued),
                                   hazard_min_subperiod_agree=cfg.HAZARD_MIN_SUBPERIOD_AGREE,
                                   std_min_subperiod_agree=cfg.MIN_SUBPERIOD_AGREE,
                                   rescued_codes=",".join(rescued["지표코드"].head(20).tolist())))
    return res


# =============================================================================
# [5] 복합점수 레이어 (walk-forward)
#     - 표준화는 expanding(과거 전체) 평균/표준편차로만 수행 -> 미래 분포 사용 금지
#     - 지표 채택/가중치는 매년 초, '그 시점까지의 데이터'로만 재검증하여 갱신
# =============================================================================
def expanding_zscore(s: pd.Series, min_obs: int = 252, clip: float = 3.0) -> pd.Series:
    """
    [룩어헤드 차단] t시점 z = (x_t - mean(x_{<=t})) / std(x_{<=t}).
    rolling이 아닌 expanding을 쓰는 이유: 표본 초기부터 사용 가능하고,
    미래 구간의 평균/표준편차가 절대 섞이지 않는다.
    """
    m = s.expanding(min_periods=min_obs).mean()
    v = s.expanding(min_periods=min_obs).std()
    z = (s - m) / v.replace(0, np.nan)
    return z.clip(-clip, clip)


def _select_and_weight_period(vt: pd.DataFrame, cfg: Config
                              ) -> Tuple[Optional[np.ndarray], Optional[np.ndarray], dict]:
    """
    [v1.2.0] 한 재추정 시점의 검증표(vt)로부터: 엄격PASS 선정 -> (부족 시) 보조채택 ->
    (그래도 0개면) TREND_200 최후 방어 -> |IC(평가지평)|·보조채택할인 비례 가중치 산출 ->
    추세트랙 가중치 상한 적용까지 수행한다.
    build_walkforward_weights()의 워밍업(연 1회) 루프와 본구간(REWEIGHT_FREQ) 루프가
    이 함수를 공유함으로써, 두 루프에서 보조채택·추세트랙상한 로직이 서로 다르게
    구현되어 어긋나는(=검증 기준이 재추정 주기에 따라 암묵적으로 달라지는) 위험을 없앤다.
    반환: (지표코드 배열 또는 None, 부호포함 정규화가중치 배열 또는 None, 로그용 부가정보 dict)
    """
    passed = vt[vt["판정"] == "PASS"].copy()
    passed["_보조채택"] = False
    info: Dict[str, object] = {}

    # [v1.2.0] 보조채택(soft adoption): 엄격 PASS 지표수가 cfg.MIN_INDICATORS 미만이면
    # FAIL 지표 중 (a) 커버리지 충분(cfg.MIN_COVERAGE 이상), (b) 실증방향이 경제적
    # 사전방향과 일치하는 지표를 |IC(평가지평)| 내림차순으로 최대 cfg.SOFT_ADOPT_MAX개까지
    # 보조채택한다. 보조채택 지표의 원시가중치에는 cfg.SOFT_ADOPT_WEIGHT_DISCOUNT(<1)를
    # 곱해 정식 PASS 지표보다 낮은 신뢰도로 반영한다.
    # 목적: 데이터 복구 초기 등으로 PASS 지표가 지나치게 적어 복합점수가 근소한 수의
    # 지표로만 산출되는 '신호 공백' 구간을 줄이되, 최대개수+가중치할인의 이중 제한으로
    # 무분별한 완화(=검증 기준 형해화)를 막는다.
    if len(passed) < cfg.MIN_INDICATORS:
        failed = vt[vt["판정"] == "FAIL"].copy()
        # [v1.3.0 §3] 정식 PASS 게이트와 동일하게 가중 커버리지 기준 사용(하위호환: 컬럼이
        # 없는 옛 검증표가 들어오면 "커버리지"로 폴백 — 이론상 발생하지 않지만 방어적으로 둠).
        cov_col = "커버리지(가중)" if "커버리지(가중)" in failed.columns else "커버리지"
        # [v1.5.0 §A] 정식 PASS 게이트가 짧은이력 지표에 완화된 커버리지 하한(유효최소커버리지
        # 컬럼, validate_indicators()에서 지표별로 채움)을 쓰는 것과 동일한 기준을 여기서도
        # 써야 일관된다 — 그렇지 않으면 정식게이트는 통과 가능한 커버리지(예: 0.50)인데
        # 보조채택 후보에서는 고정 cfg.MIN_COVERAGE(0.60)에 걸려 제외되는 모순이 생긴다.
        # 컬럼이 없는 옛 검증표(하위호환)에서는 기존과 동일하게 고정 cfg.MIN_COVERAGE를 쓴다.
        min_cov_eff = failed["유효최소커버리지"] if "유효최소커버리지" in failed.columns else cfg.MIN_COVERAGE
        cand = failed[(failed[cov_col] >= min_cov_eff) &
                      (failed["사전방향일치"] == "일치")].copy()
        cand["_absic"] = cand["IC_평가지평"].abs().fillna(0.0)
        cand = cand.sort_values("_absic", ascending=False)
        soft = cand.head(cfg.SOFT_ADOPT_MAX).copy()
        soft["_보조채택"] = True
        info["soft_adopt"] = len(soft)
        info["n_strict_pass"] = len(passed)
        info["soft_codes"] = ",".join(soft["지표코드"].tolist())
        passed = pd.concat([passed, soft], ignore_index=True)

    if len(passed) == 0:
        info["fallback_trend"] = True
        passed = vt[vt["지표코드"] == "TREND_200"].copy()   # 최후 방어: 추세필터만 사용
        if len(passed) == 0:
            return None, None, info
        passed["_보조채택"] = False
        passed = passed.assign(**{"IC_평가지평": 0.05, "실증방향": 1})

    w_raw = passed["IC_평가지평"].abs().fillna(0.0).values.astype(float)
    discount = np.where(passed["_보조채택"].values, cfg.SOFT_ADOPT_WEIGHT_DISCOUNT, 1.0)
    w_raw = w_raw * discount
    if w_raw.sum() <= 0:
        w_raw = np.ones(len(passed)) * discount
    w_norm = w_raw / w_raw.sum()
    signs = passed["실증방향"].replace(0, 1).values
    codes = passed["지표코드"].values
    trend_flags = (passed["추세트랙"].fillna(False).values.astype(bool)
                   if "추세트랙" in passed.columns else np.zeros(len(passed), dtype=bool))

    w_signed = w_norm * signs

    # [v1.2.0] 추세트랙 가중치 상한: E.추세 카테고리 등 trend_track 지표들의 절대가중치
    # 합이 cfg.TREND_TRACK_WEIGHT_CAP(기본 0.30)를 넘으면 상한까지 축소하고, 풀려난
    # 비중은 비-추세트랙(선행) 지표들에 비례 재분배한다. 비-추세트랙 지표가 하나도 없는
    # 극단적 경우엔 재분배 없이 상한만 적용한다 — composite_score()가 매일 그날 사용가능한
    # 지표 기준으로 |가중치| 합으로 다시 나눠 정규화하므로(denom 로직) 안전하다.
    # 목적: 후행적 추세추종 지표군이 선행지표군을 압도해 '선행지표 기반 조기경보'라는
    # 시스템의 핵심 목적이 희석되는 것을 구조적으로 방지.
    trend_sum = float(np.abs(w_signed[trend_flags]).sum()) if trend_flags.any() else 0.0
    if trend_sum > cfg.TREND_TRACK_WEIGHT_CAP:
        scale = cfg.TREND_TRACK_WEIGHT_CAP / trend_sum
        freed = trend_sum - cfg.TREND_TRACK_WEIGHT_CAP
        w_signed[trend_flags] = w_signed[trend_flags] * scale
        nontrend_sum = float(np.abs(w_signed[~trend_flags]).sum())
        if nontrend_sum > 0:
            w_signed[~trend_flags] = w_signed[~trend_flags] * (1.0 + freed / nontrend_sum)
        info["trend_cap_applied"] = True
        info["trend_sum_before"] = round(trend_sum, 4)
        info["trend_redistributed"] = bool(nontrend_sum > 0)

    # [v1.3.0 §6] 기저 시리즈별 가중치 상한 — 추세트랙 캡과 같은 단일패스 축소+재분배
    # 설계를 그룹 단위로 일반화한다. 그룹 키는 IndicatorSpec.base_series(명시된 경우) 또는
    # 자동생성 지표(auto=True)의 series_id — 원천이 불분명한 수기 지표(base_series="")는
    # 캡 대상에서 제외한다(과도한 일반화로 기존 검증된 소규모 채택 구간의 동작을 바꾸지
    # 않기 위함). 트렌드캡 적용 '이후' 시점의 w_signed를 대상으로 하여, 두 상한이
    # 중첩 적용(예: 추세트랙이면서 동일 시리즈 다중파생인 경우)될 수 있게 한다.
    group_keys = np.array([
        (SPEC_BY_KEY[c].base_series or (SPEC_BY_KEY[c].series_id if SPEC_BY_KEY[c].auto else ""))
        if c in SPEC_BY_KEY else ""
        for c in codes
    ])
    series_cap_events: List[dict] = []
    for g in pd.unique(group_keys):
        if not g:
            continue    # 기저 시리즈 불명 -> 캡 미적용
        gmask = group_keys == g
        gsum = float(np.abs(w_signed[gmask]).sum())
        if gsum > cfg.SERIES_WEIGHT_CAP:
            scale = cfg.SERIES_WEIGHT_CAP / gsum
            freed = gsum - cfg.SERIES_WEIGHT_CAP
            w_signed[gmask] = w_signed[gmask] * scale
            other_mask = ~gmask
            other_sum = float(np.abs(w_signed[other_mask]).sum())
            if other_sum > 0:
                w_signed[other_mask] = w_signed[other_mask] * (1.0 + freed / other_sum)
            series_cap_events.append({"series": g, "sum_before": round(gsum, 4),
                                      "redistributed": bool(other_sum > 0)})
    if series_cap_events:
        info["series_cap_applied"] = True
        info["series_cap_detail"] = "; ".join(
            f"{e['series']}:{e['sum_before']:.3f}→{cfg.SERIES_WEIGHT_CAP:.2f}" for e in series_cap_events)

    info["n_selected"] = len(passed)
    info["n_soft"] = int(passed["_보조채택"].sum())
    return codes, w_signed, info


def _select_and_weight_hazard_period(vt: pd.DataFrame, cfg: Config
                                     ) -> Tuple[Optional[np.ndarray], Optional[np.ndarray], dict]:
    """
    [v1.3.0 §4(B)] 위험(해저드) 트랙 전용 선정·가중치 함수. _select_and_weight_period()(수익
    트랙)와 같은 vt(그 재추정 시점의 validate_indicators() 결과)를 입력받아 별도의 가중치
    행렬을 산출한다 — 같은 vt를 재사용하므로 검증 자체(비용 지배 요인)를 두 번 하지 않는다.

    수익 트랙과의 핵심 차이 3가지 (IMPROVEMENT_PLAN_v1.3.md §4(B)):
      1. 선정 기준은 "위험트랙판정"=="PASS"뿐이다(IC/NW-t 불문 — validate_indicators()의
         _hazard_track_verdict()가 이미 AUC 방향성·안정성·가중커버리지만으로 판정했다).
      2. 가중치는 |위험트랙AUC엣지| 비례.
      3. 부호는 반드시 '경제적 사전방향의 반대(-사전방향)'로 고정한다 — 예: VIX_LEVEL은
         사전방향=-1("높으면 위험")이므로 부호=+1, 즉 값이 높을수록 H가 올라가도록 만든다.
         실증 IC 부호를 쓰지 않는 것이 이 트랙이 존재하는 이유 그 자체다(실증 IC 부호를 쓰면
         VIX_LEVEL 같은 지표는 다시 "하락 뒤 반등"쪽으로 가중돼 위험 감지 기능을 상실한다).
    또한 보조채택(soft-adoption)·추세트랙 가중치상한·TREND_200 최후방어 폴백을 전혀 적용하지
    않는다 — 해저드 신호가 비어 있는 것("위험하다는 근거가 없다")은 안전한 상태이지, 수익
    트랙처럼 반드시 채워야 하는 신호 공백이 아니기 때문이다(§4(B) 명시).
    §6 기저 시리즈 가중치 상한(SERIES_WEIGHT_CAP)은 수익 트랙과 동일 로직으로, 위험 트랙에도
    독립적으로 적용한다(§6 수용기준 "수익 트랙과 위험 트랙 각각 독립 적용").

    [v1.4.0 §3(a) ⚠ 신호(위험) 파라미터] TOP_K 압축을 이 함수에서 수행한다(게이트 판정 자체는
    여전히 _hazard_track_verdict()의 몫). 게이트 통과 지표수가 cfg.HAZARD_TOP_K를 초과하면
    |위험트랙AUC엣지| 내림차순 상위 cfg.HAZARD_TOP_K개만 남기고 나머지는 버린다 — 자세한
    근거는 아래 본문 주석과 IMPROVEMENT_PLAN_v1.4.md §3 참조.

    반환: (지표코드 배열 또는 None, 부호포함 정규화가중치 배열 또는 None, 로그용 부가정보 dict)
    """
    info: Dict[str, object] = {}
    if "위험트랙판정" not in vt.columns:
        return None, None, info   # 하위호환: 옛 vt(위험트랙 컬럼 없음)가 들어오면 조용히 비활성
    haz = vt[vt["위험트랙판정"] == "PASS"].copy()
    if len(haz) == 0:
        info["n_selected"] = 0
        return None, None, info

    # [v1.4.0 §3(a) ⚠ 신호(위험) 파라미터] TOP_K 압축(희석 방지) — IMPROVEMENT_PLAN_v1.4.md §3
    # 진단: 게이트를 통과하는 위험트랙 지표가 재추정 시점마다 55~80개에 달해, |AUC엣지| 비례
    # 가중이 그 개수 전체로 분산되면 발행지연 35~75일짜리 느린 거시지표들의 합산 가중치가
    # VIX_TERM/NFCI_CHG5/ANFCI_CHG5/RVOL_RATIO/VIX_LEVEL 같은 빠르고 반응성 높은 지표를
    # 압도해버린다(log3.txt/report3.xlsx 06c 임계값민감도 시트: HAZARD_ENTER가 0.85~0.95
    # 전 구간에서 MDD가 전혀 변하지 않음 — 사실상 '죽은 규칙'이 되는 근본 원인으로 진단됨).
    # 대응: 게이트 통과 지표 중 |위험트랙AUC엣지| 내림차순 상위 cfg.HAZARD_TOP_K(기본 15)개만
    # 채택해 위험 트랙을 소수의 강한 신호로 압축한다. 통과 지표수가 HAZARD_TOP_K 이하이면
    # 있는 그대로 전부 사용한다(인위적 패딩 없음 — 위 docstring 원칙과 동일하게 신호가 적으면
    # 적은 대로 둔다). 이 절단은 정렬 기준(|AUC엣지|)이 이미 게이트를 통과한 지표들 사이의
    # 순위이므로 게이트 자체(_hazard_track_verdict)를 흔들지 않는다 — 판정과 압축을 분리해
    # 두 파라미터(HAZARD_MIN_AUC_EDGE와 HAZARD_TOP_K)의 효과를 로그에서 독립적으로 추적할
    # 수 있게 한다.
    info["n_gate_passed"] = int(len(haz))
    if len(haz) > cfg.HAZARD_TOP_K:
        abs_edge = haz["위험트랙AUC엣지"].abs().fillna(0.0)
        haz = haz.loc[abs_edge.sort_values(ascending=False).index].head(cfg.HAZARD_TOP_K).copy()
        info["topk_applied"] = True
    else:
        info["topk_applied"] = False
    info["n_after_topk"] = int(len(haz))

    w_raw = haz["위험트랙AUC엣지"].abs().fillna(0.0).values.astype(float)
    if w_raw.sum() <= 0:
        w_raw = np.ones(len(haz))
    w_norm = w_raw / w_raw.sum()
    signs = -haz["사전방향"].replace(0, 1).values     # 고정 부호(실증 IC 부호 금지 — §4 핵심)
    codes = haz["지표코드"].values

    w_signed = w_norm * signs

    # [v1.3.0 §6] 기저 시리즈 가중치 상한 — 수익 트랙과 동일 단일패스 축소+재분배, 위험
    # 트랙에 독립 적용(같은 group_keys 산출 로직을 재사용).
    group_keys = np.array([
        (SPEC_BY_KEY[c].base_series or (SPEC_BY_KEY[c].series_id if SPEC_BY_KEY[c].auto else ""))
        if c in SPEC_BY_KEY else ""
        for c in codes
    ])
    series_cap_events: List[dict] = []
    for g in pd.unique(group_keys):
        if not g:
            continue
        gmask = group_keys == g
        gsum = float(np.abs(w_signed[gmask]).sum())
        if gsum > cfg.SERIES_WEIGHT_CAP:
            scale = cfg.SERIES_WEIGHT_CAP / gsum
            freed = gsum - cfg.SERIES_WEIGHT_CAP
            w_signed[gmask] = w_signed[gmask] * scale
            other_mask = ~gmask
            other_sum = float(np.abs(w_signed[other_mask]).sum())
            if other_sum > 0:
                w_signed[other_mask] = w_signed[other_mask] * (1.0 + freed / other_sum)
            series_cap_events.append({"series": g, "sum_before": round(gsum, 4),
                                      "redistributed": bool(other_sum > 0)})
    if series_cap_events:
        info["series_cap_applied"] = True
        info["series_cap_detail"] = "; ".join(
            f"{e['series']}:{e['sum_before']:.3f}→{cfg.SERIES_WEIGHT_CAP:.2f}" for e in series_cap_events)

    # [v1.14.0 §B] 위험트랙 카테고리 가중 상한(기본 None=비활성) — 특정 카테고리(위기 직후의
    # 금리계열 등)가 H를 독식하는 편중을 제한한다. 시리즈캡과 동일한 단일패스 축소+재분배를
    # vt의 "카테고리" 컬럼 그룹에 적용. 비활성이면 이 블록은 완전히 건너뛴다(하위호환).
    if cfg.HAZARD_CATEGORY_WEIGHT_CAP is not None and "카테고리" in haz.columns:
        cat_keys = haz["카테고리"].fillna("").values
        cat_cap_events: List[dict] = []
        for g in pd.unique(cat_keys):
            if not g:
                continue
            gmask = cat_keys == g
            gsum = float(np.abs(w_signed[gmask]).sum())
            if gsum > cfg.HAZARD_CATEGORY_WEIGHT_CAP:
                scale = cfg.HAZARD_CATEGORY_WEIGHT_CAP / gsum
                freed = gsum - cfg.HAZARD_CATEGORY_WEIGHT_CAP
                w_signed[gmask] = w_signed[gmask] * scale
                other_mask = ~gmask
                other_sum = float(np.abs(w_signed[other_mask]).sum())
                if other_sum > 0:
                    w_signed[other_mask] = w_signed[other_mask] * (1.0 + freed / other_sum)
                cat_cap_events.append({"cat": g, "sum_before": round(gsum, 4)})
        if cat_cap_events:
            info["category_cap_applied"] = True
            info["category_cap_detail"] = "; ".join(
                f"{e['cat']}:{e['sum_before']:.3f}→{cfg.HAZARD_CATEGORY_WEIGHT_CAP:.2f}"
                for e in cat_cap_events)

    info["n_selected"] = len(haz)
    return codes, w_signed, info


def _reestimation_boundaries(idx: pd.DatetimeIndex, start: pd.Timestamp, end: pd.Timestamp,
                             freq: str) -> List[pd.Timestamp]:
    """
    [v1.2.0] start~end 구간에서 freq("D"=매일/"W"=매주/"M"=매월/"A"=매년)에 따른 재추정
    경계일 목록을 생성한다. 각 경계일 t는 '그 날짜부터 다음 경계일 전날까지' 하나의
    가중치 벡터가 적용되는 구간의 시작이며, 실제 학습종료일은 호출부에서 t-1일로 계산한다
    (재추정 당일 장 마감 전 데이터는 아직 확정되지 않았다는 기존 연간로직의 보수적 관례를
    그대로 유지 — 룩어헤드 차단).
    """
    if start > end or len(idx) == 0:
        return []
    if freq == "D":
        return [pd.Timestamp(d) for d in idx[(idx >= start) & (idx <= end)]]
    if freq == "A":
        years = sorted({y for y in idx.year if pd.Timestamp(f"{y}-01-01") >= start
                        and pd.Timestamp(f"{y}-01-01") <= end})
        return [pd.Timestamp(f"{y}-01-01") for y in years]
    alias = {"W": "W-MON", "M": "MS"}.get(freq, "W-MON")
    raw = list(pd.date_range(start, end, freq=alias))
    if not raw or raw[0] > start:
        raw = [start] + raw
    return raw


def build_walkforward_weights(ind: pd.DataFrame, px_adj: pd.Series, cfg: Config = CFG,
                              collect_vt: Optional[List[dict]] = None
                              ) -> Tuple[pd.DataFrame, List[dict], pd.DataFrame]:
    """
    '그 재추정 시점 이전 데이터만' 사용해 재검증 -> PASS(+보조채택) 지표와 가중치 결정.
    가중치 = |IC(평가지평)| 비례(부호는 실증방향), 절대값 합이 1이 되도록 정규화(추세트랙
    상한 적용 후에도 유지).

    [v1.3.0 §4(B)] 위험(해저드) 트랙 가중치 행렬(W_haz)도 이 함수 안에서 함께 만든다.
    매 재추정 시점마다 이미 validate_indicators()로 그 시점까지의 vt(검증표)를 만드는데
    (비용 지배 요인, 전체 실행시간의 대부분), 이 vt에는 "위험트랙판정"/"위험트랙AUC엣지"
    컬럼이 이미 포함돼 있으므로 _select_and_weight_hazard_period()로 별도 가중치만
    산출하면 된다 — validate_indicators()를 위험 트랙용으로 한 번 더 호출(=전체 실행시간
    거의 2배)하지 않기 위한 설계 결정(§8 성능 목표: 위험트랙 추가로 큰 증가 없어야 정상).

    [v1.2.0] 재추정 주기 일반화 + 시간감쇠 가중 (개선명세서 §4.2~4.4):
    - SIGNAL_START 이전(워밍업): cfg.WARMUP_REWEIGHT_FREQ(기본 "A"=연 1회)로 재추정.
      복합점수 백분위(expanding rank)가 SIGNAL_START 시점에 안정적인 분포를 갖도록
      매매 시작 전부터 충분한 이력의 점수를 만들어 둔다.
    - SIGNAL_START 이후(본구간): cfg.REWEIGHT_FREQ("D"/"W"/"M", 기본 "W"=주1회)로 재추정.
      "일 단위 expanding 학습"이라는 사용자 요구는 (a) 복합점수의 expanding z-score/백분위가
      이미 매일 자동으로 전체 과거이력을 반영하는 것으로 1차 충족되고, (b) 지표 PASS/FAIL
      재판정·가중치 자체는 주1회(기본) 재추정하되 매 재추정마다 '그 시점까지의 전체 이력'을
      다시 검증에 사용한다는 점에서 2차로 충족된다 — 매일 284개 지표를 전부 재검증하면
      1회 실행이 1시간을 넘겨(사용자 위임: "어디부터 어디까지는 너가 적당히 정하고") 실용성이
      없으므로, 하루치 데이터가 통계량을 사실상 바꾸지 않는다는 점을 근거로 기본 주기를
      주1회로 정했다(CHANGELOG 명시). cfg.REWEIGHT_FREQ="D"로 바꾸면 완전한 일 단위 재검증도
      가능하다.
    - 시간감쇠 가중(cfg.HALF_LIFE_DAYS, 달력일 기준, 기본 913일≈2.5년): 매 재추정마다 그 시점까지의 전체
      이력(DATA_START~train_end)에 대해 asof=train_end 기준 지수감쇠가중치를 다시 계산해
      IC/NW-t/AUC/구간별IC에 적용한다 — "오래된 데이터는 '그런 케이스가 있었다' 수준으로만,
      최신 데이터에 비중"이라는 요구를 통계적으로 구현한 것. asof를 반드시 매 루프마다
      train_end로 재계산하는 것이 룩어헤드 차단의 핵심이다(decay_weights() 참조).
    - N_eff(유효표본수) 안전장치: 유효표본이 cfg.N_EFF_MIN 미만이면 그 재추정을 건너뛰고
      직전 가중치를 그대로 그 구간에 이어붙인다(가중치가 소수의 최근 관측치에만 의존하는
      불안정한 재추정을 방지).

    반환: (일자별 가중치 행렬, 재추정 시점별 가중치/진단 로그)
    """
    t0 = time.time()
    idx = px_adj.index
    sig_start = pd.Timestamp(cfg.SIGNAL_START)
    # 복합점수 백분위를 안정화하려면 신호 시작 이전에도 점수가 존재해야 한다.
    # -> 학습 가능한 가장 이른 해부터 가중치를 만들어 둔다(신호 자체는 SIGNAL_START부터 사용).
    warm_start = pd.Timestamp(cfg.DATA_START) + pd.DateOffset(years=cfg.TRAIN_MIN_YEARS)
    first_year = min(sig_start.year, max(warm_start.year, idx[0].year + cfg.TRAIN_MIN_YEARS))
    first_dt = pd.Timestamp(f"{first_year}-01-01")

    warm_bounds = _reestimation_boundaries(idx, first_dt, sig_start - pd.Timedelta(days=1),
                                           cfg.WARMUP_REWEIGHT_FREQ)
    main_bounds = _reestimation_boundaries(idx, max(sig_start, first_dt), idx[-1],
                                           cfg.REWEIGHT_FREQ)
    bounds = sorted(set(warm_bounds) | set(main_bounds))

    keys = [s.key for s in INDICATOR_SPECS]
    W = pd.DataFrame(0.0, index=idx, columns=keys)
    W_haz = pd.DataFrame(0.0, index=idx, columns=keys)   # [v1.3.0 §4(B)]
    wlog: List[dict] = []
    if not bounds:
        log("COMPOSITE", kv(event="walkforward_no_boundaries", first_dt=str(first_dt.date())),
            "warning")
        return W, wlog, W_haz

    prev_codes: Optional[np.ndarray] = None
    prev_w: Optional[np.ndarray] = None
    prev_codes_haz: Optional[np.ndarray] = None
    prev_w_haz: Optional[np.ndarray] = None

    # [v1.4.0 §1(B)2 성능] forward_return()은 전체 이력에 대해 여기서 딱 1회만 계산해 아래
    # 79회 재추정 루프 전체가 재사용한다 — validate_indicators()가 매 호출마다 eval_end
    # 이후로 새어들 수 있는 마지막 h개 관측치를 강제로 NaN 마스킹하므로 절단 재계산과 결과가
    # 완전히 동일하다(룩어헤드 차단 유지, 단위테스트로 확인됨 — IMPROVEMENT_PLAN_v1.4.md
    # §1(B), /tmp/test_validate_indicators_perf_equiv.py). forward_maxdd(dd_label)는 재사용
    # 대상에서 제외했다 — validate_indicators() docstring의 §1(B) 절 참조(부분윈도우 불일치).
    fwd_full = {h: forward_return(px_adj, h) for h in cfg.VAL_HORIZONS}

    for i, t in enumerate(bounds):
        cadence = "연간(워밍업)" if t < sig_start else cfg.REWEIGHT_FREQ
        train_end = t - pd.Timedelta(days=1)
        train_idx = idx[idx <= train_end]
        period_end = (bounds[i + 1] - pd.Timedelta(days=1)) if i + 1 < len(bounds) else idx[-1]
        mask = (idx >= t) & (idx <= period_end)
        if not mask.any():
            continue
        if len(train_idx) < cfg.TRAIN_MIN_YEARS * 252:
            log("COMPOSITE", kv(event="skip_period_insufficient_train",
                                reestim_date=str(t.date()), train_days=len(train_idx)),
                "warning")
            continue

        # [v1.2.0] 시간감쇠 가중치: 이 재추정 시점(t) 기준 asof=train_end로 매번 새로 계산한다
        # (전역/최종일자 기준으로 한 번만 계산해 재사용하면 룩어헤드가 생긴다 — §4.4).
        w_decay = decay_weights(train_idx, asof=train_end, half_life_days=cfg.HALF_LIFE_DAYS)
        n_eff = effective_n(w_decay) if w_decay is not None else float("nan")

        if (w_decay is not None and pd.notna(n_eff) and n_eff < cfg.N_EFF_MIN
                and prev_codes is not None):
            log("COMPOSITE", kv(event="skip_low_n_eff_carry_forward",
                                reestim_date=str(t.date()), n_eff=round(n_eff, 1),
                                min_required=cfg.N_EFF_MIN), "warning")
            for k, w in zip(prev_codes, prev_w):
                W.loc[mask, k] = float(w)
            entry = {"재추정시작일": str(t.date()), "재추정종료일": str(period_end.date()),
                     "주기": cadence, "학습종료일": str(train_end.date()),
                     "학습일수": len(train_idx), "N_eff": round(n_eff, 1),
                     "직전가중치유지": True, "채택지표수": len(prev_codes), "보조채택수": np.nan,
                     "위험채택지표수": len(prev_codes_haz) if prev_codes_haz is not None else 0}
            for k, w in zip(prev_codes, prev_w):
                entry[k] = round(float(w), 4)
            # [v1.3.0 §4(B)] 위험트랙도 동일하게 직전 가중치 유지(재추정 자체를 건너뛰므로
            # 위험트랙만 따로 새로 추정할 근거도 없다 — 같은 w_decay/N_eff를 공유하는 재추정).
            if prev_codes_haz is not None:
                for k, w in zip(prev_codes_haz, prev_w_haz):
                    W_haz.loc[mask, k] = float(w)
                    entry[f"[해저드]{k}"] = round(float(w), 4)
            wlog.append(entry)
            # [v1.14.0 §B] 캡 재시뮬레이션용 수집 — 직전 가중치 유지 구간은 vt=None으로 표시
            # (재시뮬레이션도 동일하게 직전 케이스 가중치를 이어붙인다).
            if collect_vt is not None:
                collect_vt.append({"t": t, "mask": mask.copy(), "vt": None})
            continue

        # [v1.4.0 §1(B)1·2] full_report=False(h_eval IC만 계산) + 전역 fwd_full 재사용 —
        # PASS/FAIL 판정·가중치 산정 결과는 기존과 동일(단위테스트로 확인됨).
        vt = validate_indicators(ind, px_adj, cfg,
                                 eval_end=train_end, verbose=False,
                                 compute_quintiles=False, weights=w_decay,
                                 full_report=False, fwd_full=fwd_full)
        codes, w_signed, info = _select_and_weight_period(vt, cfg)
        # [v1.3.0 §4(B)] 위험트랙 가중치 — 같은 vt 재사용(validate_indicators() 재호출 없음).
        codes_haz, w_signed_haz, info_haz = (
            _select_and_weight_hazard_period(vt, cfg) if cfg.USE_HAZARD_TRACK else (None, None, {}))
        # [v1.14.0 §B] 캡 재시뮬레이션용 수집 — 위험트랙 재선정에 필요한 5컬럼만 복사(저용량).
        # 이 캐시로 hazard_cap_sensitivity()가 validate_indicators() 재실행 없이(비용 지배
        # 요인 회피) 카테고리 상한 케이스별 W_haz를 재구축할 수 있다.
        if collect_vt is not None:
            _vt_cols = [c for c in ["지표코드", "카테고리", "위험트랙판정", "위험트랙AUC엣지",
                                    "사전방향"] if c in vt.columns]
            collect_vt.append({"t": t, "mask": mask.copy(), "vt": vt[_vt_cols].copy()})

        if info.get("soft_adopt"):
            log("COMPOSITE", kv(event="soft_adopt", reestim_date=str(t.date()),
                                n_strict_pass=info["n_strict_pass"],
                                n_soft_adopted=info["soft_adopt"],
                                soft_codes=info["soft_codes"]), "warning")
        if info.get("fallback_trend"):
            log("COMPOSITE", kv(event="no_pass_fallback_trend", reestim_date=str(t.date())),
                "warning")
        if info.get("trend_cap_applied"):
            log("COMPOSITE", kv(event="trend_track_cap_applied", reestim_date=str(t.date()),
                                trend_sum_before=info["trend_sum_before"],
                                cap=cfg.TREND_TRACK_WEIGHT_CAP,
                                redistributed=info["trend_redistributed"]), "warning")
        if info.get("series_cap_applied"):
            log("COMPOSITE", kv(event="series_weight_cap_applied", reestim_date=str(t.date()),
                                cap=cfg.SERIES_WEIGHT_CAP, detail=info["series_cap_detail"]),
                "warning")
        if info_haz.get("series_cap_applied"):
            log("COMPOSITE", kv(event="hazard_series_weight_cap_applied", reestim_date=str(t.date()),
                                cap=cfg.SERIES_WEIGHT_CAP, detail=info_haz["series_cap_detail"]),
                "warning")
        # [v1.14.0 §B] 카테고리 상한 발동 추적(기본 None이라 평소 미발동 — 켜진 실행에서만).
        if info_haz.get("category_cap_applied"):
            log("COMPOSITE", kv(event="hazard_category_cap_applied", reestim_date=str(t.date()),
                                cap=cfg.HAZARD_CATEGORY_WEIGHT_CAP,
                                detail=info_haz["category_cap_detail"]), "warning")
        # [v1.4.0 §3(a)] TOP_K 압축이 실제로 발동했는지(게이트 통과수가 HAZARD_TOP_K를
        # 초과해 절단이 일어났는지) 매 재추정 시점마다 추적 가능하도록 로깅 — 이 값이 로그에
        # 없으면 HAZARD_TOP_K가 실제로 무엇을 하고 있는지 나중에 검증할 수 없다(사용자 지침:
        # 투명성/추적가능성).
        if info_haz.get("topk_applied"):
            log("COMPOSITE", kv(event="hazard_topk_applied", reestim_date=str(t.date()),
                                n_gate_passed=info_haz["n_gate_passed"],
                                top_k=cfg.HAZARD_TOP_K,
                                n_after_topk=info_haz["n_after_topk"]), "info")

        if codes is None:
            log("COMPOSITE", kv(event="skip_period_no_indicators", reestim_date=str(t.date())),
                "error")
            continue

        for k, w in zip(codes, w_signed):
            W.loc[mask, k] = float(w)
        # [v1.3.0 §4(B)] 위험트랙: 채택 지표가 0개인 것은 정상/안전한 상태다(§4(B) 명시 —
        # 수익트랙과 달리 TREND_200류 최후방어 폴백을 두지 않는다). W_haz는 이미 0으로
        # 초기화돼 있으므로 codes_haz가 None이면 그냥 이 구간을 건너뛴다(값 전부 0 유지).
        if codes_haz is not None:
            for k, w in zip(codes_haz, w_signed_haz):
                W_haz.loc[mask, k] = float(w)

        entry = {"재추정시작일": str(t.date()), "재추정종료일": str(period_end.date()),
                 "주기": cadence, "학습종료일": str(train_end.date()),
                 "학습일수": len(train_idx),
                 "N_eff": round(n_eff, 1) if pd.notna(n_eff) else np.nan,
                 "직전가중치유지": False,
                 "채택지표수": info["n_selected"], "보조채택수": info["n_soft"],
                 "위험채택지표수": info_haz.get("n_selected", 0),
                 # [v1.4.0 §3(a)] TOP_K 압축 전 게이트 통과 원본 수 — 압축 폭을 08시트에서
                 # 바로 확인할 수 있도록(위험채택지표수와의 차이 = 절단된 지표수).
                 "위험게이트통과수": info_haz.get("n_gate_passed", info_haz.get("n_selected", 0))}
        for k, w in zip(codes, w_signed):
            entry[k] = round(float(w), 4)
        if codes_haz is not None:
            for k, w in zip(codes_haz, w_signed_haz):
                entry[f"[해저드]{k}"] = round(float(w), 4)
        wlog.append(entry)
        log("COMPOSITE", kv(event="reweight", reestim_date=str(t.date()), cadence=cadence,
                            train_end=str(train_end.date()), n_selected=info["n_selected"],
                            n_soft=info["n_soft"],
                            n_selected_haz=info_haz.get("n_selected", 0),
                            n_eff=round(n_eff, 1) if pd.notna(n_eff) else -1,
                            selected=",".join(codes.tolist()[:8])))
        prev_codes, prev_w = codes, w_signed
        prev_codes_haz, prev_w_haz = codes_haz, w_signed_haz

    log("COMPOSITE", kv(event="walkforward_done", periods=len(wlog),
                        warmup_freq=cfg.WARMUP_REWEIGHT_FREQ, main_freq=cfg.REWEIGHT_FREQ,
                        half_life_days=cfg.HALF_LIFE_DAYS,
                        use_hazard_track=cfg.USE_HAZARD_TRACK,
                        elapsed_s=round(time.time() - t0, 2)))
    return W, wlog, W_haz


def composite_score(ind: pd.DataFrame, W: pd.DataFrame, cfg: Config = CFG
                    ) -> Tuple[pd.Series, pd.DataFrame, pd.Series]:
    """
    복합점수 = Σ (가중치_i × z_i) / Σ |가중치_i|  (그날 값이 존재하는 지표만으로 재정규화)
    반환: (복합점수, 지표별 기여도, 그날 사용된 지표 수)
    """
    Z = pd.DataFrame({k: expanding_zscore(ind[k]) for k in ind.columns}, index=ind.index)
    contrib = Z * W                       # 지표별 기여도 (부호 포함)
    avail = (Z.notna() & (W != 0))
    denom = (W.abs() * avail).sum(axis=1)
    score = contrib.where(avail).sum(axis=1) / denom.replace(0, np.nan)
    n_used = avail.sum(axis=1)
    score = score.where(n_used >= 3)      # 최소 3개 지표 확보 시에만 신호 생성
    log("COMPOSITE", kv(event="score_built", rows=int(score.notna().sum()),
                        mean=float(score.mean(skipna=True)),
                        std=float(score.std(skipna=True)),
                        min=float(score.min(skipna=True)), max=float(score.max(skipna=True))))
    return score, contrib, n_used


# =============================================================================
# [6] 신호 레이어 : 국면 판정 + 이력현상(hysteresis) + 추세 오버라이드
# =============================================================================
def score_percentile(score: pd.Series, min_obs: int = 252) -> pd.Series:
    """복합점수를 '그때까지의 자기 과거 분포' 대비 백분위로 변환 (expanding rank, causal)."""
    return score.expanding(min_periods=min_obs).rank(pct=True)


def deep_drawdown_flag(close: pd.Series, dd_threshold: float, window: int,
                       mode: str = "peak_to_trough") -> pd.Series:
    """[v1.16.0 §A] 규칙 ⑦용 '최근 window 거래일 안에 dd_threshold 이상의 깊은 낙폭이 있었는가'.

    mode="peak_to_trough" (v1.16.0 기본, 정의 수정): 매일의 낙폭 dd_t = close_t / rolling_max_t − 1
    (그날까지의 window 고점 대비, 인과)을 만든 뒤, 그 dd의 최근 window 거래일 rolling-min이
    dd_threshold 이하인지 본다. 고점이 저점보다 **먼저** 온 진짜 하락(베어마켓)만 잡는다.
    mode="range" (v1.15.0 정의, 06c 참고행 전용): rolling_min / rolling_max − 1 ≤ dd_threshold.
    저점과 고점의 시간 순서를 따지지 않아 "저점 → +25% 랠리 → 고점"도 '-20% 낙폭'으로 오인했다
    (report17 리플레이: 2021-04-08~16, 2024-04-15~23 발동이 실제로는 랠리 뒤의 조정이었고,
    2020-09-24~11-02 22일 중 20일도 같은 오인). 두 정의 모두 과거 창만 사용(룩어헤드 없음)."""
    c = close.astype(float)
    roll_high = c.rolling(window, min_periods=20).max()
    if mode == "range":
        roll_low = c.rolling(window, min_periods=20).min()
        return (roll_low / roll_high - 1.0) <= dd_threshold
    dd = c / roll_high - 1.0
    return dd.rolling(window, min_periods=20).min() <= dd_threshold


def _fast_trigger_coverage_gate(fast_pct: Optional[pd.Series], sig_mask_s: pd.Series,
                                cfg: Config) -> Tuple[float, bool, int]:
    """[v1.21.0 §A(4)] 급락트리거 백분위의 신호구간 커버리지 게이트. (커버리지, 성능저하여부, 신호일수).
    커버리지 < FAST_TRIGGER_MIN_COVERAGE 이면 RuntimeError(ALLOW_DEGRADED_RUN=True면 경고 후 True)."""
    _n_sig = int(sig_mask_s.sum())
    ft_coverage = (float(fast_pct.notna().sum()) / _n_sig) if (fast_pct is not None and _n_sig) else 0.0
    ft_degraded = False
    if cfg.USE_FAST_TRIGGER and _n_sig:
        if ft_coverage < cfg.FAST_TRIGGER_MIN_COVERAGE:
            _msg = (f"[중단/데이터수집] 급락트리거({cfg.FAST_TRIGGER_INDICATOR}) 백분위 커버리지 "
                    f"{ft_coverage:.0%}(신호구간 {_n_sig}일 중 {int(fast_pct.notna().sum()) if fast_pct is not None else 0}일)가 "
                    f"하한 {cfg.FAST_TRIGGER_MIN_COVERAGE:.0%} 미만입니다 — 규칙 ⓪이 사실상 비활성인 리포트는 정상 실행과 "
                    f"비교할 수 없습니다(report22 사례). 다음 단계: 10_데이터품질의 ^VIX/^VIX3M 행 확인 후 재실행, "
                    f"또는 Config.ALLOW_DEGRADED_RUN=True로 명시.")
            if not cfg.ALLOW_DEGRADED_RUN:
                log("SIGNAL", kv(event="fast_trigger_coverage_abort", coverage=round(ft_coverage, 3),
                                 floor=cfg.FAST_TRIGGER_MIN_COVERAGE, signal_days=_n_sig), "error")
                raise RuntimeError(_msg)
            ft_degraded = True
            log("SIGNAL", kv(event="fast_trigger_coverage_degraded", coverage=round(ft_coverage, 3),
                             floor=cfg.FAST_TRIGGER_MIN_COVERAGE, signal_days=_n_sig), "warning")
        else:
            log("SIGNAL", kv(event="fast_trigger_coverage_ok", coverage=round(ft_coverage, 3),
                             floor=cfg.FAST_TRIGGER_MIN_COVERAGE, signal_days=_n_sig))
    return ft_coverage, ft_degraded, _n_sig


def generate_signals(score_pct: pd.Series, trend200: pd.Series, cfg: Config = CFG,
                     score: Optional[pd.Series] = None,
                     haz_pct: Optional[pd.Series] = None,
                     fast_pct: Optional[pd.Series] = None,
                     recov_conf: Optional[pd.Series] = None,
                     deep_recov: Optional[pd.Series] = None,
                     struct_dd: Optional[pd.Series] = None) -> pd.DataFrame:
    """
    t일 종가 기준으로 목표비중을 확정한다(t일 정보만 사용).
    실제 체결은 [7]에서 t+1일 시가로 이뤄진다.

    [v1.3.0 §4(C)/§5] ⚠ 위험(신호) 파라미터 변경. haz_pct(위험/해저드 점수의 자기과거분포
    대비 백분위, run()에서 score_percentile(H)로 산출)가 주어지고 cfg.USE_HAZARD_TRACK=True
    이면 위험 트랙을 결합한다:
      ① 위험 급등(haz_pct>HAZARD_ENTER) 단독으로 위험회피 진입 — 수익점수(느린 매크로
         지표)가 아직 위험선호를 가리켜도 강제 전환(§0에서 확인된 '빠른 조정에 무방비' 대응).
      ② 위험선호 신규진입 중 haz_pct>HAZARD_BLOCK이면 중립까지만 허용(위험선호 오진입 차단).
      ③ 가격이 200일선 위이고 해저드가 정상화(haz_pct<HAZARD_NEUTRAL_FLOOR)됐다면, 그 무엇
         으로도(수익점수·해저드진입·추세오버라이드) RISK_OFF로 묶어두지 않고 최소 중립까지는
         승격한다 — 후행적 매크로 점수가 저점 이후에도 한동안 위험회피를 유지해 방어분을
         반납하는 문제(§5, 실사용 리포트 2023-09~11·2026-03~04 재진입 지연)의 안전판.
      ④ [v1.8.0 §B] cfg.USE_BUY_HOLD_GATE=True이면, 비중을 늘리는(BUY) 정상 확정 전환을
         그 날 haz_pct가 BUY_HOLD_GATE_THRESHOLD를 넘는 동안 보류한다 — ②(HAZARD_BLOCK)가
         RISK_ON 신규진입만 차단하고 RISK_OFF→NEUTRAL 상향은 차단하지 않던 비대칭 구멍을
         막는다. 비중을 줄이는 전환은 절대 보류하지 않는다(안전 비대칭). 이력현상 루프
         내부에서 처리되며 fallback(TREND_ONLY/NO_SIGNAL 강제전환)에는 적용하지 않는다.
      ⓪ [v1.10.0 §A] cfg.USE_FAST_TRIGGER=True이고 fast_pct(급락 트리거 지표의 위험방향
         자기과거분포 백분위, run()에서 산출)가 주어지면, fast_pct>FAST_TRIGGER_PCT인 날
         raw_state를 즉시 RISK_OFF로 강제한다 — 합성 H(느린 지표에 희석)와 무관하게 빠른
         단독 지표(기본 VIX_TERM)의 극단 꼬리만으로 발동하는 ①의 OR 조건. 규칙 ③(안전판)은
         fast-trigger 발동일에는 적용하지 않는다(급성 변동성 급등은 H 레벨이 낮아도 능동적
         위험 — 2020-02-24~28처럼 가격>200MA & H<0.70인 급락 초입에서 안전판이 트리거를
         되돌리는 것을 방지). USE_FAST_TRIGGER=False 또는 fast_pct=None이면 완전 비활성
         (v1.9.0과 비트 단위 동일 — 하위호환).
      ⑤ [v1.11.0 §A] cfg.USE_RECOVERY_FLOOR=True이고 recov_conf(종가가 최근 저점 대비 확인폭
         이상 회복했는지의 불리언, run()에서 산출)가 주어지면, 회복 확인일에 급락트리거·
         haz_enter가 침묵하는 한 RISK_OFF를 최소 중립(0.5)으로 승격한다 — 규칙 ③이 요구하는
         가격>200MA·H<0.70이 위기 직후 회복장에서 구조적으로 불가능한 문제(2020-04, 2023,
         2026 실측)의 해법. 이 승격은 규칙 ④(매수보류게이트) 적용 제외 — 승격 대상일의 74%가
         H>0.70이라 제외 없이는 무력화되며, 가격 확인 + 트리거/ENTER 침묵이 자체 안전장치.
         USE_RECOVERY_FLOOR=False 또는 recov_conf=None이면 완전 비활성(v1.10.0 동일 — 하위호환).
      ⑥ [v1.12.0 §A] cfg.USE_TREND_PROMOTION=True이면, 원시상태 중립 & 가격>200일선 &
         점수백분위>=TREND_PROMOTION_MIN_SCORE_PCT & H<HAZARD_BLOCK & 급락트리거 침묵인 날
         위험선호(1.0)로 승격 — 완만한 강세장에서 매크로 점수 저공비행으로 0.5에 갇히는
         구조적 과소투자(2019/2021/2023/2026 실측)의 해법. False면 v1.11.0 동일(하위호환).
    cfg.USE_HAZARD_TRACK=False 이거나 haz_pct=None이면 이 블록은 완전히 건너뛰어 v1.2.0과
    비트 단위 동일한 신호를 낸다(하위호환·회귀테스트 — §4 수용기준). 이력현상·최소보유일·
    200일선 오버라이드 로직 자체는 변경하지 않는다(§4(C) 명시).
    """
    t0 = time.time()
    if score is None:
        score = score_pct
    raw_state = pd.Series("NEUTRAL", index=score_pct.index, dtype=object)
    raw_state[score_pct > cfg.PCT_RISK_ON] = "RISK_ON"
    raw_state[score_pct < cfg.PCT_RISK_OFF] = "RISK_OFF"
    raw_state[score_pct.isna()] = "NO_SIGNAL"

    # [v1.3.0 §4(C)] 위험(해저드) 트랙 진입/차단 — score_pct가 유효한 날에만 적용한다
    # (NO_SIGNAL 구간은 기존 200일선 폴백(TREND_ONLY_*)이 전담, 여기서 건드리지 않는다).
    haz_enter = pd.Series(False, index=score_pct.index)
    haz_block = pd.Series(False, index=score_pct.index)
    if cfg.USE_HAZARD_TRACK and haz_pct is not None:
        valid = score_pct.notna()
        haz_enter = valid & haz_pct.notna() & (haz_pct > cfg.HAZARD_ENTER)
        haz_block = valid & haz_pct.notna() & (haz_pct > cfg.HAZARD_BLOCK)
        raw_state[haz_enter] = "RISK_OFF"
        raw_state[haz_block & raw_state.eq("RISK_ON")] = "NEUTRAL"

    # [v1.10.0 §A] 규칙 ⓪ 급락 fast-trigger — 빠른 단독 지표(기본 VIX_TERM)의 위험방향
    # expanding 백분위가 극단 꼬리(FAST_TRIGGER_PCT 초과)면 그 날 즉시 위험회피 강제.
    # 합성 H와 독립적으로 동작한다(희석 무관). score_pct 유효일에만 적용(기존 위험트랙 규칙과
    # 동일 관례 — NO_SIGNAL 구간은 추세 폴백 전담).
    fast_fire = pd.Series(False, index=score_pct.index)
    if cfg.USE_FAST_TRIGGER and fast_pct is not None:
        fast_fire = (score_pct.notna() & fast_pct.notna()
                     & (fast_pct > cfg.FAST_TRIGGER_PCT))
        raw_state[fast_fire] = "RISK_OFF"

    # [v1.17.0 §B 보류 메커니즘 — 기본 비활성] 소프트 트리거 캡: 급락트리거 지표의 백분위가
    # SOFT_TRIGGER_PCT(0.93) 초과이지만 규칙 ⓪ 임계(0.97) 미만인 '경계' 구간이면 위험선호를
    # 중립 상한(0.5)으로 강등하고 규칙 ⑥ 승격을 차단한다(ΔH 경보와 같은 '캡' 방식). 규칙 ⑦은
    # 차단하지 않는다 — 차단 변형은 2020-04/05 회복(VIX 기간구조 백분위가 위기 후 한동안 0.93
    # 초과)을 막아 2020년 -4.9pp로 훨씬 나빴다(엔진 내 리플레이). 사용자 요청 "중간 규모 하락
    # 회피"의 후보 4계열(쇼크 브레이크/20일 고점 낙폭 캡/소프트 트리거/변동성 급등) 중 비용이
    # 가장 작은 것이지만 그래도 CAGR -0.2pp·손실일 감소 0 — 기각. 실데이터 확인용으로 06c
    # 보류메커니즘 격자에서만 매 실행 실측한다(두 데이터셋 리플레이 결과는 Config 주석 참조).
    soft_fire = pd.Series(False, index=score_pct.index)
    if cfg.USE_SOFT_TRIGGER_CAP and cfg.USE_FAST_TRIGGER and fast_pct is not None:
        soft_fire = (score_pct.notna() & fast_pct.notna()
                     & (fast_pct > cfg.SOFT_TRIGGER_PCT) & ~fast_fire)
        raw_state[soft_fire & raw_state.eq("RISK_ON")] = "NEUTRAL"

    # [v1.13.0 §C] H 속도(ΔH) 조기경보(A-2) — 과거 H만 사용(shift, 인과). 발동 시 위험선호를
    # 중립 상한으로 강등(레벨 무관)하고 아래 규칙 ⑥ 승격도 차단한다. 기본 비활성.
    haz_vel = pd.Series(False, index=score_pct.index)
    if cfg.USE_HAZARD_VELOCITY and cfg.USE_HAZARD_TRACK and haz_pct is not None:
        _dh = haz_pct - haz_pct.shift(cfg.HAZARD_VELOCITY_WINDOW)
        haz_vel = (score_pct.notna() & _dh.notna() & (_dh > cfg.HAZARD_VELOCITY_DELTA))
        raw_state[haz_vel & raw_state.eq("RISK_ON")] = "NEUTRAL"

    # 추세 오버라이드: 200일선 하회 + 복합점수 음수 -> 강제 위험회피
    override = pd.Series(False, index=score_pct.index)
    if cfg.USE_TREND_OVERRIDE:
        override = (trend200 < 0) & (score_pct < 0.5) & score_pct.notna()
        raw_state[override] = "RISK_OFF"

    # [v1.3.0 §5] 위험회피 해제 안전판 — 위 세 경로(수익점수·해저드진입·추세오버라이드) 중
    # 무엇으로 RISK_OFF가 됐든, 가격이 200일선을 회복했고 해저드도 정상화됐다면 최소
    # 중립까지 승격한다. trend200>0 조건 때문에 추세오버라이드(trend200<0 필요)와는 절대
    # 동시에 성립하지 않는다 — 2022년형(가격이 200일선 아래 대부분) 완만한 베어마켓에서는
    # 이 안전판이 사실상 발동하지 않아 방어력을 훼손하지 않는다(§5 수용기준 근거).
    # [v1.10.0 §A] fast-trigger 발동일(~fast_fire)은 안전판 대상에서 제외 — 급성 변동성
    # 급등은 합성 H 레벨이 낮아도 능동적 위험이며, 제외하지 않으면 급락 초입(가격>200MA,
    # H<0.70)에서 안전판이 트리거를 NEUTRAL로 되돌려 무력화한다(2020-02-24~28 실측 사례).
    haz_floor = pd.Series(False, index=score_pct.index)
    if cfg.USE_HAZARD_TRACK and haz_pct is not None:
        haz_floor = ((trend200 > 0) & haz_pct.notna() & (haz_pct < cfg.HAZARD_NEUTRAL_FLOOR)
                     & raw_state.eq("RISK_OFF") & ~fast_fire)
        raw_state[haz_floor] = "NEUTRAL"

    # [v1.11.0 §A] 규칙 ⑤ 회복 승격 — 종가가 최근 저점 대비 확인폭 이상 회복했고(recov_conf)
    # 그 날 급락트리거·haz_enter가 침묵하면, 점수·추세오버라이드·H레벨과 무관하게 RISK_OFF를
    # 최소 중립으로 승격한다. 규칙 ③과 달리 가격>200MA를 요구하지 않아(2020-03~05처럼 200MA
    # 아래의 V반등 초입에서 동작) 위기 직후 회복장의 구조적 재진입 봉쇄를 푼다.
    recovery_floor = pd.Series(False, index=score_pct.index)
    if cfg.USE_RECOVERY_FLOOR and recov_conf is not None:
        recovery_floor = (score_pct.notna() & recov_conf.fillna(False).astype(bool)
                          & ~fast_fire & ~haz_enter & raw_state.eq("RISK_OFF"))
        raw_state[recovery_floor] = "NEUTRAL"

    # [v1.12.0 §A] 규칙 ⑥ 추세 승격 — 원시상태 중립 & 가격>200일선 & 점수백분위>=하한(0.30,
    # 위험회피 경계+버퍼) & H<BLOCK(능동적 위험 아님) & 급락트리거 침묵이면 위험선호(1.0)로
    # 승격한다. 매크로 점수가 강세장 계량기로는 구조적으로 보수적이라는 4개 리포트 연속
    # 실측(2019/2021/2023/2026 저공비행)의 해법 — "매크로가 명확히 반대하지 않고 추세·위험
    # 지표가 허락하면 풀포지션". H<0.70 조건 덕에 승격일은 매수보류게이트(임계 0.70)에
    # 구조적으로 걸리지 않는다. 위험트랙이 없으면(haz_pct=None) H 조건을 확인할 수 없어
    # 규칙 전체를 비활성(보수적 하위호환).
    trend_promo = pd.Series(False, index=score_pct.index)
    if cfg.USE_TREND_PROMOTION and cfg.USE_HAZARD_TRACK and haz_pct is not None:
        # [v1.13.0 §B] H 상한을 BLOCK(0.70) 고정에서 TREND_PROMOTION_MAX_H(기본 0.85=ENTER
        # 통일)로 분리 — 위기 직후 금리편중 H가 0.7+에 머물며 강세장 승격을 봉쇄하던 2023년형
        # 문제의 해법(상세 근거는 Config §B 주석). 주의: 상한이 게이트 임계(0.70)를 넘으므로
        # H 0.70~0.85 구간의 승격 상향이 매수보류게이트에 걸릴 수 있는데, 이는 의도된 이중
        # 확인이 아니라 게이트의 원래 목적(위험 '상승 중' 매수 차단)과 충돌한다 — 규칙 ⑤와
        # 동일하게 게이트 적용에서 제외한다(추세 위 + 점수 무반대 + ENTER 미만이 자체 안전장치).
        trend_promo = (score_pct.notna() & (trend200 > 0)
                       & (score_pct >= cfg.TREND_PROMOTION_MIN_SCORE_PCT)
                       & haz_pct.notna() & (haz_pct < cfg.TREND_PROMOTION_MAX_H)
                       & ~fast_fire & ~haz_vel & ~soft_fire & raw_state.eq("NEUTRAL"))
        raw_state[trend_promo] = "RISK_ON"

    # [v1.15.0 §A] 규칙 ⑦ 깊은 낙폭 회복 풀매수 — 회복 확인(deep_recov: 회복확인 AND 최근
    # 120일 저점이 같은 창 고점 대비 -20% 이상 깊음 = 베어마켓급 낙폭) 상태의 중립일을
    # 위험선호(1.0)로 승격한다. 규칙 ⑥이 커버하지 못하는 영역(가격<200MA·점수 저공·H 고공의
    # 위기 직후 V반등 — 2020-04형)의 풀포지션 진입로. 급락트리거·haz_enter·ΔH경보 발동일
    # 제외(안전장치). 승격 상향은 규칙 ⑤와 동일하게 매수보류게이트 적용 제외(dr_vals).
    # [v1.16.0 §B 점수 가드] DEEP_RECOVERY_SCORE_GUARD=True면 복합점수 백분위가 위험회피 밴드
    # (< PCT_RISK_OFF) 안에 있는 날은 승격하지 않는다. 근거: report17 리플레이에서 유일한 손실
    # 발동 구간(2022-08-09~17, 21일 후 -8.0%)은 점수백분위 0.039(하위 4%)·H 0.84였고, 그 중립
    # 상태는 규칙 ⑤가 위험회피를 끌어올린 것이었다 — 규칙 ⑤의 승격 위에 규칙 ⑦이 다시 얹히는
    # '이중 승격'을 막는다. 임계값은 기존 PCT_RISK_OFF를 그대로 재사용(신규 수치 없음).
    deep_boost = pd.Series(False, index=score_pct.index)
    if cfg.USE_DEEP_RECOVERY_BOOST and deep_recov is not None:
        deep_boost = (score_pct.notna() & deep_recov.fillna(False).astype(bool)
                      & ~fast_fire & ~haz_enter & ~haz_vel & raw_state.eq("NEUTRAL"))
        if cfg.DEEP_RECOVERY_SCORE_GUARD:
            deep_boost = deep_boost & (score_pct >= cfg.PCT_RISK_OFF)
        raw_state[deep_boost] = "RISK_ON"

    # [v1.18.0 §A] 규칙 ⑧ 구조적 저점 확인 승격 — 최근 RECOVERY_LOW_WINDOW 안에 STRUCT_BOTTOM_DD
    # (-8%, 고점→저점 순서 보장) 이상의 조정이 있었고(struct_dd), 종가가 저점 대비 회복 확인
    # (recov_conf, +5%)됐으며, **가격이 200일선을 되찾았고**(trend200>0 — 베어마켓 랠리가 고전적으로
    # 실패하는 선), H가 STRUCT_BOTTOM_MAX_H(0.70=BLOCK, 능동 위험 아님) 미만이고, 트리거·H급등·ΔH·
    # 소프트캡이 침묵하면 중립을 위험선호(1.0)로 승격한다. 규칙 ⑥과 달리 복합점수 하한(0.30)을
    # 요구하지 않는다 — 조정 뒤 회복장에서 매크로 점수가 하위 20%대에 머물러 규칙 ⑥이 침묵한
    # 2026-04(+20% 반등을 0.5로 통과) 사례의 해법. 규칙 ⑦(-15%)과의 관계: ⑦은 200MA 아래 V반등
    # (2020-04·2025-04)을, ⑧은 200MA 위로 복귀한 조정 회복을 맡는다. 데드캣 방어: 21개 반등
    # 이벤트 전수에서 200MA 되찾기+H<0.70 조건을 통과한 데드캣은 2022-02-02 하나뿐(IMPROVEMENT_
    # PLAN_v1.18.md §B). 게이트 적용 제외(sb_vals — ⑤·⑥·⑦과 동일 근거).
    struct_boost = pd.Series(False, index=score_pct.index)
    if (cfg.USE_STRUCT_BOTTOM_PROMOTION and cfg.USE_HAZARD_TRACK and haz_pct is not None
            and recov_conf is not None and struct_dd is not None):
        struct_boost = (score_pct.notna() & recov_conf.fillna(False).astype(bool)
                        & struct_dd.fillna(False).astype(bool) & (trend200 > 0)
                        & haz_pct.notna() & (haz_pct < cfg.STRUCT_BOTTOM_MAX_H)
                        & ~fast_fire & ~haz_enter & ~haz_vel & ~soft_fire & raw_state.eq("NEUTRAL"))
        raw_state[struct_boost] = "RISK_ON"

    # [v1.0.3] 채택지표가 부족해 복합점수가 없는 구간은 '현금'이 아니라
    # 가장 단순하고 오래 검증된 200일선 추세필터로 폴백한다.
    # (지표 부족은 '하락 신호'가 아니므로 무조건 현금화하면 장기 상승분을 통째로 놓친다)
    raw_state[raw_state.eq("NO_SIGNAL") & (trend200 > 0)] = "TREND_ONLY_IN"
    raw_state[raw_state.eq("NO_SIGNAL") & (trend200 <= 0)] = "TREND_ONLY_OUT"

    pos_map = {"RISK_ON": cfg.POS_RISK_ON, "NEUTRAL": cfg.POS_NEUTRAL,
               "RISK_OFF": cfg.POS_RISK_OFF,
               "TREND_ONLY_IN": 1.0, "TREND_ONLY_OUT": 0.0, "NO_SIGNAL": 0.0}

    # 이력현상 + 최소보유일 (휩쏘 억제). 순차 루프지만 O(n), 하루 1회 연산이라 비용 미미.
    # [v1.0.1 버그수정] streak 은 '동일한 raw_state 가 연속된 일수' 여야 한다.
    #   기존 코드는 확정상태(cur)와 비교해 매일 1로 초기화되어 전환이 사실상 봉쇄되었다.
    states = raw_state.values
    # [v1.8.0 §B] 매수(비중증가) 보류 게이트용 H백분위 배열 — score_pct와 haz_pct는 run()에서
    # 동일 인덱스(cal)로 산출돼(§4536) 위치기반 접근이 안전하다(기존 haz_enter/haz_block/
    # haz_floor 벡터화 연산과 동일 전제). 게이트가 꺼져 있거나(USE_BUY_HOLD_GATE=False) 위험
    # 트랙 자체가 없으면(haz_pct=None) None으로 두어 루프에서 완전히 건너뛴다(하위호환).
    haz_vals = (haz_pct.values
                if (cfg.USE_HAZARD_TRACK and cfg.USE_BUY_HOLD_GATE and haz_pct is not None)
                else None)
    rec_vals = recovery_floor.values   # [v1.11.0 §A] 규칙 ⑤ 발동일(게이트 제외 판정용)
    tp_vals = trend_promo.values       # [v1.13.0 §B] 규칙 ⑥ 발동일(게이트 제외 판정용)
    dr_vals = deep_boost.values        # [v1.15.0 §A] 규칙 ⑦ 발동일(게이트 제외 판정용)
    sb_vals = struct_boost.values      # [v1.18.0 §A] 규칙 ⑧ 발동일(게이트 제외 판정용)
    conf_state, conf_pos = [], []
    buy_hold_gate = []   # [v1.8.0 §B] 이 날 비중증가 전환이 게이트에 의해 보류됐는지(감사/추적성)
    cur = "NO_SIGNAL"
    prev_raw = None
    streak, held = 0, 0
    dir_streak, dir_sign, dir_states = 0, 0, []   # [v1.19.0 §B] 같은 방향 연속일수·방향·본 상태들
    for i, s in enumerate(states):
        streak = streak + 1 if s == prev_raw else 1
        prev_raw = s
        held += 1
        gated = False
        # [v1.19.0 §B] 교대-잠금 수정: cur 대비 같은 방향(위/아래)의 raw 가 연속되면 상태가 달라도
        # 방향 연속일수를 누적한다. TREND_ONLY/NO_SIGNAL(폴백 경로)은 종전 로직 그대로.
        if cfg.USE_ALTERNATION_FIX and s in pos_map and cur in pos_map:
            sgn = int(np.sign(pos_map[s] - pos_map[cur]))
            if sgn != 0 and sgn == dir_sign:
                dir_streak += 1; dir_states.append(s)
            elif sgn != 0:
                dir_streak, dir_sign, dir_states = 1, sgn, [s]
            else:
                dir_streak, dir_sign, dir_states = 0, 0, []
        if s != cur:
            fallback = ("TREND_ONLY" in str(cur)) or ("TREND_ONLY" in str(s)) \
                       or cur == "NO_SIGNAL" or s == "NO_SIGNAL"
            # [v1.13.0 §A] 비대칭 히스테리시스 — 위험을 줄이는 전환(목표비중 감소)은 확인일수
            # HYSTERESIS_DAYS_DOWN(기본 1일)로 단축하고 최소보유일 적용을 면제(MIN_HOLD_EXEMPT_
            # DOWN=True 시)한다. 위험을 늘리는 전환은 기존 확인일수·최소보유일 그대로("손실
            # 회피는 빠르게, 진입은 신중하게"). USE_ASYM_HYSTERESIS=False면 기존 대칭 로직과
            # 비트 단위 동일(하위호환).
            is_down = pos_map.get(s, 0.0) < pos_map.get(cur, 0.0)
            if cfg.USE_ASYM_HYSTERESIS and is_down:
                req_streak = cfg.HYSTERESIS_DAYS_DOWN
                req_hold = 0 if cfg.MIN_HOLD_EXEMPT_DOWN else cfg.MIN_HOLD_DAYS
            else:
                req_streak, req_hold = cfg.HYSTERESIS_DAYS, cfg.MIN_HOLD_DAYS
            can_switch = (streak >= req_streak and held >= req_hold) or fallback
            # [v1.19.0 §B] 교대 상황(동일 raw 연속은 부족하지만 같은 방향 연속은 충분)이면 보수적인
            # 한 단계로 전환 대상을 바꾼다: 상향은 본 상태들 중 비중이 낮은 쪽, 하향은 높은 쪽.
            if (cfg.USE_ALTERNATION_FIX and not can_switch and not fallback and dir_sign != 0
                    and dir_streak >= req_streak and held >= req_hold and len(set(dir_states)) > 1):
                s = (min(dir_states, key=lambda x: pos_map[x]) if dir_sign > 0
                     else max(dir_states, key=lambda x: pos_map[x]))
                can_switch = True
            # [v1.8.0 §B] 정상 확정 경로(fallback 아님)에서 비중을 늘리는 전환만 재확인한다.
            # 비중을 줄이는 전환(REDUCE/SELL)은 절대 보류하지 않는다(안전 비대칭). fallback
            # (TREND_ONLY/NO_SIGNAL 강제전환)은 이미 이력현상 자체를 면제하는 별도 경로라
            # 이번 게이트의 범위 밖으로 둔다(§C-3, 워밍업 아티팩트와 성격이 다름).
            # [v1.11.0 §A] 규칙 ⑤(회복 승격)로 만들어진 상향은 게이트 적용 제외(rec_vals[i]) —
            # 실측상 승격 대상일의 74%(166/225)가 H>0.70이라 제외 없이는 규칙이 무력화되고,
            # 가격 확인(+5%)·트리거/ENTER 침묵이 게이트의 역할을 대신한다(Config §A 주석 참조).
            # [v1.13.0 §B] 규칙 ⑥(추세 승격) 상향도 동일하게 제외(tp_vals[i]) — H 상한이
            # ENTER(0.85)로 완화되면서 0.70~0.85 구간 승격이 게이트와 충돌하게 된 것의 정리.
            if can_switch and not fallback and haz_vals is not None \
                    and not rec_vals[i] and not tp_vals[i] and not dr_vals[i] and not sb_vals[i]:
                is_buy = pos_map.get(s, 0.0) > pos_map.get(cur, 0.0)
                if is_buy:
                    h = haz_vals[i]
                    if pd.notna(h) and h > cfg.BUY_HOLD_GATE_THRESHOLD:
                        can_switch = False
                        gated = True
            if can_switch:
                cur = s
                held = 0
                dir_streak, dir_sign, dir_states = 0, 0, []   # [v1.19.0 §B] 전환 후 방향 누적 리셋
        conf_state.append(cur)
        conf_pos.append(pos_map[cur])
        buy_hold_gate.append(gated)

    out = pd.DataFrame({
        "raw_state": raw_state,
        "state": pd.Series(conf_state, index=score_pct.index),
        "target_pos": pd.Series(conf_pos, index=score_pct.index, dtype=float),
        "trend_override": override,
        "hazard_entry": haz_enter,     # [v1.3.0 §4(C)] 위험급등 단독 위험회피 진입 발동일
        "hazard_block": haz_block,     # [v1.3.0 §4(C)] 위험선호 신규진입 차단 조건 성립일
        "hazard_floor": haz_floor,     # [v1.3.0 §5] 위험회피 해제 안전판(최소중립 승격) 발동일
        # [v1.8.0 §B] 집행일 매수 보류 게이트 발동일(비중증가 전환이 H임계값 초과로 보류된 날)
        "buy_hold_gate": pd.Series(buy_hold_gate, index=score_pct.index),
        "fast_trigger": fast_fire,     # [v1.10.0 §A] 급락 fast-trigger(규칙 ⓪) 발동일
        "recovery_floor": recovery_floor,  # [v1.11.0 §A] 회복 승격(규칙 ⑤) 발동일
        "trend_promotion": trend_promo,    # [v1.12.0 §A] 추세 승격(규칙 ⑥) 발동일
        "hazard_velocity": haz_vel,        # [v1.13.0 §C] ΔH 속도 경보 발동일(v1.14.0부터 활성)
        "deep_recovery": deep_boost,       # [v1.15.0 §A] 깊은 낙폭 회복 풀매수(규칙 ⑦) 발동일
        "soft_trigger": soft_fire,         # [v1.17.0 §B] 소프트 트리거 캡 발동일(기본 비활성 — 보류)
        "struct_bottom": struct_boost,     # [v1.18.0 §A] 구조적 저점 확인 승격(규칙 ⑧) 발동일
    })
    out["target_pos"] = out["target_pos"].fillna(0.0)

    # [v1.19.0 §A] 규칙 ⑨ 중립 위험감축 — 확정 상태 중립(0.5) & 그날 H > NEUTRAL_RISK_CUT_H 이면
    # 목표비중을 POS_NEUTRAL_HIGH_H(기본 0.0)로. 상태기계·이력현상은 건드리지 않는 사이징
    # 오버레이(사용자 지시 "위험이 높을수록 비중은 작게 — 하락기엔 현금 또는 0.5 미만"). 근거는
    # Config/CHANGELOG v1.19.0(두 데이터셋 2018+ 리플레이: CAGR 무손상, 샤프↑, MDD↓, 2022 -7.4→
    # -3.6%, 손실일 -4; 비용 2020 -4.5pp·2023 -1.5~2pp).
    neutral_cut = pd.Series(False, index=score_pct.index)
    if cfg.USE_NEUTRAL_RISK_CUT and cfg.USE_HAZARD_TRACK and haz_pct is not None:
        neutral_cut = (out["state"].eq("NEUTRAL") & haz_pct.notna()
                       & (haz_pct > cfg.NEUTRAL_RISK_CUT_H))
        out.loc[neutral_cut, "target_pos"] = np.minimum(out.loc[neutral_cut, "target_pos"],
                                                          cfg.POS_NEUTRAL_HIGH_H)
    out["neutral_risk_cut"] = neutral_cut

    # [v1.20.0 §C] 규칙 ⑩ 과열 헤어컷 — 확정 RISK_ON & 200일선 이격도(EXTENSION_HAIRCUT_SMOOTH일 평균)가
    # EXTENSION_HAIRCUT_STEPS 임계 이상이면 목표비중 상한을 0.1 단위로 낮춘다(≥+10% → 0.8, ≥+12% → 0.6).
    # 규칙 ⑨와 같은 '확정 후 사이징 오버레이' 층: 상태기계·이력현상·게이트는 건드리지 않는다. 인과:
    # trend200은 t일 종가/200일선(t)이며 이동평균도 t까지의 창(min_periods=창 → 워밍업 구간은 상한 없음).
    # 근거·실증 수치는 Config/CHANGELOG v1.20.0 참조. ext_cap 은 감사용(1.0 = 미적용).
    ext_cap = pd.Series(1.0, index=score_pct.index)
    if cfg.USE_EXTENSION_HAIRCUT and cfg.EXTENSION_HAIRCUT_STEPS:
        w = int(max(1, cfg.EXTENSION_HAIRCUT_SMOOTH))
        ext_s = trend200.rolling(w, min_periods=w).mean() if w > 1 else trend200
        for thr, cap in sorted(cfg.EXTENSION_HAIRCUT_STEPS, key=lambda x: x[0]):
            ext_cap[ext_s.notna() & (ext_s >= thr)] = float(cap)
    ext_hit = out["state"].eq("RISK_ON") & (ext_cap < out["target_pos"] - 1e-12)
    out.loc[ext_hit, "target_pos"] = ext_cap[ext_hit]
    out["extension_haircut"] = ext_hit
    out["ext_cap"] = ext_cap

    # [v1.21.0 §C] 규칙 ⑪ 레버리지 사다리 — 기본 비활성(⚠ 위험 파라미터). 켜면 확정 RISK_ON & 목표 1.0(헤어컷
    # 미적용)인 날에 한해 (a) 급락 후 회복 진입(가격<200MA, 규칙 ⑦ 경로) → LEVERAGE_RECOVERY_POS,
    # (b) 저위험(이격도 평균 ≤ LOW_RISK_EXT & H ≤ LOW_RISK_H) → LEVERAGE_LOW_RISK_POS. LEVERAGE_MAX로 절대 상한.
    # 인과: 그날 종가 이격도·H. 근거·비용은 Config 주석/CHANGELOG v1.21.0 §C.
    lev_hit = pd.Series(False, index=score_pct.index)
    if cfg.USE_LEVERAGE:
        w = int(max(1, cfg.EXTENSION_HAIRCUT_SMOOTH))
        ext_s2 = trend200.rolling(w, min_periods=w).mean() if w > 1 else trend200
        full_on = out["state"].eq("RISK_ON") & (out["target_pos"] >= cfg.POS_RISK_ON - 1e-12)
        recov_entry = full_on & (trend200 < 0)
        low_risk = (full_on & ext_s2.notna() & (ext_s2 <= cfg.LEVERAGE_LOW_RISK_EXT)
                    & (haz_pct.notna() & (haz_pct <= cfg.LEVERAGE_LOW_RISK_H) if haz_pct is not None else False))
        lev_pos = pd.Series(np.nan, index=score_pct.index)
        lev_pos[low_risk] = min(cfg.LEVERAGE_LOW_RISK_POS, cfg.LEVERAGE_MAX)
        lev_pos[recov_entry] = min(cfg.LEVERAGE_RECOVERY_POS, cfg.LEVERAGE_MAX)
        lev_hit = lev_pos.notna() & (lev_pos > out["target_pos"] + 1e-12)
        out.loc[lev_hit, "target_pos"] = lev_pos[lev_hit]
    out["leverage"] = lev_hit

    n_sw = int((out["state"] != out["state"].shift()).sum())
    dist = out["state"].value_counts().to_dict()
    log("SIGNAL", kv(event="generated", switches=n_sw,
                     risk_on=dist.get("RISK_ON", 0), neutral=dist.get("NEUTRAL", 0),
                     risk_off=dist.get("RISK_OFF", 0),
                     trend_fallback=dist.get("TREND_ONLY_IN", 0) + dist.get("TREND_ONLY_OUT", 0),
                     no_signal=dist.get("NO_SIGNAL", 0),
                     overrides=int(override.sum()),
                     # [v1.4.0 §4.2 ⚠ 신호(위험) 파라미터] 이번 실행에 실제 적용된 국면
                     # 전환 임계값을 매 실행 로그에 남겨, PCT_RISK_ON 변경(0.50->0.60)의
                     # 효과를 이후 리포트에서 실행별로 추적할 수 있게 한다.
                     pct_risk_on=cfg.PCT_RISK_ON, pct_risk_off=cfg.PCT_RISK_OFF,
                     use_hazard_track=cfg.USE_HAZARD_TRACK,
                     hazard_entries=int(haz_enter.sum()), hazard_blocks=int(haz_block.sum()),
                     hazard_floors=int(haz_floor.sum()),
                     # [v1.8.0 §B ⚠ 신호(위험) 파라미터] 매수보류게이트 실제 적용 여부·임계값·
                     # 이번 실행 발동일수를 매 실행 로그에 남긴다(§4.2와 동일 추적성 원칙).
                     use_buy_hold_gate=cfg.USE_BUY_HOLD_GATE,
                     buy_hold_gate_threshold=cfg.BUY_HOLD_GATE_THRESHOLD,
                     buy_hold_gates=int(sum(buy_hold_gate)),
                     # [v1.10.0 §A ⚠ 신호(위험) 파라미터] fast-trigger 적용 여부·지표·임계값·
                     # 발동일수를 매 실행 로그에 남긴다(추적성 원칙).
                     use_fast_trigger=cfg.USE_FAST_TRIGGER,
                     fast_trigger_indicator=cfg.FAST_TRIGGER_INDICATOR,
                     fast_trigger_pct=cfg.FAST_TRIGGER_PCT,
                     fast_triggers=int(fast_fire.sum()),
                     # [v1.17.0 §B 보류] 소프트 트리거 캡 적용 여부·임계·발동일수.
                     use_soft_trigger_cap=cfg.USE_SOFT_TRIGGER_CAP,
                     soft_trigger_pct=cfg.SOFT_TRIGGER_PCT,
                     soft_triggers=int(soft_fire.sum()),
                     # [v1.11.0 §A ⚠ 신호(위험) 파라미터] 회복 승격 규칙 적용 여부·파라미터·
                     # 발동일수(추적성 원칙).
                     use_recovery_floor=cfg.USE_RECOVERY_FLOOR,
                     recovery_low_window=cfg.RECOVERY_LOW_WINDOW,
                     recovery_confirm_pct=cfg.RECOVERY_CONFIRM_PCT,
                     recovery_floors=int(recovery_floor.sum()),
                     # [v1.12.0 §A ⚠ 신호(위험) 파라미터] 추세 승격 규칙 적용 여부·하한·발동일수.
                     use_trend_promotion=cfg.USE_TREND_PROMOTION,
                     trend_promotion_min_score_pct=cfg.TREND_PROMOTION_MIN_SCORE_PCT,
                     trend_promotions=int(trend_promo.sum()),
                     # [v1.13.0] 보류 메커니즘 상태(기본 비활성 — 켜지면 여기서 즉시 확인 가능).
                     use_asym_hysteresis=cfg.USE_ASYM_HYSTERESIS,
                     trend_promotion_max_h=cfg.TREND_PROMOTION_MAX_H,
                     use_hazard_velocity=cfg.USE_HAZARD_VELOCITY,
                     hazard_velocities=int(haz_vel.sum()),
                     # [v1.15.0 §A ⚠ 신호(위험) 파라미터] 깊은 낙폭 회복 풀매수 상태·발동일수.
                     use_deep_recovery_boost=cfg.USE_DEEP_RECOVERY_BOOST,
                     deep_recovery_dd=cfg.DEEP_RECOVERY_DD,
                     deep_recovery_dd_mode=cfg.DEEP_RECOVERY_DD_MODE,        # [v1.16.0 §A]
                     deep_recovery_score_guard=cfg.DEEP_RECOVERY_SCORE_GUARD,  # [v1.16.0 §B]
                     deep_recoveries=int(deep_boost.sum()),
                     # [v1.18.0 §A ⚠ 신호(위험) 파라미터] 규칙 ⑧ 적용 여부·파라미터·발동일수.
                     use_struct_bottom_promotion=cfg.USE_STRUCT_BOTTOM_PROMOTION,
                     struct_bottom_dd=cfg.STRUCT_BOTTOM_DD,
                     struct_bottom_max_h=cfg.STRUCT_BOTTOM_MAX_H,
                     struct_bottoms=int(struct_boost.sum()),
                     # [v1.19.0 §A/§B ⚠ 신호(위험) 파라미터] 규칙 ⑨·교대 수정 적용 여부·발동일수.
                     use_neutral_risk_cut=cfg.USE_NEUTRAL_RISK_CUT,
                     neutral_risk_cut_h=cfg.NEUTRAL_RISK_CUT_H,
                     pos_neutral_high_h=cfg.POS_NEUTRAL_HIGH_H,
                     neutral_risk_cuts=int(neutral_cut.sum()),
                     use_alternation_fix=cfg.USE_ALTERNATION_FIX,
                     # [v1.20.0 §C ⚠ 신호(사이징) 파라미터] 규칙 ⑩ 적용 여부·단계·평활·발동일수·상한 분포.
                     use_extension_haircut=cfg.USE_EXTENSION_HAIRCUT,
                     extension_haircut_steps=str(cfg.EXTENSION_HAIRCUT_STEPS).replace(" ", ""),
                     extension_haircut_smooth=cfg.EXTENSION_HAIRCUT_SMOOTH,
                     extension_haircuts=int(ext_hit.sum()),
                     ext_cap_dist=str({float(k): int(v) for k, v in
                                       ext_cap[ext_hit].value_counts().sort_index().items()}).replace(" ", ""),
                     # [v1.21.0 §C ⚠ 위험 파라미터] 규칙 ⑪ 레버리지 적용 여부·발동일수·최대 목표비중.
                     use_leverage=cfg.USE_LEVERAGE, leverage_days=int(lev_hit.sum()),
                     max_target_pos=float(out["target_pos"].max()),
                     elapsed_s=round(time.time() - t0, 3)))
    return out


def action_labels(pos: pd.Series) -> pd.Series:
    """포지션 변화 -> 사람이 읽는 매매행동 라벨."""
    d = pos.diff()
    lab = pd.Series("HOLD", index=pos.index, dtype=object)
    prev = pos.shift()
    lab[(d > 0) & (prev <= 0)] = "BUY"        # 신규 진입
    lab[(d > 0) & (prev > 0)] = "ADD"         # 비중 확대
    lab[(d < 0) & (pos > 0)] = "REDUCE"       # 비중 축소
    lab[(d < 0) & (pos <= 0)] = "SELL"        # 전량 청산
    lab[pos.isna()] = "-"
    lab.iloc[0] = "START"
    return lab


# =============================================================================
# [7] 백테스트 레이어
#     체결 규칙: t일 종가에 확정된 target_pos 를 t+1일 '시가'에 체결.
#     t+1일 수익률 = 이전비중 × (시가/전일종가 - 1) + 신규비중 × (종가/시가 - 1)
#     -> 룩어헤드가 구조적으로 불가능하며 실전 체결과 동일한 분해.
# =============================================================================
def run_backtest(price: pd.DataFrame, target_pos: pd.Series, cfg: Config = CFG,
                 rf_daily: Optional[pd.Series] = None) -> pd.DataFrame:
    t0 = time.time()
    df = pd.DataFrame(index=price.index)
    df["Open"] = price["Open"]
    df["Close"] = price["Close"]
    adj_col = "Adj Close" if "Adj Close" in price.columns else "Close"
    df["AdjClose"] = price[adj_col]
    # 배당 포함 총수익 계수 (Adj Close 기반)를 원시 OHLC 분해에 반영
    df["ret_cc"] = df["AdjClose"].pct_change()                       # 종가->종가 총수익
    div_factor = (1.0 + df["ret_cc"]) / (df["Close"] / df["Close"].shift(1))
    df["ret_co"] = (df["Open"] / df["Close"].shift(1) - 1.0)          # 전일종가->당일시가
    df["ret_oc"] = (1.0 + df["ret_cc"]) / (1.0 + df["ret_co"]) - 1.0  # 당일시가->당일종가(총수익 정합)

    df["pos_target"] = target_pos.reindex(df.index)
    df["pos_exec"] = df["pos_target"].shift(1)          # t일 신호 -> t+1일 시가 체결
    df["pos_prev"] = df["pos_exec"].shift(1).fillna(0.0)
    df["pos_exec"] = df["pos_exec"].fillna(0.0)

    turn = (df["pos_exec"] - df["pos_prev"]).abs()
    cost = turn * (cfg.COST_BPS / 1e4)
    rf = rf_daily.reindex(df.index).fillna(0.0) if rf_daily is not None else 0.0

    gross = df["pos_prev"] * df["ret_co"] + df["pos_exec"] * df["ret_oc"]
    cash_leg = (1.0 - df["pos_exec"]) * rf                            # 미투자분 단기금리 수취(pos>1 이면 단기금리 차입)
    # [v1.21.0 §C] 초과노출(pos>1)에는 단기금리 위에 LEVERAGE_SPREAD_BPS 스프레드를 추가로 부과(레버리지 ETF/마진 비용 근사).
    lev_cost = np.maximum(df["pos_exec"] - 1.0, 0.0) * (cfg.LEVERAGE_SPREAD_BPS / 1e4 / 252.0)
    df["strategy_ret"] = (gross + cash_leg - cost - lev_cost).fillna(0.0)
    df["cost"] = cost
    df["turnover"] = turn
    df["bh_ret"] = df["ret_cc"].fillna(0.0)
    df["equity"] = (1.0 + df["strategy_ret"]).cumprod()
    df["bh_equity"] = (1.0 + df["bh_ret"]).cumprod()
    df["dd"] = df["equity"] / df["equity"].cummax() - 1.0
    df["bh_dd"] = df["bh_equity"] / df["bh_equity"].cummax() - 1.0

    log("EXEC", kv(event="backtest_done", days=len(df),
                   trades=int((turn > 1e-9).sum()),
                   total_cost=float(cost.sum()),
                   final_equity=float(df["equity"].iloc[-1]),
                   bh_equity=float(df["bh_equity"].iloc[-1]),
                   elapsed_s=round(time.time() - t0, 3)))
    return df


def perf_metrics(ret: pd.Series, label: str = "") -> Dict[str, float]:
    r = ret.dropna()
    if len(r) < 20:
        return {}
    ann = 252.0
    eq = (1 + r).cumprod()
    yrs = len(r) / ann
    cagr = eq.iloc[-1] ** (1 / yrs) - 1 if yrs > 0 else np.nan
    vol = r.std() * math.sqrt(ann)
    sharpe = (r.mean() * ann) / vol if vol > 0 else np.nan
    dn = r[r < 0].std() * math.sqrt(ann)
    sortino = (r.mean() * ann) / dn if dn and dn > 0 else np.nan
    mdd = float((eq / eq.cummax() - 1).min())
    return {
        "전략": label,
        "총수익배수": round(float(eq.iloc[-1]), 3),
        "CAGR": round(float(cagr), 4),
        "연변동성": round(float(vol), 4),
        "샤프": round(float(sharpe), 3),
        "소르티노": round(float(sortino), 3) if pd.notna(sortino) else np.nan,
        "최대낙폭(MDD)": round(mdd, 4),
        "칼마(CAGR/MDD)": round(float(cagr / abs(mdd)), 3) if mdd else np.nan,
        "일간승률": round(float((r > 0).mean()), 4),
        "최악일": round(float(r.min()), 4),
        "최고일": round(float(r.max()), 4),
    }


def threshold_sensitivity(score_pct: pd.Series, trend200: pd.Series, price: pd.DataFrame,
                          cfg: Config = CFG, rf_daily: Optional[pd.Series] = None,
                          haz_pct: Optional[pd.Series] = None,
                          fast_pct: Optional[pd.Series] = None,
                          recov_conf: Optional[pd.Series] = None,
                          deep_recov: Optional[pd.Series] = None,
                          struct_dd: Optional[pd.Series] = None) -> pd.DataFrame:
    """
    국면 임계값(백분위)을 격자로 바꿔가며 성과를 측정한다.
    특정 임계값에서만 좋은 결과가 나온다면 그것은 곡선맞춤(curve fitting)이다.
    -> 넓은 구간에서 고르게 개선되는지 확인하는 것이 목적.

    [v1.3.0 §4(C)] haz_pct(위험/해저드 점수 백분위, run()에서 이미 계산된 값을 재사용 —
    walk-forward 자체를 다시 하지 않으므로 저비용)가 주어지고 cfg.USE_HAZARD_TRACK=True이면
    같은 시트에 HAZARD_ENTER×HAZARD_BLOCK 격자도 이어붙인다. PCT_RISK_OFF/ON은 이 격자에서는
    cfg 기본값으로 고정(둘을 동시에 격자화하면 조합이 폭증하고, 목적도 다르다 — 이쪽은
    "위험 트랙 임계값이 특정 값에서만 좋은가"를 보는 것). [v1.7.0 §A] HAZARD_NEUTRAL_FLOOR
    단독 민감도(4케이스), [v1.8.0 §B] BUY_HOLD_GATE_THRESHOLD 단독 민감도(4케이스,
    cfg.USE_BUY_HOLD_GATE=True일 때만), [v1.10.0 §A] FAST_TRIGGER_PCT 단독 민감도(4케이스
    + 발동 후 21일 수익 기반 오탐률, cfg.USE_FAST_TRIGGER=True & fast_pct 제공 시),
    [v1.11.0 §A] RECOVERY_CONFIRM_PCT 단독 민감도(4케이스, cfg.USE_RECOVERY_FLOOR=True 시),
    [v1.12.0 §A] TREND_PROMOTION_MIN_SCORE_PCT 단독 민감도(4케이스, cfg.USE_TREND_PROMOTION=
    True 시)도 이어붙인다.
    """
    t0 = time.time()
    rows = []
    for off in [0.10, 0.15, 0.20, 0.25, 0.30, 0.35]:
        for on in [0.40, 0.50, 0.60, 0.70]:
            if on <= off:
                continue
            c = Config(**{**cfg.__dict__, "PCT_RISK_OFF": off, "PCT_RISK_ON": on})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            rows.append({
                "위험회피 백분위(<)": off, "위험선호 백분위(>)": on,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "기본설정": "★" if (abs(off - cfg.PCT_RISK_OFF) < 1e-9 and
                                    abs(on - cfg.PCT_RISK_ON) < 1e-9) else "",
            })
    df = pd.DataFrame(rows)
    log("VALIDATE", kv(event="threshold_sensitivity", combos=len(df),
                       sharpe_min=float(df["샤프"].min()), sharpe_med=float(df["샤프"].median()),
                       sharpe_max=float(df["샤프"].max()),
                       elapsed_s=round(time.time() - t0, 2)))

    # [v1.3.0 §4(C)] 위험(해저드) 임계값 격자 — 같은 06c 시트에 추가 컬럼으로 이어붙인다.
    if cfg.USE_HAZARD_TRACK and haz_pct is not None:
        # [v1.4.0 §6-2] "해저드 규칙으로 상태가 실제 바뀐 일수" 컬럼의 기준선(base) — 위험트랙을
        # 완전히 끈(haz_pct=None) 상태의 국면(state)을 1회만 계산해둔다. 이 격자는 PCT_RISK_ON/
        # OFF 등 나머지 파라미터를 cfg 고정값으로 두고 HAZARD_ENTER/BLOCK만 바꾸므로(위 docstring
        # 명시) base는 조합과 무관하게 동일 — 20개 조합마다 다시 계산할 이유가 없다(성능·
        # 정확성 모두). 목적: HAZARD_ENTER×BLOCK 조합이 실제로 국면을 몇 일이나 바꿨는지를
        # 격자만 보고 바로 알 수 있게 해서, "성과지표는 그대로인데 사실 규칙이 한 번도 발동하지
        # 않았다"는 식의 죽은 규칙을 조용히 넘기지 않게 한다(§0/§3 진단: HAZARD_ENTER가
        # 0.85~0.95 전 구간에서 MDD가 전혀 바뀌지 않았던 사례가 실제로 있었음).
        sg_base = generate_signals(score_pct, trend200, cfg, haz_pct=None, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
        base_state = sg_base["state"]
        base_state = base_state.loc[base_state.index >= pd.Timestamp(cfg.SIGNAL_START)]

        haz_rows = []
        for enter in [0.75, 0.80, 0.85, 0.90, 0.95]:
            for block in [0.55, 0.60, 0.65, 0.70, 0.75]:
                if block >= enter:
                    continue
                c = Config(**{**cfg.__dict__, "HAZARD_ENTER": enter, "HAZARD_BLOCK": block})
                sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
                b = run_backtest(price, sg["target_pos"], c, rf_daily)
                b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
                m = perf_metrics(b["strategy_ret"])
                cur_state = sg["state"].loc[sg["state"].index >= pd.Timestamp(cfg.SIGNAL_START)]
                n_state_changed = int((cur_state.reindex(base_state.index) !=
                                       base_state).sum())
                haz_rows.append({
                    "HAZARD_ENTER": enter, "HAZARD_BLOCK": block,
                    "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                    "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                    "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                    "거래횟수": int((b["turnover"] > 1e-9).sum()),
                    # [v1.4.0 §6-2] 위험트랙 미적용(base) 대비 국면이 실제로 달라진 일수.
                    # 0(또는 매우 작음)이면 이 (enter, block) 조합이 이 구간에서 사실상
                    # 발동하지 않았다는 뜻 — 성과지표(CAGR/MDD 등)가 기본설정과 동일해도
                    # "죽은 규칙"인지 이 컬럼으로 바로 확인 가능.
                    "상태변경일수(vs미적용)": n_state_changed,
                    "기본설정": "★" if (abs(enter - cfg.HAZARD_ENTER) < 1e-9 and
                                        abs(block - cfg.HAZARD_BLOCK) < 1e-9) else "",
                })
        if haz_rows:
            df_haz = pd.DataFrame(haz_rows)
            sh = pd.to_numeric(df_haz["샤프"], errors="coerce")
            log("VALIDATE", kv(event="hazard_threshold_sensitivity", combos=len(df_haz),
                               sharpe_min=float(sh.min()) if sh.notna().any() else -99,
                               sharpe_max=float(sh.max()) if sh.notna().any() else -99,
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_haz], ignore_index=True, sort=False)

        # [v1.7.0 §A] HAZARD_NEUTRAL_FLOOR 단독 민감도 — v1.7.0에서 0.50→0.70으로 바꾼
        # 안전판 임계값이 특정 값에서만 좋은 것인지(곡선맞춤 여부)를 다음 실행부터 실측으로
        # 확인할 수 있게 한다. ENTER/BLOCK 격자와 동일하게 나머지 파라미터는 cfg 고정,
        # 상태변경일수(vs미적용)는 위에서 이미 계산한 base_state를 재사용(동일 근거: base는
        # 위험트랙 완전 미적용 상태라 floor 값과 무관).
        floor_rows = []
        for floor in [0.50, 0.60, 0.70, 0.80]:
            c = Config(**{**cfg.__dict__, "HAZARD_NEUTRAL_FLOOR": floor})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            cur_state = sg["state"].loc[sg["state"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            n_state_changed = int((cur_state.reindex(base_state.index) != base_state).sum())
            floor_rows.append({
                "HAZARD_NEUTRAL_FLOOR": floor,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "상태변경일수(vs미적용)": n_state_changed,
                "기본설정": "★" if abs(floor - cfg.HAZARD_NEUTRAL_FLOOR) < 1e-9 else "",
            })
        if floor_rows:
            df_floor = pd.DataFrame(floor_rows)
            shf = pd.to_numeric(df_floor["샤프"], errors="coerce")
            log("VALIDATE", kv(event="hazard_floor_sensitivity", combos=len(df_floor),
                               sharpe_min=float(shf.min()) if shf.notna().any() else -99,
                               sharpe_max=float(shf.max()) if shf.notna().any() else -99,
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_floor], ignore_index=True, sort=False)

        # [v1.8.0 §B] 매수보류게이트 임계값(BUY_HOLD_GATE_THRESHOLD) 단독 민감도 —
        # IMPROVEMENT_PLAN_v1.8.md §B-1이 명시적으로 요구한 BLOCK(0.70)/0.75/0.80/ENTER(0.85)
        # 4케이스. 기준선(gate_base_state)은 위 ENTER×BLOCK/FLOOR 격자의 base_state(위험트랙
        # 완전 미적용)와는 분리한다 — 이 게이트만 끈(USE_BUY_HOLD_GATE=False) 상태를 기준선으로
        # 써야 ENTER/BLOCK/FLOOR 등 나머지 위험트랙 메커니즘 효과와 섞이지 않고 B-1 자체의
        # 순수 효과(상태변경일수·게이트발동일수)만 분리해 볼 수 있다. "지연으로 잃는 상승분
        # vs 회피하는 휩쏘"를 실측하기 위한 것이며, 특정 값이 성과가 가장 좋다고 해서 그 값을
        # 그대로 채택하지 않는다(§9 격자 최적 셀 채택 금지 — 이번 라운드 기본값 0.70은 어디까지나
        # HAZARD_BLOCK과의 의미론 통일이 근거).
        if cfg.USE_BUY_HOLD_GATE:
            cfg_gate_off = Config(**{**cfg.__dict__, "USE_BUY_HOLD_GATE": False})
            sg_gate_base = generate_signals(score_pct, trend200, cfg_gate_off, haz_pct=haz_pct, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            gate_base_state = sg_gate_base["state"]
            gate_base_state = gate_base_state.loc[gate_base_state.index >= pd.Timestamp(cfg.SIGNAL_START)]

            gate_rows = []
            for gth in [0.70, 0.75, 0.80, 0.85]:
                c = Config(**{**cfg.__dict__, "BUY_HOLD_GATE_THRESHOLD": gth})
                sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
                b = run_backtest(price, sg["target_pos"], c, rf_daily)
                b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
                m = perf_metrics(b["strategy_ret"])
                cur_state = sg["state"].loc[sg["state"].index >= pd.Timestamp(cfg.SIGNAL_START)]
                n_state_changed = int((cur_state.reindex(gate_base_state.index) != gate_base_state).sum())
                sig_gate = sg["buy_hold_gate"].loc[sg["buy_hold_gate"].index >= pd.Timestamp(cfg.SIGNAL_START)]
                gate_rows.append({
                    "BUY_HOLD_GATE_THRESHOLD": gth,
                    "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                    "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                    "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                    "거래횟수": int((b["turnover"] > 1e-9).sum()),
                    "상태변경일수(vs게이트끔)": n_state_changed,
                    "게이트발동일수": int(sig_gate.sum()),
                    "기본설정": "★" if abs(gth - cfg.BUY_HOLD_GATE_THRESHOLD) < 1e-9 else "",
                })
            if gate_rows:
                df_gate = pd.DataFrame(gate_rows)
                shg = pd.to_numeric(df_gate["샤프"], errors="coerce")
                log("VALIDATE", kv(event="buy_hold_gate_sensitivity", combos=len(df_gate),
                                   sharpe_min=float(shg.min()) if shg.notna().any() else -99,
                                   sharpe_max=float(shg.max()) if shg.notna().any() else -99,
                                   elapsed_s=round(time.time() - t0, 2)))
                df = pd.concat([df, df_gate], ignore_index=True, sort=False)

    # [v1.10.0 §A] 급락 fast-trigger 임계값(FAST_TRIGGER_PCT) 단독 민감도 — 위험트랙 블록
    # 밖에 둔다(트리거는 합성 H와 독립 메커니즘). 기준선은 트리거만 끈(USE_FAST_TRIGGER=False)
    # 상태로, 나머지 규칙(①~④) 효과와 분리해 트리거의 순수 효과만 본다. 오탐률 컬럼:
    # 발동일 이후 21거래일 시장수익의 중앙값과 양(+)수익 비율 — 트리거가 "진짜 급락"을 잡는지
    # "괜히 파는지"를 실측(사후 진단용 forward 통계 — 신호에 재사용되지 않음, 룩어헤드 무관).
    if cfg.USE_FAST_TRIGGER and fast_pct is not None:
        cfg_ft_off = Config(**{**cfg.__dict__, "USE_FAST_TRIGGER": False})
        sg_ft_base = generate_signals(score_pct, trend200, cfg_ft_off, haz_pct=haz_pct,
                                      fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
        ft_base_state = sg_ft_base["state"]
        ft_base_state = ft_base_state.loc[ft_base_state.index >= pd.Timestamp(cfg.SIGNAL_START)]
        adj_col = "Adj Close" if "Adj Close" in price.columns else "Close"
        fwd21 = price[adj_col].pct_change(21).shift(-21)   # 발동일 기준 이후 21일 수익(진단용)

        ft_rows = []
        for fpct in [0.90, 0.95, 0.97, 0.99]:
            c = Config(**{**cfg.__dict__, "FAST_TRIGGER_PCT": fpct})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            cur_state = sg["state"].loc[sg["state"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            n_state_changed = int((cur_state.reindex(ft_base_state.index) != ft_base_state).sum())
            fire = sg["fast_trigger"].loc[sg["fast_trigger"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            fire_dates = fire[fire].index
            fw = fwd21.reindex(fire_dates).dropna()
            ft_rows.append({
                "FAST_TRIGGER_PCT": fpct,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "상태변경일수(vs트리거끔)": n_state_changed,
                "트리거발동일수": int(fire.sum()),
                "발동후21일수익중앙값(%)": round(float(fw.median()) * 100, 2) if len(fw) else np.nan,
                "발동후21일수익양수비율": round(float((fw > 0).mean()), 2) if len(fw) else np.nan,
                "기본설정": "★" if abs(fpct - cfg.FAST_TRIGGER_PCT) < 1e-9 else "",
            })
        if ft_rows:
            df_ft = pd.DataFrame(ft_rows)
            shf2 = pd.to_numeric(df_ft["샤프"], errors="coerce")
            log("VALIDATE", kv(event="fast_trigger_sensitivity", combos=len(df_ft),
                               sharpe_min=float(shf2.min()) if shf2.notna().any() else -99,
                               sharpe_max=float(shf2.max()) if shf2.notna().any() else -99,
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_ft], ignore_index=True, sort=False)

    # [v1.11.0 §A] 회복 승격 확인폭(RECOVERY_CONFIRM_PCT) 단독 민감도 — 확인폭이 특정 값에서만
    # 좋은지(곡선맞춤 여부) + 2022년형 베어랠리 오탐 비용을 실측한다. 각 케이스마다 recov_conf
    # 불리언을 그 확인폭으로 재계산(창은 cfg.RECOVERY_LOW_WINDOW 고정 — 두 파라미터 동시
    # 격자화는 조합 폭증, §9 관례대로 핵심 축 하나만). 기준선은 규칙 ⑤만 끈 상태.
    if cfg.USE_RECOVERY_FLOOR:
        cfg_rf_off = Config(**{**cfg.__dict__, "USE_RECOVERY_FLOOR": False})
        sg_rf_base = generate_signals(score_pct, trend200, cfg_rf_off, haz_pct=haz_pct,
                                      fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
        rf_base_state = sg_rf_base["state"]
        rf_base_state = rf_base_state.loc[rf_base_state.index >= pd.Timestamp(cfg.SIGNAL_START)]
        _close = price["Close"].astype(float)
        _roll_low = _close.rolling(cfg.RECOVERY_LOW_WINDOW, min_periods=20).min()

        rf_rows = []
        for cpct in [0.03, 0.05, 0.07, 0.10]:
            rc = (_close >= _roll_low * (1.0 + cpct))
            c = Config(**{**cfg.__dict__, "RECOVERY_CONFIRM_PCT": cpct})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct,
                                  fast_pct=fast_pct, recov_conf=rc, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            cur_state = sg["state"].loc[sg["state"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            n_state_changed = int((cur_state.reindex(rf_base_state.index) != rf_base_state).sum())
            rfire = sg["recovery_floor"].loc[sg["recovery_floor"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            rf_rows.append({
                "RECOVERY_CONFIRM_PCT": cpct,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "상태변경일수(vs규칙끔)": n_state_changed,
                "회복승격일수": int(rfire.sum()),
                "기본설정": "★" if abs(cpct - cfg.RECOVERY_CONFIRM_PCT) < 1e-9 else "",
            })
        if rf_rows:
            df_rf = pd.DataFrame(rf_rows)
            shr = pd.to_numeric(df_rf["샤프"], errors="coerce")
            log("VALIDATE", kv(event="recovery_floor_sensitivity", combos=len(df_rf),
                               sharpe_min=float(shr.min()) if shr.notna().any() else -99,
                               sharpe_max=float(shr.max()) if shr.notna().any() else -99,
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_rf], ignore_index=True, sort=False)

    # [v1.12.0 §A] 추세 승격 점수하한(TREND_PROMOTION_MIN_SCORE_PCT) 단독 민감도 — 하한이
    # 특정 값에서만 좋은지 + 하한을 낮출 때 2022년형 방어 훼손이 언제 시작되는지 실측.
    # 기준선은 규칙 ⑥만 끈 상태(위험트랙·트리거·회복승격은 그대로).
    if cfg.USE_TREND_PROMOTION and cfg.USE_HAZARD_TRACK and haz_pct is not None:
        cfg_tp_off = Config(**{**cfg.__dict__, "USE_TREND_PROMOTION": False})
        sg_tp_base = generate_signals(score_pct, trend200, cfg_tp_off, haz_pct=haz_pct,
                                      fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
        tp_base_state = sg_tp_base["state"]
        tp_base_state = tp_base_state.loc[tp_base_state.index >= pd.Timestamp(cfg.SIGNAL_START)]

        tp_rows = []
        for msp in [0.25, 0.30, 0.35, 0.40]:
            c = Config(**{**cfg.__dict__, "TREND_PROMOTION_MIN_SCORE_PCT": msp})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct,
                                  fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            cur_state = sg["state"].loc[sg["state"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            n_state_changed = int((cur_state.reindex(tp_base_state.index) != tp_base_state).sum())
            tfire = sg["trend_promotion"].loc[sg["trend_promotion"].index >= pd.Timestamp(cfg.SIGNAL_START)]
            tp_rows.append({
                "TREND_PROMOTION_MIN_SCORE_PCT": msp,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "상태변경일수(vs승격끔)": n_state_changed,
                "추세승격일수": int(tfire.sum()),
                "기본설정": "★" if abs(msp - cfg.TREND_PROMOTION_MIN_SCORE_PCT) < 1e-9 else "",
            })
        if tp_rows:
            df_tp = pd.DataFrame(tp_rows)
            sht = pd.to_numeric(df_tp["샤프"], errors="coerce")
            log("VALIDATE", kv(event="trend_promotion_sensitivity", combos=len(df_tp),
                               sharpe_min=float(sht.min()) if sht.notna().any() else -99,
                               sharpe_max=float(sht.max()) if sht.notna().any() else -99,
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_tp], ignore_index=True, sort=False)

        # [v1.13.0 §D] 보류 메커니즘 3종 확인 격자 — 리플레이 실증에서 기각/보류된 (a) 비대칭
        # 히스테리시스(A-3), (b) 추세승격 H 상한 완화, (c) ΔH 속도 경보(A-2)를 실데이터
        # 전체 파이프라인에서도 같은 결론이 나오는지 사후 확인한다. 전부 기본 비활성이므로
        # 이 격자는 순수 진단이며 라이브 신호에 영향 없음.
        held_rows = []
        # [v1.17.0 §B] 소프트 트리거 캡(FT>0.93 → 중립 상한) 행 추가 — "중간 규모 하락 회피"
        # 요청의 후보 중 유일하게 비용이 ~0인 것을 매 실행 실측(-1% 손실일 수도 함께 기록).
        held_cases = [
            ("기준(전부 기본값)", {}),
            ("A-3 비대칭(1일+면제)", {"USE_ASYM_HYSTERESIS": True}),
            ("승격 H상한 0.85", {"TREND_PROMOTION_MAX_H": 0.85}),
            ("A-2 ΔH경보(15d,0.40)", {"USE_HAZARD_VELOCITY": True}),
            (f"소프트 트리거 캡(FT>{cfg.SOFT_TRIGGER_PCT:.2f}→0.5)", {"USE_SOFT_TRIGGER_CAP": True}),
            # [v1.18.0 §A] 규칙 ⑧ 구조적 저점 확인 승격 + MDD 우선 참고(전 비중 ×0.75)
            (f"⑧ 구조적 저점 확인({cfg.STRUCT_BOTTOM_DD:.0%}, H<{cfg.STRUCT_BOTTOM_MAX_H:.2f})",
             {"USE_STRUCT_BOTTOM_PROMOTION": True}),
            ("전 비중 ×0.75 (MDD 우선 참고)", {"POS_RISK_ON": cfg.POS_RISK_ON * 0.75,
                                            "POS_NEUTRAL": cfg.POS_NEUTRAL * 0.75}),
            # [v1.19.0 §B] 이력현상 교대-잠금 수정(기본 비활성)
            ("이력현상 교대-잠금 수정", {"USE_ALTERNATION_FIX": True}),
            # [v1.20.0 §D] 규칙 ⑩ 위에 얹은 1차 실증 후보: ⑧ 구조적 저점 확인의 H 상한을 0.50으로 조인 변형
            # (report21/15 리플레이: CAGR +0.3pp·칼마↑·MDD 동일, 샤프 -0.01·손실일 +8·2022 -0.9pp — 2차 실증 대기).
            (f"⑧ 구조적 저점 확인({cfg.STRUCT_BOTTOM_DD:.0%}, H<0.50) [1차 실증]",
             {"USE_STRUCT_BOTTOM_PROMOTION": True, "STRUCT_BOTTOM_MAX_H": 0.50}),
        ]
        for lab, over in held_cases:
            c = Config(**{**cfg.__dict__, **over})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct,
                                  fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            is_live = all(getattr(cfg, k) == v for k, v in over.items())
            held_rows.append({
                "보류메커니즘 확인": lab,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "-1%손실일수": int((b["strategy_ret"] < -0.01).sum()),   # [v1.17.0 §B]
                "기본설정": "★" if not over else ("(=라이브)" if is_live else ""),
            })
        if held_rows:
            df_hd = pd.DataFrame(held_rows)
            log("VALIDATE", kv(event="held_mechanisms_check", combos=len(df_hd),
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_hd], ignore_index=True, sort=False)

        # [v1.19.0 §A] 규칙 ⑨ 중립 위험감축 단독 민감도 — off / 0.25@0.70 / 0.0@0.70 / 0.0@0.75 / 0.0@0.80.
        # 라이브와 같은 케이스에 ★. 어떤 행도 라이브 신호에 영향을 주지 않는다(재시뮬레이션 전용).
        if haz_pct is not None:
            nc_rows = []
            nc_cases = [(False, cfg.NEUTRAL_RISK_CUT_H, cfg.POS_NEUTRAL_HIGH_H, "off(중립 0.5 유지)"),
                        (True, 0.70, 0.25, "0.25 @ H>0.70"), (True, 0.70, 0.0, "0.0 @ H>0.70"),
                        (True, 0.75, 0.0, "0.0 @ H>0.75"), (True, 0.80, 0.0, "0.0 @ H>0.80")]
            for use, th, lvl, label in nc_cases:
                c = Config(**{**cfg.__dict__, "USE_NEUTRAL_RISK_CUT": use,
                              "NEUTRAL_RISK_CUT_H": th, "POS_NEUTRAL_HIGH_H": lvl})
                sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct,
                                      recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
                b = run_backtest(price, sg["target_pos"], c, rf_daily)
                b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
                m = perf_metrics(b["strategy_ret"])
                is_live = (use == cfg.USE_NEUTRAL_RISK_CUT and
                           (not use or (abs(th - cfg.NEUTRAL_RISK_CUT_H) < 1e-9 and
                                        abs(lvl - cfg.POS_NEUTRAL_HIGH_H) < 1e-9)))
                nc_rows.append({
                    "NEUTRAL_RISK_CUT": label,
                    "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                    "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                    "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                    "거래횟수": int((b["turnover"] > 1e-9).sum()),
                    "-1%손실일수": int((b["strategy_ret"] < -0.01).sum()),
                    "감축발동일수": int(sg["neutral_risk_cut"].loc[sg.index >= pd.Timestamp(cfg.SIGNAL_START)].sum()),
                    "기본설정": "★" if is_live else "",
                })
            if nc_rows:
                df_nc = pd.DataFrame(nc_rows)
                log("VALIDATE", kv(event="neutral_risk_cut_sensitivity", combos=len(df_nc),
                                   elapsed_s=round(time.time() - t0, 2)))
                df = pd.concat([df, df_nc], ignore_index=True, sort=False)

        # [v1.20.0 §C] 규칙 ⑩ 과열 헤어컷 단독 민감도 — off / E1(0.9/0.8) / E3(0.8/0.6, 라이브) / E5(0.7/0.5) /
        # 0.1 사다리(+10.5%부터 0.5%p당 -0.1, 바닥 0.4) / E3 평활 없음. 라이브와 같은 케이스에 ★.
        # 어떤 행도 라이브 신호에 영향을 주지 않는다(재시뮬레이션 전용). trend200만 쓰므로 위험트랙 유무와 무관.
        eh_rows = []
        ladder = tuple((round(0.105 + 0.005 * i, 3), round(0.9 - 0.1 * i, 1)) for i in range(6))  # 0.9…0.4
        eh_cases = [(False, cfg.EXTENSION_HAIRCUT_STEPS, cfg.EXTENSION_HAIRCUT_SMOOTH, "off(상한 없음)"),
                    (True, ((0.10, 0.9), (0.12, 0.8)), cfg.EXTENSION_HAIRCUT_SMOOTH, "E1: ≥10%→0.9, ≥12%→0.8"),
                    (True, ((0.10, 0.8), (0.12, 0.6)), cfg.EXTENSION_HAIRCUT_SMOOTH, "E3: ≥10%→0.8, ≥12%→0.6"),
                    (True, ((0.10, 0.7), (0.12, 0.5)), cfg.EXTENSION_HAIRCUT_SMOOTH, "E5: ≥10%→0.7, ≥12%→0.5"),
                    (True, ladder, cfg.EXTENSION_HAIRCUT_SMOOTH, "사다리: ≥10.5%부터 0.5%p당 -0.1(바닥 0.4)"),
                    (True, ((0.10, 0.8), (0.12, 0.6)), 1, "E3 평활 없음(당일값)")]
        for use, steps, sm, label in eh_cases:
            c = Config(**{**cfg.__dict__, "USE_EXTENSION_HAIRCUT": use,
                          "EXTENSION_HAIRCUT_STEPS": tuple(steps), "EXTENSION_HAIRCUT_SMOOTH": sm})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct,
                                  recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            is_live = (use == cfg.USE_EXTENSION_HAIRCUT and
                       (not use or (tuple(steps) == tuple(cfg.EXTENSION_HAIRCUT_STEPS)
                                    and sm == cfg.EXTENSION_HAIRCUT_SMOOTH)))
            eh_rows.append({
                "EXTENSION_HAIRCUT": label,
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "평균비중": round(float(b["pos_exec"].mean()), 3),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "-1%손실일수": int((b["strategy_ret"] < -0.01).sum()),
                "헤어컷발동일수": int(sg["extension_haircut"].loc[sg.index >= pd.Timestamp(cfg.SIGNAL_START)].sum()),
                "기본설정": "★" if is_live else "",
            })
        if eh_rows:
            df_eh = pd.DataFrame(eh_rows)
            log("VALIDATE", kv(event="extension_haircut_sensitivity", combos=len(df_eh),
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_eh], ignore_index=True, sort=False)

        # [v1.21.0 §C] 레버리지 사다리(규칙 ⑪) 격자 — 기본 비활성이므로 순수 정보(사용자 목표 "B&H 2배"의 대가를
        # 매 실행 실측). off★ / M1.3 / M1.3+회복 1.5 / 전 비중 ×1.5. 조달비용은 run_backtest가 rf+스프레드로 부과.
        lv_rows = []
        lv_cases = [("off(상한 1.0)★" if not cfg.USE_LEVERAGE else "off(상한 1.0)", {"USE_LEVERAGE": False}),
                    ("저위험 1.3 (이격≤7%·H≤0.5)", {"USE_LEVERAGE": True, "LEVERAGE_RECOVERY_POS": 1.3, "LEVERAGE_LOW_RISK_POS": 1.3}),
                    ("저위험 1.3 + 급락 후 회복진입 1.5", {"USE_LEVERAGE": True, "LEVERAGE_LOW_RISK_POS": 1.3, "LEVERAGE_RECOVERY_POS": 1.5}),
                    ("전 비중 ×1.5 (일괄)", {"USE_LEVERAGE": False, "POS_RISK_ON": cfg.POS_RISK_ON * 1.5, "POS_NEUTRAL": cfg.POS_NEUTRAL * 1.5,
                                         "EXTENSION_HAIRCUT_STEPS": tuple((t, round(c * 1.5, 2)) for t, c in cfg.EXTENSION_HAIRCUT_STEPS)})]
        for label, over in lv_cases:
            c = Config(**{**cfg.__dict__, **over})
            sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct, fast_pct=fast_pct,
                                  recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
            b = run_backtest(price, sg["target_pos"], c, rf_daily)
            b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
            m = perf_metrics(b["strategy_ret"])
            is_live = all(getattr(cfg, k) == v for k, v in over.items())
            lv_rows.append({
                "LEVERAGE": label.replace("★", ""),
                "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                "평균비중": round(float(b["pos_exec"].mean()), 3),
                "최대비중": round(float(b["pos_exec"].max()), 2),
                "거래횟수": int((b["turnover"] > 1e-9).sum()),
                "-1%손실일수": int((b["strategy_ret"] < -0.01).sum()),
                "총수익배수": round(float(b["equity"].iloc[-1] / b["equity"].iloc[0]), 3),
                "기본설정": "★" if is_live else "",
            })
        if lv_rows:
            df_lv = pd.DataFrame(lv_rows)
            log("VALIDATE", kv(event="leverage_sensitivity", combos=len(df_lv),
                               elapsed_s=round(time.time() - t0, 2)))
            df = pd.concat([df, df_lv], ignore_index=True, sort=False)

        # [v1.15.0 §A] 깊은 낙폭 회복 풀매수(규칙 ⑦) 단독 민감도 — off/-0.12/-0.15/-0.20.
        # 리플레이에서 -12/-15%는 2022 방어를 훼손해 기각됐음을 실데이터에서도 재확인하는 용도.
        # [v1.15.1 §B] 기본값(USE_DEEP_RECOVERY_BOOST)과 무관하게 항상 산출 — 기본 비활성으로
        # 되돌린 뒤에도 매 실행 실데이터 실측을 쌓아 재활성 근거로 쓴다(A-2·카테고리 상한과
        # 같은 "보류 메커니즘 확인" 방식). off 행이 라이브(기본 비활성)와 동일 케이스다.
        # [v1.16.0 §A] 격자 케이스를 (임계값, 낙폭정의, 점수가드)로 확장 — 앞 4행은 라이브 정의
        # (고점→저점 + 점수가드)로 off/-12/-15/-20%, 마지막 2행은 report17 06c와의 연속성을 위한
        # 참고행(v1.15 정의: 임의순서 min/max, 점수가드 없음 / 고점→저점 정의에 점수가드만 없음).
        # 라이브와 같은 케이스에 ★. 어떤 행도 라이브 신호에 영향을 주지 않는다(재시뮬레이션 전용).
        if recov_conf is not None:
            _cl = price["Close"].astype(float)
            dr_rows = []
            live_mode, live_guard = cfg.DEEP_RECOVERY_DD_MODE, cfg.DEEP_RECOVERY_SCORE_GUARD
            cases = [(None, live_mode, live_guard, "off(부스트 없음)")]
            cases += [(t, live_mode, live_guard, f"{t:.0%}") for t in (-0.12, -0.15, -0.20)]
            cases += [(cfg.DEEP_RECOVERY_DD, "range", False,
                       f"{cfg.DEEP_RECOVERY_DD:.0%} [참고: v1.15 정의(임의순서)+가드없음]"),
                      (cfg.DEEP_RECOVERY_DD, "peak_to_trough", False,
                       f"{cfg.DEEP_RECOVERY_DD:.0%} [참고: 고점→저점, 가드없음]")]
            for dd_th, mode, guard, label in cases:
                if dd_th is None:
                    c = Config(**{**cfg.__dict__, "USE_DEEP_RECOVERY_BOOST": False})
                    dr_case = None
                else:
                    c = Config(**{**cfg.__dict__, "USE_DEEP_RECOVERY_BOOST": True,
                                  "DEEP_RECOVERY_DD": dd_th, "DEEP_RECOVERY_DD_MODE": mode,
                                  "DEEP_RECOVERY_SCORE_GUARD": guard})
                    dr_case = recov_conf & deep_drawdown_flag(_cl, dd_th, cfg.RECOVERY_LOW_WINDOW, mode)
                sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct,
                                      fast_pct=fast_pct, recov_conf=recov_conf,
                                      deep_recov=dr_case)
                b = run_backtest(price, sg["target_pos"], c, rf_daily)
                b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
                m = perf_metrics(b["strategy_ret"])
                dfire = sg["deep_recovery"].loc[sg["deep_recovery"].index >= pd.Timestamp(cfg.SIGNAL_START)]
                is_live = ((dd_th is None and not cfg.USE_DEEP_RECOVERY_BOOST) or
                           (dd_th is not None and cfg.USE_DEEP_RECOVERY_BOOST and
                            abs(dd_th - cfg.DEEP_RECOVERY_DD) < 1e-9 and
                            mode == live_mode and guard == live_guard))
                dr_rows.append({
                    "DEEP_RECOVERY_DD": label,
                    "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
                    "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
                    "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
                    "거래횟수": int((b["turnover"] > 1e-9).sum()),
                    "부스트발동일수": int(dfire.sum()),
                    "기본설정": "★" if is_live else "",
                })
            if dr_rows:
                df_dr = pd.DataFrame(dr_rows)
                log("VALIDATE", kv(event="deep_recovery_sensitivity", combos=len(df_dr),
                                   elapsed_s=round(time.time() - t0, 2)))
                df = pd.concat([df, df_dr], ignore_index=True, sort=False)
    return df


def hazard_cap_sensitivity(vt_periods: List[dict], ind: pd.DataFrame,
                           score_pct: pd.Series, trend200: pd.Series, price: pd.DataFrame,
                           cfg: Config = CFG, rf_daily: Optional[pd.Series] = None,
                           fast_pct: Optional[pd.Series] = None,
                           recov_conf: Optional[pd.Series] = None,
                           deep_recov: Optional[pd.Series] = None,
                           struct_dd: Optional[pd.Series] = None,
                           sig_mask: Optional[pd.Series] = None,
                           W_haz_live: Optional[pd.DataFrame] = None) -> pd.DataFrame:
    """
    [v1.14.0 §B] 위험트랙 카테고리 가중 상한(HAZARD_CATEGORY_WEIGHT_CAP) 저비용 민감도.
    walk-forward가 수집해 둔 재추정별 검증표 캐시(vt_periods)로 위험트랙 '재선정'만 케이스별로
    다시 수행한다 — 비용 지배 요인인 validate_indicators() 재실행이 없어 케이스당 수 초.
    각 케이스: W_haz 재구축 → H 합성 → 백분위 → 신호 → 백테스트 → 성과.

    무제한(None) 케이스는 라이브 W_haz와 비트 단위로 같아야 한다 — W_haz_live가 주어지면 이를
    검증해 재시뮬레이션 자체의 충실도를 매 실행 자기검증한다(불일치 시 경고 로그, 진단 계속).
    """
    t0 = time.time()
    if not vt_periods or not cfg.USE_HAZARD_TRACK:
        return pd.DataFrame()
    idx = ind.index
    keys = [s.key for s in INDICATOR_SPECS]
    sig_mask_s = sig_mask if sig_mask is not None else pd.Series(True, index=idx)

    rows = []
    for cap in [None, 0.50, 0.40, 0.30]:
        c = Config(**{**cfg.__dict__, "HAZARD_CATEGORY_WEIGHT_CAP": cap})
        W_haz_case = pd.DataFrame(0.0, index=idx, columns=keys)
        prev: Optional[Tuple[np.ndarray, np.ndarray]] = None
        n_cap_fired = 0
        for entry in vt_periods:
            mask, vt = entry["mask"], entry["vt"]
            if vt is None:                      # 직전 가중치 유지 구간(N_eff 스킵)
                if prev is not None:
                    for k, w in zip(prev[0], prev[1]):
                        W_haz_case.loc[mask, k] = float(w)
                continue
            codes_h, w_h, info_h = _select_and_weight_hazard_period(vt, c)
            if codes_h is not None:
                for k, w in zip(codes_h, w_h):
                    W_haz_case.loc[mask, k] = float(w)
                prev = (codes_h, w_h)
                if info_h.get("category_cap_applied"):
                    n_cap_fired += 1
            else:
                prev = None

        if cap is None and W_haz_live is not None:
            if not np.allclose(W_haz_case.values, W_haz_live.values, atol=1e-12):
                log("VALIDATE", kv(event="hazard_cap_resim_mismatch",
                                   note="무제한 케이스가 라이브 W_haz와 불일치 — 재시뮬 충실도 확인 필요"),
                    "warning")
            else:
                log("VALIDATE", kv(event="hazard_cap_resim_fidelity_ok"))

        haz_score_c, _, _ = composite_score(ind, W_haz_case, c)
        haz_pct_c = score_percentile(haz_score_c).where(sig_mask_s)
        sg = generate_signals(score_pct, trend200, c, haz_pct=haz_pct_c,
                              fast_pct=fast_pct, recov_conf=recov_conf, deep_recov=deep_recov, struct_dd=struct_dd)
        b = run_backtest(price, sg["target_pos"], c, rf_daily)
        b = b.loc[b.index >= pd.Timestamp(cfg.SIGNAL_START)]
        m = perf_metrics(b["strategy_ret"])
        rows.append({
            "위험트랙 카테고리 상한": "무제한(현행)" if cap is None else f"{cap:.2f}",
            "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
            "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
            "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
            "거래횟수": int((b["turnover"] > 1e-9).sum()),
            "상한발동 재추정수": n_cap_fired,
            "기본설정": "★" if cap == cfg.HAZARD_CATEGORY_WEIGHT_CAP else "",
        })
    df = pd.DataFrame(rows)
    log("VALIDATE", kv(event="hazard_cap_sensitivity", combos=len(df),
                       elapsed_s=round(time.time() - t0, 2)))
    return df


def half_life_sensitivity(ind: pd.DataFrame, px_adj: pd.Series, price: pd.DataFrame,
                          trend200: pd.Series, cfg: Config = CFG,
                          rf_daily: Optional[pd.Series] = None) -> pd.DataFrame:
    """
    [v1.2.0 §4.3/§5] 시간감쇠 반감기(HALF_LIFE_DAYS, 달력일 기준)를 {548일(1.5년),
    913일(2.5년, 기본), 1461일(4년), None(감쇠없음)} 4케이스로 바꿔가며 walk-forward 전체를
    재실행해 성과를 비교한다. threshold_sensitivity()와 다른 점: 그쪽은 신호/체결 파라미터만
    바뀌어 이미 계산된 복합점수를 재사용할 수 있지만, 반감기는 지표 검증·가중치 산출
    (build_walkforward_weights) 자체에 영향을 주므로 각 케이스마다 그 전체를 다시 계산해야
    한다 — 케이스 수를 4개로 제한한 것도 이 비용 때문이다(개선명세서 §4.3의 결정).
    특정 반감기에서만 성과가 두드러진다면 그 값에 대한 곡선맞춤(curve fitting)일 수 있으므로,
    넓은 범위에서 고르게 합리적인 성과가 나오는지를 스스로 점검하는 것이 목적이다.
    """
    t0 = time.time()
    idx = px_adj.index
    sig_start = pd.Timestamp(cfg.SIGNAL_START)
    sig_mask = pd.Series(idx >= sig_start, index=idx)
    cases = [548, 913, 1461, None]
    rows = []
    score_by_hl: Dict[object, pd.Series] = {}   # [v1.3.0 §7] 앙상블 계산 시 중복 재계산 방지용 캐시
    # [v1.4.0 §1(A)] 이 비교의 목적은 "반감기 간 상대적 우열"이지 정밀한 월간 재추정이
    # 아니므로, cfg.HL_SENS_REWEIGHT_FREQ(기본 "A")로 재추정 주기를 낮춰 4케이스 총 소요를
    # 줄인다(실측 4,939초 -> 약 1/4). 4케이스 모두 동일 주기를 쓰므로 케이스 간 비교의
    # 유효성 자체는 영향받지 않는다.
    log("VALIDATE", kv(event="half_life_sensitivity_start", cases=len(cases),
                       reweight_freq=cfg.HL_SENS_REWEIGHT_FREQ))
    for hl in cases:
        c = Config(**{**cfg.__dict__, "HALF_LIFE_DAYS": hl,
                      "REWEIGHT_FREQ": cfg.HL_SENS_REWEIGHT_FREQ})
        W_hl, _, _ = build_walkforward_weights(ind, px_adj, c)
        score_hl, _, _ = composite_score(ind, W_hl, c)
        score_by_hl[hl] = score_hl
        score_pct_hl = score_percentile(score_hl).where(sig_mask)
        sg = generate_signals(score_pct_hl, trend200, c, score=score_hl)
        b = run_backtest(price, sg["target_pos"], c, rf_daily)
        b = b.loc[b.index >= sig_start]
        m = perf_metrics(b["strategy_ret"])
        label = f"{hl}일(~{hl/365:.1f}년)" if hl else "감쇠없음(균등가중)"
        rows.append({
            "반감기(HALF_LIFE_DAYS)": label,
            "CAGR": m.get("CAGR"), "샤프": m.get("샤프"),
            "최대낙폭": m.get("최대낙폭(MDD)"), "칼마": m.get("칼마(CAGR/MDD)"),
            "투자시간비율": round(float((b["pos_exec"] > 0).mean()), 3),
            "거래횟수": int((b["turnover"] > 1e-9).sum()),
            "기본설정": "★" if hl == cfg.HALF_LIFE_DAYS else "",
        })
        log("VALIDATE", kv(event="half_life_case_done",
                           half_life_days=hl if hl is not None else -1,
                           cagr=m.get("CAGR"), sharpe=m.get("샤프"),
                           elapsed_s=round(time.time() - t0, 2)))

    # [v1.3.0 §7] 선택적 강건화 — 여러 반감기의 복합점수를 평균한 앙상블을 참고용으로 병기.
    # 실거래 신호 로직(run() 본경로)에는 영향을 주지 않으며, cfg.ENSEMBLE_HALF_LIVES가
    # 설정된 경우에만 계산된다(기본 None → 기존과 완전히 동일한 06d 시트).
    if cfg.ENSEMBLE_HALF_LIVES:
        ens_scores = []
        for hl in cfg.ENSEMBLE_HALF_LIVES:
            if hl in score_by_hl:
                ens_scores.append(score_by_hl[hl])
            else:
                c = Config(**{**cfg.__dict__, "HALF_LIFE_DAYS": hl,
                              "REWEIGHT_FREQ": cfg.HL_SENS_REWEIGHT_FREQ})
                W_hl, _, _ = build_walkforward_weights(ind, px_adj, c)
                score_hl, _, _ = composite_score(ind, W_hl, c)
                ens_scores.append(score_hl)
        score_ens = pd.concat(ens_scores, axis=1).mean(axis=1)
        score_pct_ens = score_percentile(score_ens).where(sig_mask)
        sg_ens = generate_signals(score_pct_ens, trend200, cfg, score=score_ens)
        b_ens = run_backtest(price, sg_ens["target_pos"], cfg, rf_daily)
        b_ens = b_ens.loc[b_ens.index >= sig_start]
        m_ens = perf_metrics(b_ens["strategy_ret"])
        ens_label = ("앙상블 평균(" +
                     "/".join(str(h) if h else "없음" for h in cfg.ENSEMBLE_HALF_LIVES) + ")")
        rows.append({
            "반감기(HALF_LIFE_DAYS)": ens_label,
            "CAGR": m_ens.get("CAGR"), "샤프": m_ens.get("샤프"),
            "최대낙폭": m_ens.get("최대낙폭(MDD)"), "칼마": m_ens.get("칼마(CAGR/MDD)"),
            "투자시간비율": round(float((b_ens["pos_exec"] > 0).mean()), 3),
            "거래횟수": int((b_ens["turnover"] > 1e-9).sum()),
            "기본설정": "",
        })
        log("VALIDATE", kv(event="half_life_ensemble_done",
                           half_lives=",".join(str(h) for h in cfg.ENSEMBLE_HALF_LIVES),
                           cagr=m_ens.get("CAGR"), sharpe=m_ens.get("샤프"),
                           elapsed_s=round(time.time() - t0, 2)))

    df = pd.DataFrame(rows)
    sharpe_vals = pd.to_numeric(df["샤프"], errors="coerce")
    log("VALIDATE", kv(event="half_life_sensitivity", cases=len(df),
                       sharpe_min=float(sharpe_vals.min()) if sharpe_vals.notna().any() else -99,
                       sharpe_max=float(sharpe_vals.max()) if sharpe_vals.notna().any() else -99,
                       elapsed_s=round(time.time() - t0, 2)))

    # [v1.3.0 §7 정직성] 기본값이 민감도 비교의 최고 성과 지점에 위치하면 선택 운
    # (data snooping) 가능성을 배제할 수 없다 — 실사용 리포트에서 913일(기본값)이 4케이스
    # 중 샤프 최고(1.601 vs 1.23~1.51)로 나온 것이 계기(IMPROVEMENT_PLAN_v1.3.md §7).
    # 이 결과를 근거로 반감기를 "더 좋게" 재튜닝하는 것은 §9에서 명시적으로 금지한다.
    try:
        default_mask = df["기본설정"] == "★"
        if default_mask.any() and sharpe_vals.notna().sum() >= 2:
            default_sharpe = pd.to_numeric(df.loc[default_mask, "샤프"], errors="coerce").iloc[0]
            if pd.notna(default_sharpe) and default_sharpe >= sharpe_vals.max() - 1e-9:
                warn_txt = ("⚠ 주의: 기본 반감기가 이 비교에서 최고 성과 — 선택 운(data snooping) "
                            "가능성 배제 불가. 이 결과로 반감기를 재튜닝하지 말 것 "
                            "(IMPROVEMENT_PLAN_v1.3.md §7/§9)")
            else:
                warn_txt = ("참고: 케이스 간 성과 격차는 전략이 반감기 선택에 민감하다는 신호 — "
                            "재튜닝 금지 원칙 유지 (IMPROVEMENT_PLAN_v1.3.md §9)")
            df = pd.concat([df, pd.DataFrame([{"반감기(HALF_LIFE_DAYS)": warn_txt}])],
                           ignore_index=True)
    except Exception as e:
        log("VALIDATE", kv(event="half_life_warning_row_skip", err=type(e).__name__), "warning")
    return df


